    template<typename ComponentType>
    void RegisterAssetRefComponentReflection(const std::string& className)
    {
        auto descriptor = std::make_unique<ClassDescriptor>(className, typeid(ComponentType));
        descriptor->AddProperty(MakeComponentAssetGuidProperty<ComponentType>());
        ReflectionRegistry::Get().RegisterClass(std::move(descriptor));
    }

    void RegisterInspectableLegacyComponentReflection()
    {
        auto descriptor = std::make_unique<ClassDescriptor>(
            "EditorInspectableLegacyComponent",
            typeid(EditorInspectableLegacyComponent));
        descriptor->AddProperty(MakeInspectableVisibleProperty());
        descriptor->AddProperty(MakeInspectableWeightProperty());
        descriptor->AddProperty(MakeInspectableLabelProperty());
        descriptor->AddProperty(MakeInspectableModeProperty());
        descriptor->AddProperty(MakeInspectableOffsetProperty());
        descriptor->AddProperty(MakeInspectableDirectionProperty());
        descriptor->AddProperty(MakeInspectableBoundsProperty());
        descriptor->AddProperty(MakeInspectableTintProperty());
        descriptor->AddProperty(MakeInspectableRotationProperty());
        ReflectionRegistry::Get().RegisterClass(std::move(descriptor));
    }

