    std::filesystem::path MakeTempScenePath(const char* name)
    {
        return std::filesystem::temp_directory_path() / name;
    }

    std::filesystem::path FindWorkspaceRoot()
    {
        std::filesystem::path path = std::filesystem::current_path();
        while (!path.empty())
        {
            if (std::filesystem::exists(path / "Editor" / "Private" / "Panels" /
                                        "AssetBrowser.cpp"))
            {
                return path;
            }

            const std::filesystem::path parent = path.parent_path();
            if (parent == path)
            {
                break;
            }
            path = parent;
        }

        return {};
    }

    std::string ReadTextFile(const std::filesystem::path& path)
    {
        std::ifstream file(path, std::ios::binary);
        std::ostringstream contents;
        contents << file.rdbuf();
        return contents.str();
    }

    class QueuedEditorFileDialogProvider final : public IEditorFileDialogProvider
    {
    public:
        bool IsAvailable() const override { return available; }

        EditorFileDialogResult OpenFile(const EditorFileDialogDesc& desc) override
        {
            ++openCount;
            lastOpenDesc = desc;
            return openResult;
        }

        EditorFileDialogResult SaveFile(const EditorFileDialogDesc& desc) override
        {
            ++saveCount;
            lastSaveDesc = desc;
            return saveResult;
        }

        bool available = true;
        uint32 openCount = 0;
        uint32 saveCount = 0;
        EditorFileDialogDesc lastOpenDesc;
        EditorFileDialogDesc lastSaveDesc;
        EditorFileDialogResult openResult;
        EditorFileDialogResult saveResult;
    };

    class QueuedUnsavedChangesPromptProvider final
        : public IEditorUnsavedChangesPromptProvider
    {
    public:
        bool IsAvailable() const override { return available; }

        EditorUnsavedChangesPromptResult Prompt(
            const EditorUnsavedChangesPromptDesc& desc) override
        {
            ++promptCount;
            lastDesc = desc;
            return result;
        }

        bool available = true;
        uint32 promptCount = 0;
        EditorUnsavedChangesPromptDesc lastDesc;
        EditorUnsavedChangesPromptResult result;
    };

    class TestEditorFrameClient final : public IEditorFrameClient
    {
    public:
        void SubmitViewportTargets(RHICommandContext&) override
        {
            ++viewportSharedSubmitCount;
        }

        void SubmitNativeMainFramebuffer(RHICommandContext*) override
        {
            ++nativeSharedSubmitCount;
        }

        void SubmitViewportTargetsStandalone() override
        {
            ++viewportStandaloneSubmitCount;
        }

        void SubmitNativeMainFramebufferStandalone() override
        {
            ++nativeStandaloneSubmitCount;
        }

        void HandleGraphicsContextUnavailable() override
        {
            ++graphicsContextUnavailableCount;
        }

        uint32 viewportSharedSubmitCount = 0;
        uint32 nativeSharedSubmitCount = 0;
        uint32 viewportStandaloneSubmitCount = 0;
        uint32 nativeStandaloneSubmitCount = 0;
        uint32 graphicsContextUnavailableCount = 0;
    };

    struct EditorContextValidation : testing::Test
    {
        void SetUp() override
        {
            Log::Initialize();
            ComponentFactory::ClearComponentClasses();
            ComponentFactory::RegisterComponentClass<EditorPayloadActorComponent>(
                ComponentFactory::ComponentClassDesc{
                    "EditorPayloadActorComponent",
                    "Actor Payload",
                    "Test",
                    false});
            ComponentFactory::RegisterComponentClass<EditorPayloadLegacyComponent>(
                ComponentFactory::ComponentClassDesc{
                    "EditorPayloadLegacyComponent",
                    "Legacy Payload",
                    "Legacy",
                    true});
            RegisterAssetRefComponentReflection<EditorPayloadActorComponent>(
                "EditorPayloadActorComponent");
            RegisterAssetRefComponentReflection<EditorPayloadLegacyComponent>(
                "EditorPayloadLegacyComponent");
        }

        void TearDown() override
        {
            EditorContext::Get().CloseProject();
            ComponentFactory::ClearComponentClasses();
            Log::Shutdown();
        }

        void RemoveFile(const std::filesystem::path& path)
        {
            std::error_code ec;
            std::filesystem::remove(path, ec);
        }

        void RemoveDirectory(const std::filesystem::path& path)
        {
            std::error_code ec;
            std::filesystem::remove_all(path, ec);
        }

        void WriteTextFile(const std::filesystem::path& path, const std::string& contents)
        {
            std::filesystem::create_directories(path.parent_path());
            std::ofstream file(path);
            file << contents;
        }
    };

    TEST_F(EditorContextValidation,
           EditorFrameCoordinatorUsesStandaloneFallbackWithoutRenderContext)
    {
        EditorFrameCoordinator coordinator;
        TestEditorFrameClient client;
        EditorFrameCoordinatorDesc desc;
        desc.client = &client;

        const EditorFrameCoordinatorStats& stats = coordinator.SubmitFrame(desc);

        EXPECT_FALSE(stats.renderContextReady);
        EXPECT_FALSE(stats.sharedRHIFrameUsed);
        EXPECT_TRUE(stats.standaloneFallbackUsed);
        EXPECT_FALSE(stats.graphicsContextReady);
        EXPECT_FALSE(stats.renderContextFrameBegun);
        EXPECT_FALSE(stats.renderContextFrameEnded);
        EXPECT_EQ(0u, client.viewportSharedSubmitCount);
        EXPECT_EQ(0u, client.nativeSharedSubmitCount);
        EXPECT_EQ(1u, client.viewportStandaloneSubmitCount);
        EXPECT_EQ(1u, client.nativeStandaloneSubmitCount);
        EXPECT_EQ(0u, client.graphicsContextUnavailableCount);
    }

    TEST_F(EditorContextValidation,
           EditorFrameSubmissionServiceRoutesUnavailableFallbacks)
    {
        EditorFrameSubmissionService service;
        EditorNativeUIRenderStatsService statsService;
        EditorNativeUISubmissionService nativeSubmissionService;
        EditorViewportSceneRenderStats viewportStats;
        EditorNativeUIRenderStats nativeStats;
        nativeStats.frameRecorded = true;

        EditorFrameSubmissionDesc desc;
        desc.viewportStats = &viewportStats;
        desc.nativeUIStats = &nativeStats;
        desc.nativeUIRenderStatsService = &statsService;
        desc.nativeUISubmissionService = &nativeSubmissionService;
        service.SetFrameDesc(desc);

        service.SubmitViewportTargetsStandalone();
        EXPECT_FALSE(viewportStats.renderContextReady);
        EXPECT_EQ("RenderContext unavailable", viewportStats.fallbackReason);

        service.SubmitNativeMainFramebufferStandalone();
        EXPECT_TRUE(nativeStats.submitAttempted);
        EXPECT_FALSE(nativeStats.submitTargetReady);
        EXPECT_EQ("RenderContext unavailable",
                  nativeStats.submitFallbackReason);

        nativeStats = {};
        nativeStats.frameRecorded = true;
        service.SetFrameDesc(desc);
        service.HandleGraphicsContextUnavailable();
        EXPECT_EQ("RenderContext graphics command context unavailable",
                  viewportStats.fallbackReason);
        EXPECT_TRUE(nativeStats.submitAttempted);
        EXPECT_TRUE(nativeStats.submitTargetReady);
        EXPECT_EQ("RenderContext graphics command context unavailable",
                  nativeStats.submitFallbackReason);
    }

