    TEST_F(EditorContextValidation,
           EditorWindowLifecycleServiceReportsInvalidCreateAndNoopDestroy)
    {
        EditorWindowLifecycleService service;

        EditorWindowCreateDesc createDesc;
        createDesc.width = 0;
        createDesc.height = 720;
        createDesc.title = "Invalid";
        const EditorWindowCreateResult invalidSizeResult =
            service.CreateWindow(createDesc);
        EXPECT_FALSE(invalidSizeResult);
        EXPECT_FALSE(invalidSizeResult.error.empty());
        EXPECT_EQ(nullptr, invalidSizeResult.window);
        EXPECT_FALSE(invalidSizeResult.glfwInitialized);

        createDesc.width = 1280;
        createDesc.title = "";
        const EditorWindowCreateResult invalidTitleResult =
            service.CreateWindow(createDesc);
        EXPECT_FALSE(invalidTitleResult);
        EXPECT_FALSE(invalidTitleResult.error.empty());
        EXPECT_EQ(nullptr, invalidTitleResult.window);
        EXPECT_FALSE(invalidTitleResult.glfwInitialized);

        GLFWwindow* window = nullptr;
        EditorWindowDestroyDesc destroyDesc;
        destroyDesc.window = &window;
        destroyDesc.terminateGlfw = false;
        const EditorWindowDestroyResult destroyResult =
            service.DestroyWindow(destroyDesc);
        EXPECT_TRUE(destroyResult);
        EXPECT_FALSE(destroyResult.windowDestroyed);
        EXPECT_FALSE(destroyResult.glfwTerminated);
        EXPECT_EQ(nullptr, window);

        const EditorWindowDestroyResult missingStorageResult =
            service.DestroyWindow({});
        EXPECT_FALSE(missingStorageResult);
        EXPECT_FALSE(missingStorageResult.error.empty());
    }

