    TEST_F(EditorContextValidation,
           EditorLegacyDebugUIServiceRoutesShellStatsAndPanelCallback)
    {
        EditorLegacyDebugUIService service;
        EditorNativeUIRenderStatsService statsService;
        EditorNativeUIRenderStats stats;

        EditorShellPolicyDecision decision;
        decision.useNativeMainShell = true;
        decision.drawLegacyDockSpace = true;
        decision.drawLegacyMainMenu = true;
        decision.drawLegacyStatusBar = true;
        decision.runDebugImGuiFrame = false;

        uint32 dockspaceDrawCount = 0;
        uint32 mainMenuDrawCount = 0;
        uint32 statusBarDrawCount = 0;
        uint32 panelsDrawCount = 0;

        EditorLegacyDebugUIFrameDesc desc;
        desc.shellDecision = &decision;
        desc.nativeUIRenderStatsService = &statsService;
        desc.nativeUIStats = &stats;
        desc.visibleLegacyPanelCount = 3;
        desc.drawDockSpace = [&dockspaceDrawCount]() {
            ++dockspaceDrawCount;
        };
        desc.drawMainMenuBar = [&mainMenuDrawCount]() {
            ++mainMenuDrawCount;
        };
        desc.drawStatusBar = [&statusBarDrawCount]() {
            ++statusBarDrawCount;
        };
        desc.drawPanels = [&panelsDrawCount]() {
            ++panelsDrawCount;
        };

        const EditorLegacyDebugUIFrameResult result =
            service.RenderFrame(desc);

        EXPECT_TRUE(result);
        EXPECT_TRUE(result.shellPolicyAvailable);
        EXPECT_FALSE(result.debugFrameActive);
        EXPECT_FALSE(result.debugFrameBegun);
        EXPECT_FALSE(result.legacyDockSpaceDrawn);
        EXPECT_FALSE(result.legacyMainMenuDrawn);
        EXPECT_FALSE(result.legacyStatusBarDrawn);
        EXPECT_TRUE(result.legacyPanelsDrawn);
        EXPECT_EQ(0u, dockspaceDrawCount);
        EXPECT_EQ(0u, mainMenuDrawCount);
        EXPECT_EQ(0u, statusBarDrawCount);
        EXPECT_EQ(1u, panelsDrawCount);
        EXPECT_EQ(3u, result.visibleLegacyPanelCount);
        EXPECT_EQ(3u, stats.visibleLegacyPanelCount);
        EXPECT_TRUE(stats.shellPolicyEvaluated);
        EXPECT_TRUE(stats.nativeCommandSurfacesOwnMainShell);
        EXPECT_TRUE(stats.legacyDockSpaceRequested);
        EXPECT_TRUE(stats.legacyMainMenuRequested);
        EXPECT_TRUE(stats.legacyStatusBarRequested);
        EXPECT_FALSE(stats.debugImGuiFrameRequested);
        EXPECT_FALSE(stats.debugImGuiFrameBegun);
        EXPECT_FALSE(stats.legacyDockSpaceDrawn);
        EXPECT_FALSE(stats.legacyMainMenuDrawn);
        EXPECT_FALSE(stats.legacyStatusBarDrawn);
#if RVX_EDITOR_ENABLE_LEGACY_IMGUI
        EXPECT_FALSE(result.nativeOnlyDefaultFramebufferClearMarked);
        EXPECT_FALSE(stats.defaultFramebufferClearedWithoutImGui);
#else
        EXPECT_TRUE(result.nativeOnlyDefaultFramebufferClearMarked);
        EXPECT_TRUE(stats.defaultFramebufferClearedWithoutImGui);
#endif

        EditorLegacyDebugUIMainFramebufferDesc mainFramebufferDesc;
        mainFramebufferDesc.debugFrameActive = false;
        const EditorLegacyDebugUIMainFramebufferResult mainFramebufferResult =
            service.RenderMainFramebuffer(mainFramebufferDesc);
        EXPECT_TRUE(mainFramebufferResult);
        EXPECT_FALSE(mainFramebufferResult.debugFrameActive);
        EXPECT_FALSE(mainFramebufferResult.debugLayerAvailable);
        EXPECT_FALSE(mainFramebufferResult.rendered);
    }

    TEST_F(EditorContextValidation,
           EditorNativeUISubmissionServiceReportsUnavailableDependencies)
    {
        EditorNativeUISubmissionService service;
        const EditorNativeUISubmissionResult result =
            service.SubmitToMainFramebuffer({});

        EXPECT_TRUE(result.attempted);
        EXPECT_FALSE(result.targetReady);
        EXPECT_FALSE(result.pipelineReady);
        EXPECT_FALSE(result.submitted);
        EXPECT_FALSE(result.defaultFramebufferTarget);
        EXPECT_FALSE(result.submittedToMainSwapChain);
        EXPECT_FALSE(result.submittedInEditorRHIFrame);
        EXPECT_EQ(0u, result.drawCallCount);
        EXPECT_EQ("RenderContext unavailable", result.fallbackReason);
    }

    TEST_F(EditorContextValidation,
           EditorMainFramebufferServiceReportsUnavailableDependencies)
    {
        EditorMainFramebufferService service;
        const EditorMainFramebufferClearResult clearResult =
            service.ClearDefaultFramebuffer({});

        EXPECT_TRUE(clearResult.attempted);
        EXPECT_FALSE(clearResult.openGLDefaultFramebufferAvailable);
        EXPECT_FALSE(clearResult.cleared);
        EXPECT_EQ(0u, clearResult.width);
        EXPECT_EQ(0u, clearResult.height);
        EXPECT_EQ("OpenGL main framebuffer is unavailable until the Editor owns an RHI swap chain",
                  clearResult.fallbackReason);

        const EditorMainFramebufferPresentResult presentResult =
            service.Present({});

        EXPECT_TRUE(presentResult.attempted);
        EXPECT_FALSE(presentResult.presented);
        EXPECT_FALSE(presentResult.mainSwapChainPresented);
        EXPECT_FALSE(presentResult.glfwSwapBuffersUsed);
        EXPECT_EQ("Main framebuffer window unavailable",
                  presentResult.fallbackReason);
    }

    TEST_F(EditorContextValidation,
           EditorMainFramePresentationServiceOwnsClearAndPresentPolicy)
    {
        EditorMainFramePresentationService service;

        EditorMainFramePrepareDesc debugDesc;
        debugDesc.debugImGuiMainFramebufferRendered = true;
        const EditorMainFramePrepareResult debugResult =
            service.PrepareMainFramebuffer(debugDesc);
        EXPECT_FALSE(debugResult.defaultFramebufferClearAttempted);
        EXPECT_FALSE(debugResult.defaultFramebufferClearedWithoutImGui);
        EXPECT_FALSE(debugResult.defaultFramebufferClearSkipped);
        EXPECT_TRUE(debugResult.fallbackReason.empty());

        EditorMainFramePrepareDesc swapChainDesc;
        swapChainDesc.mainSwapChainReady = true;
        const EditorMainFramePrepareResult swapChainResult =
            service.PrepareMainFramebuffer(swapChainDesc);
        EXPECT_FALSE(swapChainResult.defaultFramebufferClearAttempted);
        EXPECT_FALSE(swapChainResult.defaultFramebufferClearedWithoutImGui);
        EXPECT_TRUE(swapChainResult.defaultFramebufferClearSkipped);
        EXPECT_TRUE(swapChainResult.fallbackReason.empty());

        const EditorMainFramePrepareResult missingServiceResult =
            service.PrepareMainFramebuffer({});
        EXPECT_TRUE(missingServiceResult.defaultFramebufferClearAttempted);
        EXPECT_FALSE(missingServiceResult.defaultFramebufferClearedWithoutImGui);
        EXPECT_TRUE(missingServiceResult.defaultFramebufferClearSkipped);
        EXPECT_EQ("Main framebuffer service unavailable",
                  missingServiceResult.fallbackReason);

        EditorMainFramebufferService mainFramebufferService;
        EditorMainFramePrepareDesc fallbackDesc;
        fallbackDesc.mainFramebufferService = &mainFramebufferService;
        const EditorMainFramePrepareResult fallbackResult =
            service.PrepareMainFramebuffer(fallbackDesc);
        EXPECT_TRUE(fallbackResult.defaultFramebufferClearAttempted);
        EXPECT_FALSE(fallbackResult.defaultFramebufferClearedWithoutImGui);
        EXPECT_TRUE(fallbackResult.defaultFramebufferClearSkipped);
        EXPECT_EQ("OpenGL main framebuffer is unavailable until the Editor owns an RHI swap chain",
                  fallbackResult.fallbackReason);

        const EditorMainFramePresentResult missingPresentResult =
            service.PresentMainFramebuffer({});
        EXPECT_TRUE(missingPresentResult.attempted);
        EXPECT_FALSE(missingPresentResult.presented);
        EXPECT_FALSE(missingPresentResult.mainSwapChainPresented);
        EXPECT_FALSE(missingPresentResult.glfwSwapBuffersUsed);
        EXPECT_EQ("Main framebuffer service unavailable",
                  missingPresentResult.fallbackReason);

        EditorMainFramePresentDesc presentDesc;
        presentDesc.mainFramebufferService = &mainFramebufferService;
        const EditorMainFramePresentResult presentResult =
            service.PresentMainFramebuffer(presentDesc);
        EXPECT_TRUE(presentResult.attempted);
        EXPECT_FALSE(presentResult.presented);
        EXPECT_FALSE(presentResult.mainSwapChainPresented);
        EXPECT_FALSE(presentResult.glfwSwapBuffersUsed);
        EXPECT_EQ("Main framebuffer window unavailable",
                  presentResult.fallbackReason);
    }

    TEST_F(EditorContextValidation,
           EditorMainSwapChainServiceReportsUnavailableDependencies)
    {
        EditorMainSwapChainService service;

        EXPECT_FALSE(service.HasSwapChain(nullptr));
        const NativeSurfaceDesc missingSurface = service.CaptureSurface(
            nullptr,
            RHIBackendType::DX12,
            RHIFormat::BGRA8_UNORM,
            true);
        EXPECT_EQ(NativeSurfacePlatform::None, missingSurface.platform);

        const EditorMainSwapChainEnsureResult result = service.Ensure({});
        EXPECT_FALSE(result.ready);
        EXPECT_FALSE(result.created);
        EXPECT_FALSE(result.resized);
        EXPECT_EQ(0u, result.width);
        EXPECT_EQ(0u, result.height);
        EXPECT_EQ(NativeSurfacePlatform::None, result.surface.platform);
        EXPECT_EQ("Main window or RenderContext unavailable",
                  result.fallbackReason);
    }

    TEST_F(EditorContextValidation,
           EditorNativeUIRenderStatsServiceMapsFrameSubmissionAndPolicy)
    {
        EditorNativeUIRenderStatsService service;

        EditorNativeUIFrameResult frameResult;
        frameResult.hostReady = true;
        frameResult.rendererReady = true;
        frameResult.frameRecorded = true;
        frameResult.commandCount = 10;
        frameResult.rectCount = 3;
        frameResult.textCount = 2;
        frameResult.imageCount = 1;
        frameResult.vertexCount = 42;
        frameResult.indexCount = 60;
        frameResult.menuCount = 4;
        frameResult.toolbarCount = 5;
        frameResult.statusItemCount = 6;
        frameResult.executableItemCount = 7;
        frameResult.menuBarHeight = 21.0f;
        frameResult.toolbarHeight = 32.0f;
        frameResult.statusBarHeight = 18.0f;
        frameResult.dockspaceTopReservedHeight = 53.0f;
        frameResult.dockspaceBottomReservedHeight = 19.0f;
        frameResult.frameCount = 11;

        EditorNativeUIRenderStats stats =
            service.FromFrameResult(frameResult);
        EXPECT_TRUE(stats.hostReady);
        EXPECT_TRUE(stats.rendererReady);
        EXPECT_TRUE(stats.frameRecorded);
        EXPECT_EQ(10u, stats.commandCount);
        EXPECT_EQ(42u, stats.vertexCount);
        EXPECT_EQ(4u, stats.menuCount);
        EXPECT_FLOAT_EQ(53.0f, stats.dockspaceTopReservedHeight);
        EXPECT_EQ(11u, stats.frameCount);

        EditorShellPolicyDecision policyDecision;
        policyDecision.useNativeMainShell = true;
        policyDecision.drawLegacyDockSpace = true;
        policyDecision.drawLegacyMainMenu = true;
        policyDecision.drawLegacyStatusBar = true;
        policyDecision.runDebugImGuiFrame = true;
        service.SetVisibleLegacyPanelCount(stats, 9);
        service.ApplyShellPolicyDecision(stats, policyDecision);
        service.MarkDebugImGuiFrameBegun(stats);
        service.MarkLegacyDockSpaceDrawn(stats);
        service.MarkLegacyMainMenuDrawn(stats);
        service.MarkLegacyStatusBarDrawn(stats);
        EXPECT_EQ(9u, stats.visibleLegacyPanelCount);
        EXPECT_TRUE(stats.shellPolicyEvaluated);
        EXPECT_TRUE(stats.nativeCommandSurfacesOwnMainShell);
        EXPECT_TRUE(stats.legacyDockSpaceRequested);
        EXPECT_TRUE(stats.legacyMainMenuRequested);
        EXPECT_TRUE(stats.legacyStatusBarRequested);
        EXPECT_TRUE(stats.debugImGuiFrameRequested);
        EXPECT_TRUE(stats.debugImGuiFrameBegun);
        EXPECT_TRUE(stats.legacyDockSpaceDrawn);
        EXPECT_TRUE(stats.legacyMainMenuDrawn);
        EXPECT_TRUE(stats.legacyStatusBarDrawn);

        EditorMainSwapChainEnsureResult swapChainResult;
        swapChainResult.ready = true;
        swapChainResult.width = 1280;
        swapChainResult.height = 720;
        service.ApplyMainSwapChainResult(stats, swapChainResult);
        EXPECT_TRUE(stats.mainSwapChainReady);
        EXPECT_EQ(1280u, stats.mainSwapChainWidth);
        EXPECT_EQ(720u, stats.mainSwapChainHeight);
        EXPECT_TRUE(stats.mainFramebufferFallbackReason.empty());

        EditorMainFramePrepareResult prepareResult;
        prepareResult.defaultFramebufferClearSkipped = true;
        service.SetDebugImGuiMainFramebufferRendered(stats, true);
        service.ApplyMainFramePrepareResult(stats, prepareResult);
        EXPECT_TRUE(stats.debugImGuiMainFramebufferRendered);
        EXPECT_TRUE(stats.defaultFramebufferClearSkipped);

        EditorMainFramePresentResult presentResult;
        presentResult.presented = false;
        presentResult.mainSwapChainPresented = false;
        presentResult.fallbackReason = "present failed";
        service.ApplyMainFramePresentResult(stats, presentResult);
        EXPECT_FALSE(stats.mainSwapChainPresented);
        EXPECT_EQ("present failed", stats.mainFramebufferFallbackReason);

        EditorNativeUISubmissionResult submitResult;
        submitResult.attempted = true;
        submitResult.targetReady = true;
        submitResult.pipelineReady = true;
        submitResult.submitted = true;
        submitResult.defaultFramebufferTarget = false;
        submitResult.submittedToMainSwapChain = true;
        submitResult.submittedInEditorRHIFrame = true;
        submitResult.drawCallCount = 3;
        service.ApplySubmissionResult(stats, submitResult);
        EXPECT_TRUE(stats.submitAttempted);
        EXPECT_TRUE(stats.submitTargetReady);
        EXPECT_TRUE(stats.pipelineReady);
        EXPECT_TRUE(stats.submitted);
        EXPECT_TRUE(stats.submittedToMainSwapChain);
        EXPECT_TRUE(stats.submittedInEditorRHIFrame);
        EXPECT_EQ(3u, stats.drawCallCount);

        service.MarkGraphicsContextUnavailable(stats, "graphics unavailable");
        EXPECT_TRUE(stats.submitAttempted);
        EXPECT_TRUE(stats.submitTargetReady);
        EXPECT_EQ("graphics unavailable", stats.submitFallbackReason);
    }

