    TEST_F(EditorContextValidation,
           EditorSettingsServicePersistsRecentSceneDirectories)
    {
        const auto root = MakeTempScenePath("rvx_editor_settings_service");
        RemoveDirectory(root);
        std::filesystem::create_directories(root / "A");
        std::filesystem::create_directories(root / "B");
        std::filesystem::create_directories(root / "C");
        std::filesystem::create_directories(root / "D");

        const std::filesystem::path settingsPath =
            root / "Config" / "EditorSettings.json";
        EditorSettingsService service(settingsPath);
        EXPECT_EQ(settingsPath, service.GetSettingsPath());
        ASSERT_TRUE(service.Load());
        EXPECT_EQ(EditorUIBackendType::Native, service.GetUIBackendType());
        EXPECT_FLOAT_EQ(RVX_EDITOR_DEFAULT_UI_SCALE_FACTOR,
                        service.GetUIScaleFactor());
        EXPECT_TRUE(service.GetUIFontPaths().empty());
        EXPECT_TRUE(service.ShouldAppendDefaultSystemFonts());
        EXPECT_TRUE(service.GetRecentSceneDirectories().empty());
        EXPECT_FALSE(service.IsShortcutProfileAutosaveEnabled());
        EXPECT_FLOAT_EQ(0.75f,
                        service.GetShortcutProfileAutosaveDebounceSeconds());

        service.SetUIBackendType(EditorUIBackendType::Native);
        service.SetUIScaleFactor(1.5f);
        service.SetAppendDefaultSystemFonts(false);
        service.SetUIFontPaths({root / "Fonts" / "EditorPrimary.ttf",
                                root / "Fonts" / "EditorFallback.ttc"});
        service.SetMaxRecentSceneDirectories(3);
        service.SetShortcutProfileAutosaveEnabled(true);
        service.SetShortcutProfileAutosaveDebounceSeconds(1.25f);
        EXPECT_TRUE(service.AddRecentSceneDirectory(root / "A"));
        EXPECT_TRUE(service.AddRecentScenePath(root / "B" / "Level.rvxscene"));
        EXPECT_TRUE(service.AddRecentSceneDirectory(root / "C"));
        EXPECT_TRUE(service.AddRecentSceneDirectory(root / "A"));
        EXPECT_FALSE(service.AddRecentSceneDirectory(root / "Missing"));
        EXPECT_FALSE(service.GetLastError().empty());

        const auto normalize = [](const std::filesystem::path& path) {
            std::error_code ec;
            return std::filesystem::weakly_canonical(path, ec).lexically_normal();
        };

        ASSERT_EQ(3u, static_cast<uint32>(
                          service.GetRecentSceneDirectories().size()));
        EXPECT_EQ(normalize(root / "A"), service.GetRecentSceneDirectories()[0]);
        EXPECT_EQ(normalize(root / "C"), service.GetRecentSceneDirectories()[1]);
        EXPECT_EQ(normalize(root / "B"), service.GetRecentSceneDirectories()[2]);

        ASSERT_TRUE(service.Save());
        const std::string savedSettings = ReadTextFile(settingsPath);
        EXPECT_NE(std::string::npos, savedSettings.find("\"schemaVersion\""));
        EXPECT_NE(std::string::npos, savedSettings.find("\"ui\""));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"backendType\": \"native\""));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"scaleFactor\": 1.5"));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"appendDefaultSystemFonts\": false"));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"fontPaths\""));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("EditorPrimary.ttf"));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("EditorFallback.ttc"));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"maxRecentSceneDirectories\": 3"));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"recentSceneDirectories\""));
        EXPECT_NE(std::string::npos, savedSettings.find("\"shortcuts\""));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"profileAutosaveEnabled\": true"));
        EXPECT_NE(std::string::npos,
                  savedSettings.find("\"profileAutosaveDebounceSeconds\": 1.25"));

        EditorSettingsService loaded(settingsPath);
        ASSERT_TRUE(loaded.Load()) << loaded.GetLastError();
        EXPECT_EQ(EditorUIBackendType::Native, loaded.GetUIBackendType());
        EXPECT_FLOAT_EQ(1.5f, loaded.GetUIScaleFactor());
        EXPECT_FALSE(loaded.ShouldAppendDefaultSystemFonts());
        ASSERT_EQ(2u, static_cast<uint32>(loaded.GetUIFontPaths().size()));
        EXPECT_EQ((root / "Fonts" / "EditorPrimary.ttf").lexically_normal(),
                  loaded.GetUIFontPaths()[0]);
        EXPECT_EQ((root / "Fonts" / "EditorFallback.ttc").lexically_normal(),
                  loaded.GetUIFontPaths()[1]);
        EXPECT_EQ(3u, loaded.GetMaxRecentSceneDirectories());
        EXPECT_TRUE(loaded.IsShortcutProfileAutosaveEnabled());
        EXPECT_FLOAT_EQ(1.25f,
                        loaded.GetShortcutProfileAutosaveDebounceSeconds());
        ASSERT_EQ(3u, static_cast<uint32>(
                          loaded.GetRecentSceneDirectories().size()));
        EXPECT_EQ(normalize(root / "A"), loaded.GetRecentSceneDirectories()[0]);
        EXPECT_EQ(normalize(root / "C"), loaded.GetRecentSceneDirectories()[1]);
        EXPECT_EQ(normalize(root / "B"), loaded.GetRecentSceneDirectories()[2]);

        EXPECT_TRUE(loaded.AddRecentSceneDirectory(root / "D"));
        ASSERT_EQ(3u, static_cast<uint32>(
                          loaded.GetRecentSceneDirectories().size()));
        EXPECT_EQ(normalize(root / "D"), loaded.GetRecentSceneDirectories()[0]);
        EXPECT_EQ(normalize(root / "A"), loaded.GetRecentSceneDirectories()[1]);
        EXPECT_EQ(normalize(root / "C"), loaded.GetRecentSceneDirectories()[2]);

        loaded.SetMaxRecentSceneDirectories(1);
        ASSERT_EQ(1u, static_cast<uint32>(
                          loaded.GetRecentSceneDirectories().size()));
        EXPECT_EQ(normalize(root / "D"), loaded.GetRecentSceneDirectories()[0]);

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorSettingsServiceClampsUIScaleToSupportedRange)
    {
        const auto root =
            MakeTempScenePath("rvx_editor_settings_readable_ui_scale");
        RemoveDirectory(root);

        const std::filesystem::path settingsPath =
            root / "Config" / "EditorSettings.json";
        WriteTextFile(settingsPath,
                      "{\n"
                      "  \"schemaVersion\": 1,\n"
                      "  \"ui\": {\n"
                      "    \"backendType\": \"native\",\n"
                      "    \"scaleFactor\": 0.25\n"
                      "  }\n"
                      "}\n");

        EditorSettingsService service(settingsPath);
        ASSERT_TRUE(service.Load()) << service.GetLastError();
        EXPECT_FLOAT_EQ(0.75f, service.GetUIScaleFactor());

        service.SetUIScaleFactor(2.5f);
        EXPECT_FLOAT_EQ(2.0f, service.GetUIScaleFactor());

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorSettingsServiceRejectsUnsupportedUIBackendType)
    {
        const auto root = MakeTempScenePath("rvx_editor_settings_bad_ui_backend");
        RemoveDirectory(root);
        std::filesystem::create_directories(root / "Config");

        const std::filesystem::path settingsPath =
            root / "Config" / "EditorSettings.json";
        {
            std::ofstream file(settingsPath, std::ios::binary);
            file << "{\n";
            file << "  \"schemaVersion\": 1,\n";
            file << "  \"ui\": { \"backendType\": \"webview\" },\n";
            file << "  \"filePicker\": {\n";
            file << "    \"maxRecentSceneDirectories\": 3,\n";
            file << "    \"recentSceneDirectories\": []\n";
            file << "  }\n";
            file << "}\n";
        }

        EditorSettingsService service(settingsPath);
        EXPECT_FALSE(service.Load());
        EXPECT_FALSE(service.GetLastError().empty());
        EXPECT_EQ(EditorUIBackendType::Native, service.GetUIBackendType());

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorFilePickerModelLoadsFiltersSortsAndNavigatesDirectories)
    {
        const auto root = MakeTempScenePath("rvx_editor_file_picker_model");
        RemoveDirectory(root);
        std::filesystem::create_directories(root / "Subdir");
        WriteTextFile(root / "LevelB.txt", "text");
        WriteTextFile(root / "LevelA.rvxscene", "scene");
        WriteTextFile(root / "Subdir" / "Nested.rvxscene", "nested");

        EditorFilePickerDesc desc;
        desc.mode = EditorFilePickerMode::OpenFile;
        desc.initialDirectory = root;
        desc.filters.push_back(
            {"RenderVerseX Scene (*.rvxscene)", {"*.rvxscene"}});
        desc.filters.push_back({"All Files (*.*)", {"*.*"}});
        desc.recentDirectories.push_back(root / "Subdir");
        desc.recentDirectories.push_back(root / "MissingRecent");
        desc.recentDirectories.push_back(root / "Subdir");
        desc.maxRecentDirectories = 3;

        EditorFilePickerModel model;
        ASSERT_TRUE(model.Open(desc)) << model.GetLastError();

        const EditorFilePickerStats& stats = model.GetLastBuildStats();
        EXPECT_TRUE(stats.directoryLoaded);
        EXPECT_EQ(3u, stats.entryCount);
        EXPECT_EQ(1u, stats.directoryCount);
        EXPECT_EQ(2u, stats.fileCount);
        EXPECT_EQ(2u, stats.visibleEntryCount);
        EXPECT_EQ(1u, stats.visibleFileCount);
        EXPECT_EQ(1u, stats.hiddenFileCount);
        EXPECT_GE(stats.breadcrumbCount, 1u);
        EXPECT_EQ(2u, stats.recentDirectoryCount);
        ASSERT_GE(model.GetRecentDirectories().size(), static_cast<size_t>(2));
        EXPECT_EQ(root, model.GetRecentDirectories()[0]);
        EXPECT_EQ(root / "Subdir", model.GetRecentDirectories()[1]);
        EXPECT_FALSE(model.CanAcceptSelection());

        const std::vector<EditorFilePickerEntry>& visibleEntries =
            model.GetVisibleEntries();
        ASSERT_EQ(2u, static_cast<uint32>(visibleEntries.size()));
        EXPECT_TRUE(visibleEntries[0].directory);
        EXPECT_EQ("Subdir", visibleEntries[0].displayName);
        EXPECT_TRUE(visibleEntries[1].file);
        EXPECT_EQ("LevelA.rvxscene", visibleEntries[1].displayName);

        EXPECT_FALSE(model.SelectEntry(99u));
        EXPECT_EQ(2u, static_cast<uint32>(model.GetVisibleEntries().size()));
        EXPECT_FALSE(model.GetLastError().empty());

        ASSERT_TRUE(model.SelectEntry(1u));
        EXPECT_TRUE(model.CanAcceptSelection());
        EXPECT_EQ("LevelA.rvxscene",
                  model.ResolveAcceptedPath().filename().string());
        EXPECT_FALSE(model.SetCurrentDirectory(root / "Missing"));
        EXPECT_EQ(root.filename().string(),
                  model.GetCurrentDirectory().filename().string());
        EXPECT_EQ("LevelA.rvxscene", model.GetSelectedPath().filename().string());
        EXPECT_EQ(2u, static_cast<uint32>(model.GetVisibleEntries().size()));

        EXPECT_FALSE(model.EnterRecentDirectory(99u));
        ASSERT_TRUE(model.EnterRecentDirectory(1u));
        EXPECT_EQ("Subdir", model.GetCurrentDirectory().filename().string());
        ASSERT_GE(model.GetBreadcrumbs().size(), static_cast<size_t>(2));
        ASSERT_TRUE(model.EnterBreadcrumb(
            static_cast<uint32>(model.GetBreadcrumbs().size() - 2u)));
        EXPECT_EQ(root.filename().string(),
                  model.GetCurrentDirectory().filename().string());

        ASSERT_TRUE(model.SelectEntry(0u));
        EXPECT_FALSE(model.CanAcceptSelection());
        ASSERT_TRUE(model.EnterSelectedDirectory());
        EXPECT_EQ("Subdir", model.GetCurrentDirectory().filename().string());
        EXPECT_TRUE(model.CanGoBackDirectory());
        EXPECT_FALSE(model.CanGoForwardDirectory());
        ASSERT_EQ(1u, static_cast<uint32>(model.GetVisibleEntries().size()));
        EXPECT_EQ("Nested.rvxscene", model.GetVisibleEntries()[0].displayName);

        ASSERT_TRUE(model.GoBackDirectory());
        EXPECT_EQ(root.filename().string(),
                  model.GetCurrentDirectory().filename().string());
        EXPECT_TRUE(model.CanGoBackDirectory());
        EXPECT_TRUE(model.CanGoForwardDirectory());

        ASSERT_TRUE(model.GoForwardDirectory());
        EXPECT_EQ("Subdir", model.GetCurrentDirectory().filename().string());
        EXPECT_TRUE(model.CanGoBackDirectory());
        EXPECT_FALSE(model.CanGoForwardDirectory());

        ASSERT_TRUE(model.GoToParentDirectory());
        EXPECT_EQ(root.filename().string(),
                  model.GetCurrentDirectory().filename().string());
        EXPECT_TRUE(model.CanGoBackDirectory());
        EXPECT_FALSE(model.CanGoForwardDirectory());
        ASSERT_TRUE(model.SetActiveFilterIndex(1u));
        EXPECT_EQ(3u, model.GetLastBuildStats().visibleEntryCount);
        ASSERT_EQ(3u, static_cast<uint32>(model.GetVisibleEntries().size()));
        EXPECT_EQ("LevelB.txt", model.GetVisibleEntries()[2].displayName);
        ASSERT_TRUE(model.SelectEntry(2u));
        EXPECT_TRUE(model.CanAcceptSelection());

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorFilePickerModelResolvesSaveNamesAndRejectsInvalidOpenPaths)
    {
        const auto root = MakeTempScenePath("rvx_editor_file_picker_save_model");
        RemoveDirectory(root);
        std::filesystem::create_directories(root);
        WriteTextFile(root / "Existing.rvxscene", "scene");

        EditorFilePickerDesc saveDesc;
        saveDesc.mode = EditorFilePickerMode::SaveFile;
        saveDesc.initialDirectory = root;
        saveDesc.defaultExtension = "rvxscene";
        saveDesc.filters.push_back(
            {"RenderVerseX Scene (*.rvxscene)", {"*.rvxscene"}});

        EditorFilePickerModel model;
        ASSERT_TRUE(model.Open(saveDesc)) << model.GetLastError();
        EXPECT_FALSE(model.CanAcceptSelection());

        EXPECT_TRUE(model.SetTypedFileName("CreatedScene"));
        EXPECT_EQ("CreatedScene.rvxscene",
                  model.ResolveAcceptedPath().filename().string());
        EXPECT_TRUE(model.CanAcceptSelection());

        EXPECT_TRUE(model.SetTypedFileName("Wrong.txt"));
        EXPECT_FALSE(model.CanAcceptSelection());

        saveDesc.allowCreateFileInSaveMode = false;
        ASSERT_TRUE(model.Open(saveDesc)) << model.GetLastError();
        EXPECT_TRUE(model.SetTypedFileName("Existing"));
        EXPECT_TRUE(model.CanAcceptSelection());
        EXPECT_TRUE(model.SetTypedFileName("Missing"));
        EXPECT_FALSE(model.CanAcceptSelection());

        EditorFilePickerDesc openDesc;
        openDesc.mode = EditorFilePickerMode::OpenFile;
        openDesc.initialDirectory = root;
        openDesc.filters.push_back({"All Files (*.*)", {"*.*"}});
        ASSERT_TRUE(model.Open(openDesc)) << model.GetLastError();
        EXPECT_TRUE(model.SetTypedFileName("Missing.rvxscene"));
        EXPECT_FALSE(model.CanAcceptSelection());
        EXPECT_FALSE(model.ResolveAcceptedPath().empty());

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation, EditorPendingActionQueueDefersCompletesAndCancels)
    {
        EditorPendingActionQueue queue;
        EXPECT_FALSE(queue.HasPendingAction());

        uint32 alphaCount = 0;
        EditorPendingActionDesc alpha;
        alpha.id = "alpha";
        alpha.label = "Alpha";
        alpha.callback = [&alphaCount]() {
            ++alphaCount;
        };
        EXPECT_TRUE(queue.Begin(std::move(alpha)));
        EXPECT_TRUE(queue.HasPendingAction());
        EXPECT_EQ("alpha", queue.GetState().id);
        EXPECT_EQ("Alpha", queue.GetState().label);
        EXPECT_EQ(1u, queue.GetState().revision);

        uint32 blockedCount = 0;
        EditorPendingActionDesc blocked;
        blocked.id = "blocked";
        blocked.label = "Blocked";
        blocked.callback = [&blockedCount]() {
            ++blockedCount;
        };
        EXPECT_FALSE(queue.Begin(std::move(blocked)));
        EXPECT_EQ(0u, blockedCount);
        EXPECT_FALSE(queue.GetLastError().empty());

        EXPECT_TRUE(queue.Complete());
        EXPECT_EQ(1u, alphaCount);
        EXPECT_FALSE(queue.HasPendingAction());
        EXPECT_EQ(2u, queue.GetState().revision);
        EXPECT_FALSE(queue.Complete());

        uint32 betaCount = 0;
        EditorPendingActionDesc beta;
        beta.id = "beta";
        beta.label = "Beta";
        beta.callback = [&betaCount]() {
            ++betaCount;
        };
        EXPECT_TRUE(queue.Begin(std::move(beta)));
        EXPECT_TRUE(queue.Cancel());
        EXPECT_EQ(0u, betaCount);
        EXPECT_FALSE(queue.HasPendingAction());
        EXPECT_EQ(4u, queue.GetState().revision);

        queue.Clear();
        EXPECT_FALSE(queue.HasPendingAction());
        EXPECT_TRUE(queue.GetLastError().empty());
        EXPECT_EQ(0u, queue.GetState().revision);
    }

    TEST_F(EditorContextValidation,
           EditorDocumentActionServiceRoutesUnsavedAndOverwriteDecisions)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();

        const auto savedScenePath =
            MakeTempScenePath("rvx_editor_document_action_saved.rvxscene");
        const auto overwriteScenePath =
            MakeTempScenePath("rvx_editor_document_action_overwrite.rvxscene");
        RemoveFile(savedScenePath);
        RemoveFile(overwriteScenePath);
        WriteTextFile(overwriteScenePath, "existing scene");

        EditorDocumentSession document(context);
        EditorFileDialogService fileDialogs;
        auto promptProvider =
            std::make_unique<QueuedUnsavedChangesPromptProvider>();
        EditorUnsavedChangesGuard guard(document,
                                        fileDialogs,
                                        std::move(promptProvider));
        EditorPendingActionQueue pendingActions;
        EditorDocumentActionService actions;
        actions.SetDocumentSession(&document);
        actions.SetUnsavedChangesGuard(&guard);
        actions.SetPendingActions(&pendingActions);

        uint32 continuationCount = 0;
        EditorDocumentActionResult result = actions.RequestGuardedAction(
            "file.newScene",
            "New Scene",
            [&continuationCount]() {
                ++continuationCount;
            },
            true);
        EXPECT_TRUE(result);
        EXPECT_EQ(1u, continuationCount);
        EXPECT_FALSE(actions.HasPendingAction());

        ASSERT_TRUE(document.NewScene());
        SceneEntity* entity =
            context.CreateEntityUndoable("DirtyDocumentActionScene");
        ASSERT_NE(nullptr, entity);
        context.MarkSceneDirty();
        ASSERT_TRUE(document.IsDirty());

        result = actions.RequestGuardedAction(
            "file.openScene",
            "Open Scene",
            [&continuationCount]() {
                ++continuationCount;
            },
            true);
        EXPECT_EQ(EditorDocumentActionStatus::Deferred, result.status);
        EXPECT_TRUE(result.openUnsavedChangesModal);
        EXPECT_TRUE(actions.HasPendingAction());
        EXPECT_EQ(1u, continuationCount);

        result = actions.ResolveUnsavedChanges(EditorUnsavedChangesChoice::Save,
                                               true);
        EXPECT_EQ(EditorDocumentActionStatus::RequiresSaveAs, result.status);
        EXPECT_TRUE(result.closeModal);
        EXPECT_TRUE(result.openSaveSceneAsPicker);
        EXPECT_TRUE(actions.HasPendingAction());

        result = actions.CompletePendingActionAfterSave(false);
        EXPECT_EQ(EditorDocumentActionStatus::Deferred, result.status);
        EXPECT_TRUE(result.openUnsavedChangesModal);
        EXPECT_TRUE(actions.HasPendingAction());
        EXPECT_EQ(1u, continuationCount);

        result = actions.CompletePendingActionAfterSave(true);
        EXPECT_TRUE(result);
        EXPECT_FALSE(actions.HasPendingAction());
        EXPECT_EQ(2u, continuationCount);

        ASSERT_TRUE(document.SaveSceneAs(savedScenePath));
        EXPECT_FALSE(actions.ShouldConfirmSaveOverwrite(savedScenePath));
        EXPECT_TRUE(actions.ShouldConfirmSaveOverwrite(overwriteScenePath));

        const EditorSaveOverwriteConfirmationDesc confirmation =
            actions.BuildSaveOverwriteConfirmationDesc(overwriteScenePath);
        EXPECT_EQ(overwriteScenePath, confirmation.path);
        EXPECT_EQ("Overwrite Existing Scene?", confirmation.title);
        EXPECT_NE(std::string::npos,
                  confirmation.message.find(overwriteScenePath.filename().string()));
        EXPECT_EQ("Overwrite", confirmation.confirmButtonText);
        EXPECT_EQ("Cancel", confirmation.cancelButtonText);
    }

    TEST_F(EditorContextValidation,
           EditorDocumentCommandServicePublishesDeferredGuardedResults)
    {
        ConsolePanel::Clear();

        auto& context = EditorContext::Get();
        context.CloseProject();

        EditorCommandSurfaceModel surfaceModel;
        surfaceModel.BuildDefaultEditorSurfaces();
        EditorNotificationService notifications;
        notifications.SetCommandSurfaceModel(&surfaceModel);

        uint32 refreshCount = 0;
        EditorCommandExecutionService commands;
        commands.SetNotificationService(&notifications);
        commands.SetRefreshCallback([&refreshCount]() {
            ++refreshCount;
        });

        EditorDocumentSession document(context);
        EditorFileDialogService fileDialogs;
        auto promptProvider =
            std::make_unique<QueuedUnsavedChangesPromptProvider>();
        EditorUnsavedChangesGuard guard(document,
                                        fileDialogs,
                                        std::move(promptProvider));
        EditorPendingActionQueue pendingActions;
        EditorDocumentActionService actions;
        actions.SetDocumentSession(&document);
        actions.SetUnsavedChangesGuard(&guard);
        actions.SetPendingActions(&pendingActions);

        EditorDocumentCommandService documentCommands;
        documentCommands.SetCommandExecutionService(&commands);
        documentCommands.SetDocumentActionService(&actions);

        uint32 modalCount = 0;
        uint32 continuationCount = 0;
        EditorCommandActionResult result = commands.ExecutePlan(
            {"New Scene",
             [&]() {
                 return documentCommands.RequestGuardedAction(
                     "file.newScene",
                     "New Scene",
                     [&]() {
                         ++continuationCount;
                         return commands.MakeSucceeded("New Scene",
                                                       "New Scene");
                     },
                     true,
                     [&modalCount]() {
                         ++modalCount;
                     });
             }});
        EXPECT_TRUE(result);
        EXPECT_EQ(EditorCommandActionStatus::Succeeded, result.status);
        EXPECT_EQ(1u, continuationCount);
        EXPECT_EQ(0u, modalCount);
        EXPECT_EQ(1u, refreshCount);
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Success,
                  notifications.GetLatest()->severity);

        ASSERT_TRUE(document.NewScene());
        SceneEntity* entity =
            context.CreateEntityUndoable("DirtyDocumentCommandScene");
        ASSERT_NE(nullptr, entity);
        context.MarkSceneDirty();
        ASSERT_TRUE(document.IsDirty());

        result = commands.ExecutePlan(
            {"Open Scene",
             [&]() {
                 return documentCommands.RequestGuardedAction(
                     "file.openScene",
                     "Open Scene",
                     [&]() {
                         ++continuationCount;
                         return commands.MakeSucceeded("Open Scene",
                                                       "Open Scene");
                     },
                     true,
                     [&modalCount]() {
                         ++modalCount;
                     });
             }});
        EXPECT_FALSE(result);
        EXPECT_EQ(EditorCommandActionStatus::WaitingForUser, result.status);
        EXPECT_EQ(1u, continuationCount);
        EXPECT_EQ(1u, modalCount);
        EXPECT_EQ(2u, refreshCount);
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Info,
                  notifications.GetLatest()->severity);
        EXPECT_TRUE(pendingActions.HasPendingAction());

        const EditorDocumentActionResult completeResult =
            actions.CompletePendingActionAfterSave(true);
        EXPECT_TRUE(completeResult);
        EXPECT_EQ(2u, continuationCount);
        EXPECT_FALSE(pendingActions.HasPendingAction());
        EXPECT_EQ(EditorCommandActionStatus::Succeeded,
                  documentCommands.GetLastResult().status);
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Success,
                  notifications.GetLatest()->severity);
        EXPECT_EQ("Open Scene", notifications.GetLatest()->title);
        EXPECT_EQ(2u, refreshCount);

        ConsolePanel::Clear();
    }

    TEST_F(EditorContextValidation,
           EditorDocumentFileCommandServiceCompletesOpenSaveAndRecentPaths)
    {
        ConsolePanel::Clear();

        auto& context = EditorContext::Get();
        context.CloseProject();

        const auto root =
            MakeTempScenePath("rvx_editor_document_file_command_service");
        RemoveDirectory(root);
        std::filesystem::create_directories(root / "Scenes");
        const std::filesystem::path scenePath =
            root / "Scenes" / "DocumentFileCommand.rvxscene";
        const std::filesystem::path settingsPath =
            root / "Settings" / "editor-settings.json";

        EditorSettingsService settings(settingsPath);
        ASSERT_TRUE(settings.Load());

        auto provider = std::make_unique<QueuedEditorFileDialogProvider>();
        QueuedEditorFileDialogProvider* providerPtr = provider.get();
        providerPtr->saveResult.accepted = true;
        providerPtr->saveResult.path = scenePath;

        EditorFileDialogService fileDialogs(std::move(provider));
        EditorCommandSurfaceModel surfaceModel;
        surfaceModel.BuildDefaultEditorSurfaces();
        EditorNotificationService notifications;
        notifications.SetCommandSurfaceModel(&surfaceModel);

        uint32 refreshCount = 0;
        EditorCommandExecutionService commands;
        commands.SetNotificationService(&notifications);
        commands.SetRefreshCallback([&refreshCount]() {
            ++refreshCount;
        });

        EditorDocumentSession document(context);
        EditorSelectionService selection(context);
        EditorOperationService operations;
        operations.SetDocumentSession(&document);
        operations.SetSelectionService(&selection);

        EditorDocumentActionService actions;
        actions.SetDocumentSession(&document);

        EditorDocumentFileCommandService fileCommands;
        fileCommands.SetCommandExecutionService(&commands);
        fileCommands.SetDocumentActionService(&actions);
        fileCommands.SetDocumentSession(&document);
        fileCommands.SetFileDialogService(&fileDialogs);
        fileCommands.SetNotificationService(&notifications);
        fileCommands.SetOperationService(&operations);
        fileCommands.SetSettingsService(&settings);
        fileCommands.SetRefreshCallback([&refreshCount]() {
            ++refreshCount;
        });

        ASSERT_TRUE(document.NewScene());
        ASSERT_NE(nullptr, context.CreateEntityUndoable("DocumentFileCommand"));
        context.MarkSceneDirty();
        ASSERT_TRUE(document.IsDirty());

        EditorCommandActionResult result = commands.ExecutePlan(
            {"Save Scene As",
             [&]() {
                 return fileCommands.RunFallbackSaveSceneAsDialog(false);
             }});
        EXPECT_TRUE(result);
        EXPECT_EQ(EditorCommandActionStatus::Succeeded, result.status);
        EXPECT_EQ(1u, providerPtr->saveCount);
        EXPECT_EQ("Untitled.rvxscene",
                  providerPtr->lastSaveDesc.defaultPath.filename().string());
        ASSERT_TRUE(document.HasScenePath());
        EXPECT_TRUE(std::filesystem::equivalent(document.GetScenePath(),
                                                scenePath));
        EXPECT_FALSE(document.IsDirty());
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Success,
                  notifications.GetLatest()->severity);
        EXPECT_GE(refreshCount, 2u);
        ASSERT_FALSE(settings.GetRecentSceneDirectories().empty());
        EXPECT_TRUE(std::filesystem::equivalent(
            settings.GetRecentSceneDirectories().front(),
            scenePath.parent_path()));

        EditorFilePickerDialogDesc pickerDesc;
        fileCommands.PopulateSceneFilePickerRecentDirectories(pickerDesc);
        EXPECT_EQ(scenePath.parent_path(), pickerDesc.picker.initialDirectory);
        ASSERT_FALSE(pickerDesc.picker.recentDirectories.empty());
        EXPECT_EQ(scenePath.parent_path(),
                  pickerDesc.picker.recentDirectories.front());

        EditorFilePickerDialogResult openPickerResult;
        openPickerResult.accepted = true;
        openPickerResult.path = scenePath;
        result = fileCommands.CompleteOpenSceneFilePickerResult(
            openPickerResult,
            true);
        EXPECT_TRUE(result);
        EXPECT_EQ(EditorCommandActionStatus::Succeeded, result.status);
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Success,
                  notifications.GetLatest()->severity);

        EditorFilePickerDialogResult cancelPickerResult;
        result = fileCommands.CompleteOpenSceneFilePickerResult(
            cancelPickerResult,
            true);
        EXPECT_FALSE(result);
        EXPECT_EQ(EditorCommandActionStatus::Cancelled, result.status);
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Info,
                  notifications.GetLatest()->severity);
    }

