    TEST_F(EditorContextValidation,
           EditorAutomationScenarioRunnerParsesAndPreparesShortcutAutosaveSettings)
    {
        EditorAutomationScenarioType scenario =
            EditorAutomationScenarioType::None;
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "shortcut-autosave-write",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::ShortcutAutosaveWrite,
                  scenario);
        EXPECT_STREQ("shortcut-autosave-write",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_TRUE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "open-native-panel",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::OpenNativePanel,
                  scenario);
        EXPECT_STREQ("open-native-panel",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_FALSE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_EQ("view.nativePanel.native.preferences",
                  MakeNativeUIPanelViewCommandId("native.preferences"));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "command-surface-click",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::CommandSurfaceClick,
                  scenario);
        EXPECT_STREQ("command-surface-click",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_FALSE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "command-menu-open",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::CommandMenuOpen,
                  scenario);
        EXPECT_STREQ("command-menu-open",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_FALSE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "command-palette-open",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::CommandPaletteOpen,
                  scenario);
        EXPECT_STREQ("command-palette-open",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_FALSE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "open-scene-file-picker",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::OpenSceneFilePicker,
                  scenario);
        EXPECT_STREQ("open-scene-file-picker",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_FALSE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "save-scene-as-file-picker",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::SaveSceneAsFilePicker,
                  scenario);
        EXPECT_STREQ("save-scene-as-file-picker",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_FALSE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_TRUE(TryParseEditorAutomationScenario(
            "ui-scale-adjust",
            scenario));
        EXPECT_EQ(EditorAutomationScenarioType::UIScaleAdjust,
                  scenario);
        EXPECT_STREQ("ui-scale-adjust",
                     GetEditorAutomationScenarioName(scenario));
        EXPECT_TRUE(EditorAutomationScenarioRequiresSettingsPath(scenario));
        EXPECT_FALSE(TryParseEditorAutomationScenario(
            "shortcut-autosave-toggle-only",
            scenario));

        const auto root =
            MakeTempScenePath("rvx_editor_automation_runner_settings");
        const auto settingsPath = root / "Config" / "EditorSettings.json";
        RemoveDirectory(root);
        std::filesystem::create_directories(settingsPath.parent_path());

        EditorSettingsService settings(settingsPath);
        ASSERT_TRUE(settings.Load()) << settings.GetLastError();
        settings.SetShortcutProfileAutosaveEnabled(true);
        settings.SetShortcutProfileAutosaveDebounceSeconds(8.0f);
        ASSERT_TRUE(settings.Save()) << settings.GetLastError();

        EditorAutomationScenarioRunner runner;
        runner.Reset(EditorAutomationScenarioType::OpenNativePanel,
                     "native.preferences");
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_FALSE(runner.HasFailed());
        EXPECT_EQ("native.preferences", runner.GetTarget());
        EXPECT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();

        runner.Reset(EditorAutomationScenarioType::CommandSurfaceClick,
                     "file:file.newScene");
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_FALSE(runner.HasFailed());
        EXPECT_EQ("file:file.newScene", runner.GetTarget());
        EXPECT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();

        runner.Reset(EditorAutomationScenarioType::CommandMenuOpen,
                     "file");
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_FALSE(runner.HasFailed());
        EXPECT_EQ("file", runner.GetTarget());
        EXPECT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();

        runner.Reset(EditorAutomationScenarioType::SaveSceneAsFilePicker,
                     "AutomationTarget.rvxscene",
                     true);
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_FALSE(runner.HasFailed());
        EXPECT_EQ("AutomationTarget.rvxscene", runner.GetTarget());
        EXPECT_TRUE(runner.ShouldConfirmOverwrite());
        EXPECT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();

        settings.SetUIScaleFactor(2.0f);
        ASSERT_TRUE(settings.Save()) << settings.GetLastError();
        runner.Reset(EditorAutomationScenarioType::UIScaleAdjust);
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_FALSE(runner.HasFailed());
        EXPECT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();
        EXPECT_FLOAT_EQ(RVX_EDITOR_DEFAULT_UI_SCALE_FACTOR,
                        settings.GetUIScaleFactor());

        runner.Reset(EditorAutomationScenarioType::ShortcutAutosaveWrite);
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_FALSE(runner.HasFailed());
        EXPECT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();
        EXPECT_FALSE(settings.IsShortcutProfileAutosaveEnabled());
        EXPECT_FLOAT_EQ(0.0f,
                        settings.GetShortcutProfileAutosaveDebounceSeconds());

        EditorSettingsService loaded(settingsPath);
        ASSERT_TRUE(loaded.Load()) << loaded.GetLastError();
        EXPECT_FLOAT_EQ(RVX_EDITOR_DEFAULT_UI_SCALE_FACTOR,
                        loaded.GetUIScaleFactor());
        EXPECT_FALSE(loaded.IsShortcutProfileAutosaveEnabled());
        EXPECT_FLOAT_EQ(0.0f,
                        loaded.GetShortcutProfileAutosaveDebounceSeconds());

        runner.Reset(EditorAutomationScenarioType::None);
        EXPECT_FALSE(runner.HasScenario());
        EXPECT_TRUE(runner.IsComplete());
        EXPECT_TRUE(runner.PrepareSettings(settings));

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorAutomationScenarioServiceOwnsRunLifecycle)
    {
        const auto root =
            MakeTempScenePath("rvx_editor_automation_scenario_service");
        const auto settingsPath = root / "Config" / "EditorSettings.json";
        RemoveDirectory(root);
        std::filesystem::create_directories(settingsPath.parent_path());

        EditorSettingsService settings(settingsPath);
        ASSERT_TRUE(settings.Load()) << settings.GetLastError();
        settings.SetShortcutProfileAutosaveEnabled(true);
        settings.SetShortcutProfileAutosaveDebounceSeconds(3.0f);
        ASSERT_TRUE(settings.Save()) << settings.GetLastError();

        EditorAutomationScenarioService service;
        EXPECT_FALSE(service.HasScenario());
        EXPECT_TRUE(service.PrepareSettings(nullptr));

        EditorAutomationScenarioAdvanceResult inactiveAdvance =
            service.Advance({});
        EXPECT_FALSE(inactiveAdvance.scenarioActive);
        EXPECT_FALSE(inactiveAdvance.advanced);

        service.Configure(EditorAutomationScenarioType::ShortcutAutosaveWrite);
        EXPECT_TRUE(service.HasScenario());
        EXPECT_EQ(EditorAutomationScenarioType::ShortcutAutosaveWrite,
                  service.GetScenario());
        EXPECT_TRUE(service.PrepareSettings(&settings))
            << service.GetError();
        EXPECT_FALSE(settings.IsShortcutProfileAutosaveEnabled());
        EXPECT_FLOAT_EQ(0.0f,
                        settings.GetShortcutProfileAutosaveDebounceSeconds());

        service.Configure(EditorAutomationScenarioType::OpenNativePanel,
                          "native.preferences");
        EXPECT_TRUE(service.HasScenario());
        EXPECT_EQ(EditorAutomationScenarioType::OpenNativePanel,
                  service.GetScenario());
        EXPECT_FALSE(service.IsComplete());
        EXPECT_FALSE(service.HasFailed());

        EditorAutomationScenarioAdvanceResult waitingAdvance =
            service.Advance({});
        EXPECT_TRUE(waitingAdvance.scenarioActive);
        EXPECT_TRUE(waitingAdvance.advanced);
        EXPECT_FALSE(waitingAdvance.complete);
        EXPECT_FALSE(waitingAdvance.failed);
        EXPECT_FALSE(waitingAdvance.requestStop);

        service.MarkIncompleteBeforeExit();
        EXPECT_TRUE(service.HasFailed());
        EXPECT_NE(std::string::npos,
                  service.GetError().find("open-native-panel"));

        service.Configure(EditorAutomationScenarioType::None);
        EXPECT_FALSE(service.HasScenario());
        EXPECT_TRUE(service.IsComplete());
        EXPECT_FALSE(service.HasFailed());

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorAutomationScenarioRunnerAdjustsAndPersistsUIScale)
    {
        const auto root =
            MakeTempScenePath("rvx_editor_automation_ui_scale");
        const auto settingsPath = root / "Config" / "EditorSettings.json";
        RemoveDirectory(root);
        std::filesystem::create_directories(settingsPath.parent_path());

        EditorSettingsService settings(settingsPath);
        ASSERT_TRUE(settings.Load()) << settings.GetLastError();
        settings.SetUIScaleFactor(2.0f);
        ASSERT_TRUE(settings.Save()) << settings.GetLastError();

        NativeEditorUIBackend backend;
        NativeEditorUIBackendDesc desc;
        desc.host.surfaceWidth = 900;
        desc.host.surfaceHeight = 620;
        ASSERT_TRUE(backend.Initialize(desc));
        backend.RegisterPanel(
            std::make_shared<NativeEditorPreferencesPanel>(&settings));

        EditorAutomationScenarioRunner runner;
        runner.Reset(EditorAutomationScenarioType::UIScaleAdjust);
        ASSERT_TRUE(runner.PrepareSettings(settings)) << runner.GetError();
        EXPECT_FLOAT_EQ(RVX_EDITOR_DEFAULT_UI_SCALE_FACTOR,
                        settings.GetUIScaleFactor());

        EditorAutomationScenarioContext context;
        context.uiBackend = &backend;
        context.settingsService = &settings;

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 900;
        frameDesc.surfaceHeight = 620;
        frameDesc.deltaTime = 0.016f;

        for (uint32 frameIndex = 0; frameIndex < 10u && !runner.IsComplete();
             ++frameIndex)
        {
            frameDesc.scaleFactor = settings.GetUIScaleFactor();
            ASSERT_TRUE(backend.BeginFrame(frameDesc));
            backend.BuildPanels();
            runner.Advance(context);
            EXPECT_FALSE(runner.HasFailed()) << runner.GetError();
            backend.EndFrame();
        }

        EXPECT_TRUE(runner.IsComplete()) << runner.GetError();
        EXPECT_FALSE(runner.HasFailed()) << runner.GetError();
        EXPECT_FLOAT_EQ(RVX_EDITOR_DEFAULT_UI_SCALE_FACTOR,
                        settings.GetUIScaleFactor());

        EditorSettingsService loaded(settingsPath);
        ASSERT_TRUE(loaded.Load()) << loaded.GetLastError();
        EXPECT_FLOAT_EQ(RVX_EDITOR_DEFAULT_UI_SCALE_FACTOR,
                        loaded.GetUIScaleFactor());

        ASSERT_NE(nullptr, backend.GetHost());
        const std::vector<EditorUICommandHistoryEntry>& history =
            backend.GetHost()->GetCommandHistory();
        ASSERT_FALSE(history.empty());
        EXPECT_TRUE(history.back().diagnostic);
        EXPECT_TRUE(history.back().diagnosticSucceeded);
        EXPECT_NE(std::string::npos,
                  history.back().diagnosticMessage.find(
                      "UI scale adjusted and reset"));

        backend.Shutdown();
        RemoveDirectory(root);
    }

