    TEST_F(EditorContextValidation, EditorContextPublishesTypedChangeRevisions)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();

        std::vector<EditorContextChangeEvent> events;
        const uint64 callbackId =
            context.AddChangeCallback([&events](const EditorContextChangeEvent& event) {
                events.push_back(event);
            });
        ASSERT_NE(0u, callbackId);

        const uint64 initialRevision = context.GetChangeRevision();
        const uint64 initialSceneRevision = context.GetSceneRevision();
        context.NewScene();
        EXPECT_GT(context.GetChangeRevision(), initialRevision);
        EXPECT_GT(context.GetSceneRevision(), initialSceneRevision);
        ASSERT_FALSE(events.empty());
        EXPECT_TRUE(std::any_of(events.begin(),
                                events.end(),
                                [](const EditorContextChangeEvent& event) {
                                    return HasEditorContextChangeReason(
                                        event.reasonMask,
                                        EditorContextChangeReason::Scene);
                                }));

        auto* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);
        ActorSpawnParams params;
        params.name = "ChangeRevisionEntity";
        SceneEntity* entity = sceneManager->SpawnActor(params);
        ASSERT_NE(nullptr, entity);

        const uint64 selectionRevision = context.GetSelectionRevision();
        context.SelectEntity(entity);
        EXPECT_GT(context.GetSelectionRevision(), selectionRevision);
        ASSERT_FALSE(events.empty());
        EXPECT_TRUE(HasEditorContextChangeReason(
            events.back().reasonMask,
            EditorContextChangeReason::Selection));

        const uint64 dirtySceneRevision = context.GetSceneRevision();
        context.MarkSceneDirty();
        EXPECT_GT(context.GetSceneRevision(), dirtySceneRevision);
        EXPECT_TRUE(HasEditorContextChangeReason(
            events.back().reasonMask,
            EditorContextChangeReason::SceneDirty));

        const EditorContext::GizmoMode nextMode =
            context.GetGizmoMode() == EditorContext::GizmoMode::Translate
                ? EditorContext::GizmoMode::Rotate
                : EditorContext::GizmoMode::Translate;
        context.SetGizmoMode(nextMode);
        EXPECT_TRUE(HasEditorContextChangeReason(
            events.back().reasonMask,
            EditorContextChangeReason::ToolSettings));

        const size_t countBeforeRemove = events.size();
        EXPECT_TRUE(context.RemoveChangeCallback(callbackId));
        context.ClearSelection();
        context.SetGizmoMode(EditorContext::GizmoMode::Translate);
        EXPECT_EQ(countBeforeRemove, events.size());
        EXPECT_FALSE(context.RemoveChangeCallback(callbackId));
    }

    TEST_F(EditorContextValidation, SaveLoadRoundTripsSceneEntityHierarchyAndTransforms)
    {
        const auto scenePath = MakeTempScenePath("rvx_editor_context_roundtrip.rvxscene");
        RemoveFile(scenePath);

        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();

        auto* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams rootParams;
        rootParams.name = "Root";
        auto* root = sceneManager->SpawnActor(rootParams);
        ASSERT_NE(nullptr, root);
        root->SetPosition(Vec3(1.0f, 2.0f, 3.0f));
        root->SetRotation(QuatFromEuler(Vec3(0.25f, 0.5f, 0.75f)));
        root->SetScale(Vec3(2.0f, 3.0f, 4.0f));
        root->SetLayer(3);
        auto* actorPayload = root->AddComponent<EditorPayloadActorComponent>();
        ASSERT_NE(nullptr, actorPayload);
        actorPayload->SetName("ActorPayloadSlot");
        actorPayload->SetEnabled(false);
        actorPayload->payload = "actor payload with ] bracket, \"quote\", and\nnewline";
        const Tools::AssetGUID actorAssetGuid = Tools::AssetGUID::Generate();
        actorPayload->asset = actorAssetGuid;
        const ActorComponent::ComponentId actorPayloadId =
            actorPayload->GetComponentId();

        ActorSpawnParams childParams;
        childParams.name = "Child";
        childParams.parent = root;
        auto* child = sceneManager->SpawnActor(childParams);
        ASSERT_NE(nullptr, child);
        child->SetPosition(Vec3(-1.0f, 4.0f, 0.5f));
        child->SetScale(Vec3(0.5f, 0.75f, 1.25f));
        child->SetActive(false);
        auto* legacyPayload = child->AddComponent<EditorPayloadLegacyComponent>();
        ASSERT_NE(nullptr, legacyPayload);
        legacyPayload->SetName("LegacyPayloadSlot");
        legacyPayload->SetEnabled(false);
        legacyPayload->payload = "legacy payload with { object } and tab\tmarker";
        const Tools::AssetGUID legacyAssetGuid = Tools::AssetGUID::Generate();
        legacyPayload->asset = legacyAssetGuid;
        const ActorComponent::ComponentId legacyPayloadId =
            legacyPayload->GetComponentId();

        context.MarkSceneDirty();
        ASSERT_TRUE(context.IsSceneDirty());
        ASSERT_TRUE(context.SaveScene(scenePath.string()));
        EXPECT_FALSE(context.IsSceneDirty());

        {
            std::ifstream savedFile(scenePath);
            std::ostringstream savedContents;
            savedContents << savedFile.rdbuf();
            const std::string savedScene = savedContents.str();
            EXPECT_NE(std::string::npos, savedScene.find("\"componentId\""));
            EXPECT_NE(std::string::npos, savedScene.find(std::to_string(actorPayloadId)));
            EXPECT_NE(std::string::npos, savedScene.find(std::to_string(legacyPayloadId)));
            EXPECT_NE(std::string::npos, savedScene.find("\"assetRefs\""));
            EXPECT_NE(std::string::npos, savedScene.find(actorAssetGuid.ToString()));
            EXPECT_NE(std::string::npos, savedScene.find(legacyAssetGuid.ToString()));
        }

        context.SelectEntity(root);
        ASSERT_TRUE(context.LoadScene(scenePath.string()));

        auto* loadedScene = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, loadedScene);
        EXPECT_EQ(SelectionType::None, context.GetSelectionType());
        EXPECT_EQ(static_cast<size_t>(2), loadedScene->GetEntityCount());

        SceneEntity* loadedRoot = nullptr;
        SceneEntity* loadedChild = nullptr;
        loadedScene->ForEachEntity([&](SceneEntity* entity) {
            if (entity->GetName() == "Root")
            {
                loadedRoot = entity;
            }
            else if (entity->GetName() == "Child")
            {
                loadedChild = entity;
            }
        });

        ASSERT_NE(nullptr, loadedRoot);
        ASSERT_NE(nullptr, loadedChild);
        EXPECT_EQ(nullptr, loadedRoot->GetParent());
        EXPECT_EQ(loadedRoot, loadedChild->GetParent());
        EXPECT_EQ(static_cast<size_t>(1), loadedRoot->GetChildCount());
        EXPECT_EQ(loadedChild, loadedRoot->GetChildren()[0]);
        EXPECT_TRUE(loadedRoot->IsActive());
        EXPECT_FALSE(loadedChild->IsActive());
        EXPECT_TRUE(loadedRoot->IsInLayer(3));

        EXPECT_EQ(Vec3(1.0f, 2.0f, 3.0f), loadedRoot->GetPosition());
        EXPECT_EQ(Vec3(2.0f, 3.0f, 4.0f), loadedRoot->GetScale());
        EXPECT_EQ(Vec3(-1.0f, 4.0f, 0.5f), loadedChild->GetPosition());
        EXPECT_EQ(Vec3(0.5f, 0.75f, 1.25f), loadedChild->GetScale());

        auto* loadedActorPayload = loadedRoot->GetComponent<EditorPayloadActorComponent>();
        ASSERT_NE(nullptr, loadedActorPayload);
        EXPECT_EQ(actorPayloadId, loadedActorPayload->GetComponentId());
        EXPECT_EQ("ActorPayloadSlot", loadedActorPayload->GetName());
        EXPECT_FALSE(loadedActorPayload->IsEnabled());
        EXPECT_EQ("actor payload with ] bracket, \"quote\", and\nnewline",
                  loadedActorPayload->payload);
        EXPECT_EQ(actorAssetGuid, loadedActorPayload->asset);

        auto* loadedLegacyPayload = loadedChild->GetComponent<EditorPayloadLegacyComponent>();
        ASSERT_NE(nullptr, loadedLegacyPayload);
        EXPECT_EQ(legacyPayloadId, loadedLegacyPayload->GetComponentId());
        EXPECT_EQ("LegacyPayloadSlot", loadedLegacyPayload->GetName());
        EXPECT_FALSE(loadedLegacyPayload->IsEnabled());
        EXPECT_EQ("legacy payload with { object } and tab\tmarker",
                  loadedLegacyPayload->payload);
        EXPECT_EQ(legacyAssetGuid, loadedLegacyPayload->asset);

        RemoveFile(scenePath);
    }

#if RVX_EDITOR_ENABLE_LEGACY_IMGUI
    TEST_F(EditorContextValidation, AssetBrowserSelectsAssetsByDatabaseGuid)
    {
        const auto projectPath = MakeTempScenePath("rvx_editor_asset_browser_guid_project");
        const auto assetsPath = projectPath / "Assets";
        const auto texturePath = assetsPath / "Textures" / "Albedo.png";
        const auto outsidePath = projectPath / "Outside.png";
        RemoveDirectory(projectPath);
        WriteTextFile(texturePath, "not a real texture");
        WriteTextFile(outsidePath, "outside asset root");

        auto& context = EditorContext::Get();
        context.CloseProject();
        ASSERT_TRUE(context.OpenProject(projectPath.string()));

        const auto* textureEntry =
            context.GetAssetDatabase().GetAssetByPath("Textures/Albedo.png");
        ASSERT_NE(nullptr, textureEntry);
        ASSERT_TRUE(textureEntry->guid.IsValid());

        AssetBrowserPanel browser;
        browser.OnInit();

        EXPECT_EQ("Textures/Albedo.png",
                  AssetBrowserPanel::MakeAssetDatabasePath(texturePath, assetsPath));
        EXPECT_TRUE(AssetBrowserPanel::MakeAssetDatabasePath(outsidePath, assetsPath).empty());
        EXPECT_STREQ("RVX_ASSET_GUID", AssetBrowserPanel::GetAssetGuidDragDropPayloadType());

        const Tools::AssetGUID resolvedGuid = browser.ResolveAssetGuid(texturePath);
        EXPECT_EQ(textureEntry->guid, resolvedGuid);

        EXPECT_TRUE(browser.SelectAssetPath(texturePath));
        EXPECT_EQ(SelectionType::Asset, context.GetSelectionType());
        EXPECT_EQ(textureEntry->guid, context.GetSelectedAsset());
        EXPECT_TRUE(context.GetSelectedEntities().empty());

        EXPECT_FALSE(browser.SelectAssetPath(assetsPath / "Textures"));
        EXPECT_FALSE(browser.SelectAssetPath(outsidePath));
        EXPECT_EQ(textureEntry->guid, context.GetSelectedAsset());

        RemoveDirectory(projectPath);
    }
#endif

