    TEST_F(EditorContextValidation, EditorBuildCanDisableLegacyImGuiBridge)
    {
        const std::filesystem::path root = FindWorkspaceRoot();
        ASSERT_FALSE(root.empty());

        const std::string cmake = ReadTextFile(root / "Editor" / "CMakeLists.txt");
        const std::string app =
            ReadTextFile(root / "Editor" / "Private" / "EditorApplication.cpp");
        const std::string legacyDebugUIService =
            ReadTextFile(root / "Editor" / "Private" /
                         "EditorLegacyDebugUIService.cpp");
        const std::string registrationService =
            ReadTextFile(root / "Editor" / "Private" /
                         "EditorNativePanelRegistrationService.cpp");
        const std::string appHeader =
            ReadTextFile(root / "Editor" / "Include" / "Editor" /
                         "EditorApplication.h");
        const std::string viewport =
            ReadTextFile(root / "Editor" / "Private" / "Panels" / "Viewport.cpp");
        const std::string console =
            ReadTextFile(root / "Editor" / "Private" / "Panels" / "Console.cpp");
        const std::string theme =
            ReadTextFile(root / "Editor" / "Private" / "EditorTheme.cpp");
        ASSERT_FALSE(cmake.empty());
        ASSERT_FALSE(app.empty());
        ASSERT_FALSE(legacyDebugUIService.empty());
        ASSERT_FALSE(registrationService.empty());
        ASSERT_FALSE(appHeader.empty());
        ASSERT_FALSE(viewport.empty());
        ASSERT_FALSE(console.empty());
        ASSERT_FALSE(theme.empty());

        const size_t option =
            cmake.find("option(RVX_EDITOR_ENABLE_LEGACY_IMGUI");
        ASSERT_NE(std::string::npos, option);
        const size_t unconditionalViewport =
            cmake.find("Private/Panels/Viewport.cpp", option);
        const size_t legacySources =
            cmake.find("if(RVX_EDITOR_ENABLE_LEGACY_IMGUI)", option);
        ASSERT_NE(std::string::npos, unconditionalViewport);
        ASSERT_NE(std::string::npos, legacySources);
        EXPECT_LT(unconditionalViewport, legacySources);
        EXPECT_NE(cmake.find("Private/UI/DebugImGuiLayer.cpp", legacySources),
                  std::string::npos);
        EXPECT_NE(cmake.find("Private/Panels/SceneHierarchy.cpp", legacySources),
                  std::string::npos);

        const size_t compileDefs =
            cmake.find("target_compile_definitions(RVX_Editor PUBLIC");
        ASSERT_NE(std::string::npos, compileDefs);
        EXPECT_NE(cmake.find(
                      "RVX_EDITOR_ENABLE_LEGACY_IMGUI=$<BOOL:${RVX_EDITOR_ENABLE_LEGACY_IMGUI}>",
                      compileDefs),
                  std::string::npos);
        const size_t packageGate =
            cmake.find("if(RVX_EDITOR_ENABLE_LEGACY_IMGUI)", compileDefs);
        ASSERT_NE(std::string::npos, packageGate);
        EXPECT_NE(cmake.find("find_package(imgui CONFIG REQUIRED)", packageGate),
                  std::string::npos);
        EXPECT_NE(cmake.find("find_package(imguizmo CONFIG REQUIRED)", packageGate),
                  std::string::npos);
        EXPECT_NE(cmake.find("imgui::imgui", packageGate), std::string::npos);
        EXPECT_NE(cmake.find("imguizmo::imguizmo", packageGate), std::string::npos);

        const size_t debugInclude = app.find("#include \"Editor/UI/DebugImGuiLayer.h\"");
        const size_t imguiInclude = app.find("#include <imgui.h>");
        const size_t imguizmoInclude = viewport.find("#include <ImGuizmo.h>");
        ASSERT_NE(std::string::npos, debugInclude);
        ASSERT_NE(std::string::npos, imguiInclude);
        ASSERT_NE(std::string::npos, imguizmoInclude);
        EXPECT_NE(app.rfind("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI", debugInclude),
                  std::string::npos);
        EXPECT_NE(app.rfind("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI", imguiInclude),
                  std::string::npos);
        EXPECT_NE(viewport.rfind("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI", imguizmoInclude),
                  std::string::npos);

        EXPECT_NE(appHeader.find("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI\n"
                                 "class DebugImGuiLayer;"),
                  std::string::npos);
        EXPECT_NE(appHeader.find("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI\n"
                                 "    // Legacy/debug UI bridge"),
                  std::string::npos);
        const size_t nativeOnlyFallback =
            legacyDebugUIService.find("#else");
        const size_t drawPanels =
            legacyDebugUIService.find("if (desc.drawPanels)",
                                      nativeOnlyFallback);
        ASSERT_NE(std::string::npos, nativeOnlyFallback);
        ASSERT_NE(std::string::npos, drawPanels);
        const std::string nativeOnlyRenderFallback =
            legacyDebugUIService.substr(nativeOnlyFallback,
                                        drawPanels - nativeOnlyFallback);
        EXPECT_NE(nativeOnlyRenderFallback.find(
                      "MarkNativeOnlyDefaultFramebufferClear("),
                  std::string::npos);
        EXPECT_NE(nativeOnlyRenderFallback.find(
                      "result.nativeOnlyDefaultFramebufferClearMarked = true;"),
                  std::string::npos);

        const size_t registerDebug = registrationService.find(
            "void EditorNativePanelRegistrationService::RegisterDebugViewCommands()");
        const size_t refreshViewCommands = registrationService.find(
            "void EditorNativePanelRegistrationService::RefreshViewCommandStates(",
            registerDebug);
        ASSERT_NE(std::string::npos, registerDebug);
        ASSERT_NE(std::string::npos, refreshViewCommands);
        const std::string registerDebugBody =
            registrationService.substr(registerDebug,
                                       refreshViewCommands - registerDebug);
        EXPECT_NE(registerDebugBody.find("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI"),
                  std::string::npos);
        EXPECT_NE(registerDebugBody.find("m_showDemoWindow"), std::string::npos);
        EXPECT_NE(registerDebugBody.find("m_showMetricsWindow"), std::string::npos);

        EXPECT_NE(viewport.find("bool legacyGizmoUsing = false;"), std::string::npos);
        EXPECT_NE(viewport.find("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI\n"
                                "    legacyGizmoUsing = ImGuizmo::IsUsing();"),
                  std::string::npos);
        EXPECT_NE(viewport.find("Legacy ImGui viewport drawing is disabled"),
                  std::string::npos);
        EXPECT_NE(console.find("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI\n"
                               "#include <imgui.h>"),
                  std::string::npos);
        EXPECT_NE(console.find("#else\n"
                               "void ConsolePanel::OnGUI() {}"),
                  std::string::npos);
        EXPECT_NE(theme.find("#if RVX_EDITOR_ENABLE_LEGACY_IMGUI\n"
                             "#include <imgui.h>"),
                  std::string::npos);
    }

