    TEST_F(EditorContextValidation,
           EditorApplicationDelegatesUpdateFrameToService)
    {
        const std::filesystem::path root = FindWorkspaceRoot();
        ASSERT_FALSE(root.empty());

        const std::string source =
            ReadTextFile(root / "Editor" / "Private" /
                         "EditorApplication.cpp");
        ASSERT_FALSE(source.empty());
        const std::string header =
            ReadTextFile(root / "Editor" / "Include" / "Editor" /
                         "EditorApplication.h");
        ASSERT_FALSE(header.empty());
        const std::string updateHeader =
            ReadTextFile(root / "Editor" / "Include" / "Editor" /
                         "EditorUpdateService.h");
        ASSERT_FALSE(updateHeader.empty());
        const std::string updateSource =
            ReadTextFile(root / "Editor" / "Private" /
                         "EditorUpdateService.cpp");
        ASSERT_FALSE(updateSource.empty());
        const std::string cmake =
            ReadTextFile(root / "Editor" / "CMakeLists.txt");
        ASSERT_FALSE(cmake.empty());

        const size_t update =
            source.find("void EditorApplication::Update(float deltaTime)");
        ASSERT_NE(std::string::npos, update);
        const size_t render =
            source.find("void EditorApplication::Render()", update);
        ASSERT_NE(std::string::npos, render);
        const std::string updateBody = source.substr(update, render - update);

        EXPECT_NE(header.find("#include \"Editor/EditorUpdateService.h\""),
                  std::string::npos);
        EXPECT_NE(header.find("EditorUpdateService m_updateService;"),
                  std::string::npos);
        EXPECT_NE(cmake.find("Private/EditorUpdateService.cpp"),
                  std::string::npos);
        EXPECT_NE(updateBody.find("EditorUpdateDesc updateDesc;"),
                  std::string::npos);
        EXPECT_NE(updateBody.find("updateDesc.editorUIBackend = "
                                  "m_editorUIBackend.get();"),
                  std::string::npos);
        EXPECT_NE(updateBody.find("updateDesc.nativeUIFrameService = "
                                  "&m_nativeUIFrameService;"),
                  std::string::npos);
        EXPECT_NE(updateBody.find("updateDesc.shortcutProfileLifecycleService = "
                                  "&m_shortcutProfileLifecycleService;"),
                  std::string::npos);
        EXPECT_NE(updateBody.find("updateDesc.legacyPanels = &m_panels;"),
                  std::string::npos);
        EXPECT_NE(updateBody.find("m_updateService.Update(updateDesc)"),
                  std::string::npos);
        EXPECT_EQ(updateBody.find("m_nativeUIFrameService.Update("),
                  std::string::npos);
        EXPECT_EQ(updateBody.find("panel->OnUpdate("), std::string::npos);
        EXPECT_EQ(updateBody.find("for (auto& panel"), std::string::npos);

        EXPECT_NE(updateHeader.find("struct EditorUpdateDesc"),
                  std::string::npos);
        EXPECT_NE(updateHeader.find("struct EditorUpdateResult"),
                  std::string::npos);
        EXPECT_NE(updateHeader.find("class EditorUpdateService"),
                  std::string::npos);
        EXPECT_NE(updateSource.find("desc.nativeUIFrameService->Update("),
                  std::string::npos);
        EXPECT_NE(updateSource.find("panel->OnUpdate(desc.deltaTime)"),
                  std::string::npos);
        EXPECT_EQ(updateSource.find("EditorApplication"), std::string::npos);
    }

