    TEST_F(EditorContextValidation,
           EditorApplicationDelegatesRenderShutdownToService)
    {
        const auto root = FindWorkspaceRoot();
        ASSERT_FALSE(root.empty());

        const std::string source =
            ReadTextFile(root / "Editor" / "Private" /
                         "EditorApplication.cpp");
        ASSERT_FALSE(source.empty());
        const std::string header =
            ReadTextFile(root / "Editor" / "Include" / "Editor" /
                         "EditorApplication.h");
        ASSERT_FALSE(header.empty());
        const std::string cmake =
            ReadTextFile(root / "Editor" / "CMakeLists.txt");
        ASSERT_FALSE(cmake.empty());
        const std::string renderShutdownSource =
            ReadTextFile(root / "Editor" / "Private" /
                         "EditorRenderShutdownService.cpp");
        ASSERT_FALSE(renderShutdownSource.empty());
        const std::string renderShutdownHeader =
            ReadTextFile(root / "Editor" / "Include" / "Editor" /
                         "EditorRenderShutdownService.h");
        ASSERT_FALSE(renderShutdownHeader.empty());

        EXPECT_NE(header.find("#include \"Editor/EditorRenderShutdownService.h\""),
                  std::string::npos);
        EXPECT_NE(header.find("EditorRenderShutdownService "
                              "m_renderShutdownService;"),
                  std::string::npos);
        EXPECT_NE(cmake.find("Private/EditorRenderShutdownService.cpp"),
                  std::string::npos);

        const size_t shutdown =
            source.find("void EditorApplication::Shutdown()");
        ASSERT_NE(std::string::npos, shutdown);
        const size_t beginFrame =
            source.find("void EditorApplication::BeginFrame()", shutdown);
        ASSERT_NE(std::string::npos, beginFrame);
        const std::string shutdownBody =
            source.substr(shutdown, beginFrame - shutdown);

        EXPECT_NE(shutdownBody.find("EditorRenderShutdownDesc "
                                    "renderShutdownDesc;"),
                  std::string::npos);
        EXPECT_NE(shutdownBody.find("renderShutdownDesc.renderContext = "
                                    "&m_renderContext;"),
                  std::string::npos);
        EXPECT_NE(shutdownBody.find("renderShutdownDesc.sceneRenderer = "
                                    "&m_sceneRenderer;"),
                  std::string::npos);
        EXPECT_NE(shutdownBody.find("renderShutdownDesc.runtimeUIRenderer = "
                                    "&m_runtimeUIRenderer;"),
                  std::string::npos);
        EXPECT_NE(shutdownBody.find("renderShutdownDesc.editorUIRenderer = "
                                    "&m_editorUIRenderer;"),
                  std::string::npos);
        EXPECT_NE(shutdownBody.find("m_renderShutdownService."
                                    "PrepareForPanelShutdown("),
                  std::string::npos);
        EXPECT_NE(shutdownBody.find("m_renderShutdownService."
                                    "ShutdownResources("),
                  std::string::npos);

        const size_t prepareCall =
            shutdownBody.find("m_renderShutdownService."
                              "PrepareForPanelShutdown(");
        const size_t unbindPanels =
            shutdownBody.find("BindRenderDeviceToViewportPanels(nullptr);");
        const size_t panelsClear = shutdownBody.find("m_panels.clear();");
        const size_t shutdownCall =
            shutdownBody.find("m_renderShutdownService.ShutdownResources(");
        ASSERT_NE(std::string::npos, prepareCall);
        ASSERT_NE(std::string::npos, unbindPanels);
        ASSERT_NE(std::string::npos, panelsClear);
        ASSERT_NE(std::string::npos, shutdownCall);
        EXPECT_LT(prepareCall, unbindPanels);
        EXPECT_LT(unbindPanels, panelsClear);
        EXPECT_LT(panelsClear, shutdownCall);

        EXPECT_EQ(shutdownBody.find("m_renderContext->WaitIdle()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find(
                      "m_sceneRenderer->ClearExternalRenderTarget()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_sceneRenderer->Shutdown()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_sceneRenderer.reset()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_runtimeUIRenderer->Shutdown()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_runtimeUIRenderer.reset()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_editorUIRenderer->Shutdown()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_editorUIRenderer.reset()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_renderContext->Shutdown()"),
                  std::string::npos);
        EXPECT_EQ(shutdownBody.find("m_renderContext.reset()"),
                  std::string::npos);

        EXPECT_NE(renderShutdownHeader.find("struct EditorRenderShutdownDesc"),
                  std::string::npos);
        EXPECT_NE(renderShutdownHeader.find(
                      "struct EditorRenderShutdownResult"),
                  std::string::npos);
        EXPECT_NE(renderShutdownHeader.find("PrepareForPanelShutdown"),
                  std::string::npos);
        EXPECT_NE(renderShutdownHeader.find("ShutdownResources"),
                  std::string::npos);
        EXPECT_NE(renderShutdownSource.find(
                      "(*desc.renderContext)->WaitIdle();"),
                  std::string::npos);
        EXPECT_NE(renderShutdownSource.find(
                      "(*desc.sceneRenderer)->ClearExternalRenderTarget();"),
                  std::string::npos);
        EXPECT_NE(renderShutdownSource.find(
                      "(*desc.sceneRenderer)->Shutdown();"),
                  std::string::npos);
        EXPECT_NE(renderShutdownSource.find(
                      "(*desc.runtimeUIRenderer)->Shutdown();"),
                  std::string::npos);
        EXPECT_NE(renderShutdownSource.find(
                      "(*desc.editorUIRenderer)->Shutdown();"),
                  std::string::npos);
        EXPECT_NE(renderShutdownSource.find(
                      "(*desc.renderContext)->Shutdown();"),
                  std::string::npos);
        EXPECT_EQ(renderShutdownSource.find("EditorApplication"),
                  std::string::npos);
    }

