        EXPECT_NE(renderBody.find("m_debugImGuiFrameActive = "
                                  "renderFrameResult.debugFrameActive;"),
                  std::string::npos);
        EXPECT_NE(renderFrameServiceSource.find(
                      "desc.legacyDebugUIService->RenderFrame(legacyUIDesc)"),
                  std::string::npos);
        EXPECT_NE(renderFrameServiceSource.find(
                      "result.debugFrameActive = "
                      "result.legacyUIFrameResult.debugFrameActive;"),
                  std::string::npos);

        const size_t renderFrame =
            legacyDebugUISource.find("EditorLegacyDebugUIService::RenderFrame");
        ASSERT_NE(std::string::npos, renderFrame);
        const std::string legacyRenderBody =
            legacyDebugUISource.substr(renderFrame);
        const size_t shouldRun =
            legacyRenderBody.find("if (decision.runDebugImGuiFrame && "
                                  "desc.debugImGuiLayer)");
        const size_t beginDebug =
            legacyRenderBody.find("desc.debugImGuiLayer->BeginFrame();");
        const size_t frameActive =
            legacyRenderBody.find("result.debugFrameActive = true;");
        const size_t statBegun =
            legacyRenderBody.find("MarkDebugImGuiFrameBegun(");
        ASSERT_NE(std::string::npos, shouldRun);
        ASSERT_NE(std::string::npos, beginDebug);
        ASSERT_NE(std::string::npos, frameActive);
        ASSERT_NE(std::string::npos, statBegun);
