    TEST_F(EditorContextValidation, NativeAssetBrowserBuildsSearchSelectAndContextMenu)
    {
        const auto projectPath = MakeTempScenePath("rvx_native_asset_browser_project");
        const auto assetsPath = projectPath / "Assets";
        const auto texturePath = assetsPath / "Textures" / "Albedo.png";
        const auto meshPath = assetsPath / "Models" / "Ship.gltf";
        RemoveDirectory(projectPath);
        WriteTextFile(texturePath, "not a real texture");
        WriteTextFile(meshPath, "{ \"asset\": \"not a real gltf\" }");

        auto& context = EditorContext::Get();
        context.CloseProject();
        ASSERT_TRUE(context.OpenProject(projectPath.string()));

        const Tools::AssetEntry* textureEntry =
            context.GetAssetDatabase().GetAssetByPath("Textures/Albedo.png");
        const Tools::AssetEntry* meshEntry =
            context.GetAssetDatabase().GetAssetByPath("Models/Ship.gltf");
        ASSERT_NE(nullptr, textureEntry);
        ASSERT_NE(nullptr, meshEntry);
        ASSERT_TRUE(textureEntry->guid.IsValid());
        ASSERT_TRUE(meshEntry->guid.IsValid());

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 900;
        desc.surfaceHeight = 520;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeAssetBrowserPanel>();
        NativeAssetBrowserPanel* panelPtr = panel.get();
        host.RegisterPanel(panel);
        ASSERT_EQ(panelPtr, host.GetPanel("native.assetBrowser"));
        ASSERT_NE(nullptr, host.GetDockingModel().FindPlacement("native.assetBrowser"));
        EXPECT_EQ(EditorUIPanelDockArea::Bottom,
                  host.GetDockingModel().FindPlacement("native.assetBrowser")->area);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 900;
        frameDesc.surfaceHeight = 520;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        EXPECT_NE(nullptr, canvas.FindWidget("Editor.PanelSurface.Panel.native.assetBrowser.Frame"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeAssetBrowser.Search"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeAssetBrowser.Refresh"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeAssetBrowser.ClearSelection"));
        const UI::UITheme& theme = host.GetUIContext().GetTheme();
        auto refreshButton = std::dynamic_pointer_cast<UI::Button>(
            canvas.FindWidget("NativeAssetBrowser.Refresh"));
        auto clearSelectionButton = std::dynamic_pointer_cast<UI::Button>(
            canvas.FindWidget("NativeAssetBrowser.ClearSelection"));
        ASSERT_NE(nullptr, refreshButton);
        ASSERT_NE(nullptr, clearSelectionButton);
        EXPECT_FLOAT_EQ(EditorTypography::GetFontSize(
                            theme,
                            EditorTypographyRole::Control),
                        refreshButton->GetStyle().fontSize);
        EXPECT_NEAR(EditorTypography::EstimatePaddedTextWidth(
                        refreshButton->GetText(),
                        theme,
                        EditorTypographyRole::Control,
                        82.0f,
                        128.0f),
                    refreshButton->GetWidth(),
                    0.01f);
        EXPECT_NEAR(EditorTypography::EstimatePaddedTextWidth(
                        clearSelectionButton->GetText(),
                        theme,
                        EditorTypographyRole::Control,
                        68.0f,
                        112.0f),
                    clearSelectionButton->GetWidth(),
                    0.01f);
        auto assetViewport =
            std::dynamic_pointer_cast<UI::ScrollView>(
                canvas.FindWidget("NativeAssetBrowser.Viewport"));
        ASSERT_NE(nullptr, assetViewport);
        EXPECT_GT(assetViewport->GetWheelStep(), 1.0f);
        EXPECT_NE(nullptr, canvas.FindWidget("NativeAssetBrowser.Content"));
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().totalAssetCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleAssetCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().hasListViewport);
        EXPECT_GT(panelPtr->GetLastBuildStats().listViewportHeight, 0.0f);
        EXPECT_GE(panelPtr->GetLastBuildStats().listContentHeight,
                  panelPtr->GetLastBuildStats().listViewportHeight);
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeAssetBrowser.Row." +
                                    textureEntry->guid.ToString()));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeAssetBrowser.Row." +
                                    meshEntry->guid.ToString()));

        auto clickWidget = [&canvas](const UI::Widget::Ptr& widget) {
            ASSERT_NE(nullptr, widget);
            const UI::Rect rect = widget->GetGlobalRect();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            mouseDown.position = rect.Center();
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        };
        auto rightClickWidget = [&canvas](const UI::Widget::Ptr& widget) {
            ASSERT_NE(nullptr, widget);
            const UI::Rect rect = widget->GetGlobalRect();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            mouseDown.position = rect.Center();
            mouseDown.button = static_cast<int>(UI::UIMouseButton::Right);
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        };

        clickWidget(canvas.FindWidget("NativeAssetBrowser.Row." +
                                      textureEntry->guid.ToString()));
        EXPECT_EQ(SelectionType::Asset, context.GetSelectionType());
        EXPECT_EQ(textureEntry->guid, context.GetSelectedAsset());

        clickWidget(canvas.FindWidget("NativeAssetBrowser.Search"));
        UI::UIEvent textInput;
        textInput.type = UI::UIEventType::TextInput;
        textInput.text = "Ship";
        EXPECT_TRUE(canvas.HandleEvent(textInput));
        host.BuildPanels();
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleAssetCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().hasListViewport);
        EXPECT_NE(nullptr, canvas.FindWidget("NativeAssetBrowser.Viewport"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeAssetBrowser.Content"));
        EXPECT_EQ(nullptr,
                  canvas.FindWidget("NativeAssetBrowser.Row." +
                                    textureEntry->guid.ToString()));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeAssetBrowser.Row." +
                                    meshEntry->guid.ToString()));

        rightClickWidget(canvas.FindWidget("NativeAssetBrowser.Row." +
                                           meshEntry->guid.ToString()));
        EXPECT_EQ(meshEntry->guid, context.GetSelectedAsset());
        EXPECT_TRUE(host.GetContextMenu().IsOpen());
        host.BuildPanels();
        EXPECT_TRUE(host.GetContextMenu().GetLastBuildStats().open);
        EXPECT_EQ(4u, host.GetContextMenu().GetLastBuildStats().itemCount);
        EXPECT_EQ(1u, host.GetPopupLayer().GetLastBuildStats().popupCount);
        EXPECT_NE(nullptr, canvas.FindWidget("Editor.ContextMenu.NativeAssetBrowser.Asset"));

        UI::Widget::Ptr clearItem =
            canvas.FindWidget(
                "Editor.ContextMenu.NativeAssetBrowser.Asset.Item.asset.clearSelection");
        ASSERT_NE(nullptr, clearItem);
        clickWidget(clearItem);
        EXPECT_EQ(SelectionType::None, context.GetSelectionType());
        EXPECT_FALSE(context.GetSelectedAsset().IsValid());
        EXPECT_FALSE(host.GetContextMenu().IsOpen());

        host.BuildPanels();
        EXPECT_EQ(nullptr, canvas.FindWidget("Editor.ContextMenu.NativeAssetBrowser.Asset"));

        host.EndFrame();
        host.Shutdown();
        context.CloseProject();
        RemoveDirectory(projectPath);
    }

    TEST_F(EditorContextValidation, NativeAssetBrowserCachesSnapshotsUntilDataOrFilterChanges)
    {
        const auto projectPath =
            MakeTempScenePath("rvx_native_asset_browser_cache_project");
        const auto assetsPath = projectPath / "Assets";
        const auto texturePath = assetsPath / "Textures" / "Albedo.png";
        const auto meshPath = assetsPath / "Models" / "Ship.gltf";
        const auto materialPath = assetsPath / "Materials" / "Ship.mat";
        RemoveDirectory(projectPath);
        WriteTextFile(texturePath, "not a real texture");
        WriteTextFile(meshPath, "{ \"asset\": \"not a real gltf\" }");

        auto& context = EditorContext::Get();
        context.CloseProject();
        ASSERT_TRUE(context.OpenProject(projectPath.string()));

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 900;
        desc.surfaceHeight = 520;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeAssetBrowserPanel>();
        NativeAssetBrowserPanel* panelPtr = panel.get();
        host.RegisterPanel(panel);

        auto runFrame = [&host]() {
            EditorUIFrameDesc frameDesc;
            frameDesc.surfaceWidth = 900;
            frameDesc.surfaceHeight = 520;
            frameDesc.deltaTime = 0.016f;
            ASSERT_TRUE(host.BeginFrame(frameDesc));
            host.BuildPanels();
            host.EndFrame();
        };

        runFrame();
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().totalAssetCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleAssetCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().assetSnapshotRefreshCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedAssetSnapshot);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        runFrame();
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().totalAssetCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleAssetCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().assetSnapshotRefreshCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedAssetSnapshot);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        EditorUIFrameDesc editFrame;
        editFrame.surfaceWidth = 900;
        editFrame.surfaceHeight = 520;
        editFrame.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(editFrame));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        UI::Widget::Ptr searchWidget = canvas.FindWidget("NativeAssetBrowser.Search");
        ASSERT_NE(nullptr, searchWidget);
        const UI::Rect searchRect = searchWidget->GetGlobalRect();
        UI::UIEvent mouseDown;
        mouseDown.type = UI::UIEventType::MouseDown;
        mouseDown.position = searchRect.Center();
        EXPECT_TRUE(canvas.HandleEvent(mouseDown));
        UI::UIEvent mouseUp = mouseDown;
        mouseUp.type = UI::UIEventType::MouseUp;
        EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        UI::UIEvent textInput;
        textInput.type = UI::UIEventType::TextInput;
        textInput.text = "Ship";
        EXPECT_TRUE(canvas.HandleEvent(textInput));
        host.EndFrame();

        runFrame();
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().totalAssetCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleAssetCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().assetSnapshotRefreshCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedAssetSnapshot);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        WriteTextFile(materialPath, "material");
        context.RefreshAssetDatabase();
        runFrame();
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().totalAssetCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleAssetCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().assetSnapshotRefreshCount);
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedAssetSnapshot);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        host.Shutdown();
        context.CloseProject();
        RemoveDirectory(projectPath);
    }

    TEST_F(EditorContextValidation, EditorCheckboxTogglesByMouseAndKeyboard)
    {
        UI::UIContext ui;
        UI::UIContextDesc desc;
        desc.width = 240;
        desc.height = 120;
        desc.debugName = "EditorCheckboxTest";
        ASSERT_TRUE(ui.Initialize(desc));

        uint32 changeCount = 0;
        bool lastChecked = false;
        EditorCheckbox::Ptr checkbox = EditorCheckbox::Create("Enabled");
        checkbox->SetName("EditorCheckbox.Enabled");
        checkbox->ApplyTheme(ui.GetTheme());
        checkbox->SetPosition(24.0f, 24.0f);
        checkbox->SetSize(120.0f, 28.0f);
        checkbox->SetOnCheckedChanged([&changeCount, &lastChecked](bool checked) {
            ++changeCount;
            lastChecked = checked;
        });
        ui.GetCanvas().AddWidget(checkbox);

        const UI::Rect rect = checkbox->GetGlobalRect();
        UI::UIEvent mouseDown;
        mouseDown.type = UI::UIEventType::MouseDown;
        mouseDown.position = rect.Center();
        mouseDown.button = static_cast<int>(UI::UIMouseButton::Left);
        EXPECT_TRUE(ui.GetCanvas().HandleEvent(mouseDown));
        UI::UIEvent mouseUp = mouseDown;
        mouseUp.type = UI::UIEventType::MouseUp;
        EXPECT_TRUE(ui.GetCanvas().HandleEvent(mouseUp));
        EXPECT_TRUE(checkbox->IsChecked());
        EXPECT_TRUE(lastChecked);
        EXPECT_EQ(1u, changeCount);
        ASSERT_NE(nullptr, ui.GetCanvas().GetFocusedWidget());
        EXPECT_EQ("EditorCheckbox.Enabled", ui.GetCanvas().GetFocusedWidget()->GetName());

        UI::UIEvent space;
        space.type = UI::UIEventType::KeyDown;
        space.keyCode = static_cast<int>(UI::RVX_UI_KEY_SPACE);
        EXPECT_TRUE(ui.GetCanvas().HandleEvent(space));
        EXPECT_FALSE(checkbox->IsChecked());
        EXPECT_FALSE(lastChecked);
        EXPECT_EQ(2u, changeCount);

        UI::UIEvent enter;
        enter.type = UI::UIEventType::KeyDown;
        enter.keyCode = static_cast<int>(UI::RVX_UI_KEY_ENTER);
        EXPECT_TRUE(ui.GetCanvas().HandleEvent(enter));
        EXPECT_TRUE(checkbox->IsChecked());
        EXPECT_TRUE(lastChecked);
        EXPECT_EQ(3u, changeCount);

        ui.Shutdown();
    }

