        combo->SetName("EditorComboBox.Mode");
        combo->ApplyTheme(ui.GetTheme());
        combo->SetOptions({"Default", "Lighting", "Wireframe"});
        combo->SetSelectedIndex(1);
        combo->SetPosition(24.0f, 24.0f);
        combo->SetSize(160.0f, 28.0f);
        combo->SetOnOpenRequested([&openCount, &lastOpenBounds](const UI::Rect& bounds) {
            ++openCount;
            lastOpenBounds = bounds;
        });
        ui.GetCanvas().AddWidget(combo);

        const UI::Rect rect = combo->GetGlobalRect();
        UI::UIEvent mouseDown;
        mouseDown.type = UI::UIEventType::MouseDown;
        mouseDown.position = rect.Center();
