        UI::Widget::Ptr weightField = canvas.FindWidget(prefix + ".Field.weight");
        UI::Widget::Ptr labelField = canvas.FindWidget(prefix + ".Field.label");
        UI::Widget::Ptr modeField = canvas.FindWidget(prefix + ".Field.mode");
        UI::Widget::Ptr offsetXField = canvas.FindWidget(prefix + ".Field.offset.X");
        UI::Widget::Ptr directionZField = canvas.FindWidget(prefix + ".Field.direction.Z");
        UI::Widget::Ptr boundsWField = canvas.FindWidget(prefix + ".Field.bounds.W");
        UI::Widget::Ptr tintGField = canvas.FindWidget(prefix + ".Field.tint.G");
        UI::Widget::Ptr rotationWField = canvas.FindWidget(prefix + ".Field.rotation.W");
        ASSERT_NE(nullptr, visibleField);
        ASSERT_NE(nullptr, weightField);
        ASSERT_NE(nullptr, labelField);
        ASSERT_NE(nullptr, modeField);
        ASSERT_NE(nullptr, offsetXField);
        ASSERT_NE(nullptr, directionZField);
        ASSERT_NE(nullptr, boundsWField);
        ASSERT_NE(nullptr, tintGField);
        ASSERT_NE(nullptr, rotationWField);
        const std::string longLabelDisplayName =
            "Inspectable Label Property With Production Overflow Diagnostics";
