            mouseDown.button = static_cast<int>(UI::UIMouseButton::Left);
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
