        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().reflectedPropertyCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().drawnPropertyCount);
        EXPECT_EQ(0u, panelPtr->GetLastBuildStats().unsupportedPropertyCount);

        const std::string prefix =
            "NativeInspector.Component.0.EditorPayloadLegacyComponent.Property";
