    TEST_F(EditorContextValidation, EditorViewportToolModelRoutesContextState)
    {
        auto& context = EditorContext::Get();
        context.SetGizmoMode(EditorContext::GizmoMode::Translate);
        context.SetGizmoSpace(EditorContext::GizmoSpace::World);
        context.SetSnapEnabled(false);
        context.SetSnapValue(1.0f);

        EditorViewportToolModel model;
        EditorViewportToolState state = model.CaptureState();
        EXPECT_EQ(EditorContext::GizmoMode::Translate, state.mode);
        EXPECT_EQ(EditorContext::GizmoSpace::World, state.space);
        EXPECT_FALSE(state.snapEnabled);
        EXPECT_FLOAT_EQ(1.0f, state.snapValue);
        EXPECT_FALSE(model.GetLastStats().usesLegacyGizmoAdapter);

        model.SetMode(EditorContext::GizmoMode::Rotate);
        model.SetSpace(EditorContext::GizmoSpace::Local);
        model.ToggleSnap();
        model.SetSnapValue(2.5f);

        state = model.CaptureState();
        EXPECT_EQ(EditorContext::GizmoMode::Rotate, state.mode);
        EXPECT_EQ(EditorContext::GizmoSpace::Local, state.space);
        EXPECT_TRUE(state.snapEnabled);
        EXPECT_FLOAT_EQ(2.5f, state.snapValue);
        EXPECT_EQ(EditorContext::GizmoMode::Rotate, context.GetGizmoMode());
        EXPECT_EQ(EditorContext::GizmoSpace::Local, context.GetGizmoSpace());
        EXPECT_TRUE(context.IsSnapEnabled());
        EXPECT_FLOAT_EQ(2.5f, context.GetSnapValue());
        EXPECT_EQ(1u, model.GetLastStats().modeCommandCount);
        EXPECT_EQ(1u, model.GetLastStats().spaceCommandCount);
        EXPECT_EQ(2u, model.GetLastStats().snapCommandCount);
        EXPECT_FALSE(model.GetLastStats().usesLegacyGizmoAdapter);
    }

    TEST_F(EditorContextValidation, EditorViewportToolServiceRoutesSharedToolState)
    {
        auto& context = EditorContext::Get();
        context.SetGizmoMode(EditorContext::GizmoMode::Translate);
        context.SetGizmoSpace(EditorContext::GizmoSpace::World);
        context.SetSnapEnabled(false);
        context.SetSnapValue(1.0f);

        EditorViewportToolService service;
        EditorViewportToolState state = service.CaptureState();
        EXPECT_EQ(EditorContext::GizmoMode::Translate, state.mode);
        EXPECT_EQ(EditorContext::GizmoSpace::World, state.space);
        EXPECT_FALSE(state.snapEnabled);
        EXPECT_FLOAT_EQ(1.0f, state.snapValue);

        service.SetMode(EditorContext::GizmoMode::Scale);
        service.SetSpace(EditorContext::GizmoSpace::Local);
        service.ToggleSnap();
        service.SetSnapValue(0.25f);

        state = service.CaptureState();
        EXPECT_EQ(EditorContext::GizmoMode::Scale, state.mode);
        EXPECT_EQ(EditorContext::GizmoSpace::Local, state.space);
        EXPECT_TRUE(state.snapEnabled);
        EXPECT_FLOAT_EQ(0.25f, state.snapValue);
        EXPECT_TRUE(service.IsModeActive(EditorContext::GizmoMode::Scale));
        EXPECT_TRUE(service.IsSpaceActive(EditorContext::GizmoSpace::Local));
        EXPECT_STREQ("Scale",
                     service.GetModeLabel(EditorContext::GizmoMode::Scale));
        EXPECT_STREQ("Local",
                     service.GetSpaceLabel(EditorContext::GizmoSpace::Local));
        EXPECT_EQ(1u, service.GetLastStats().modeCommandCount);
        EXPECT_EQ(1u, service.GetLastStats().spaceCommandCount);
        EXPECT_EQ(2u, service.GetLastStats().snapCommandCount);
        EXPECT_FALSE(service.GetLastStats().usesLegacyGizmoAdapter);
    }

    TEST_F(EditorContextValidation, EditorViewportProjectionMapsWorldPointsToScreen)
    {
        EditorViewportCameraFrame frame;
        frame.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        frame.viewMatrix = Mat4(1.0f);
        frame.projectionMatrix = Mat4(1.0f);
        frame.valid = true;

        const EditorViewportProjectedPoint center =
            EditorViewportProjection::ProjectWorldPoint(frame, Vec3(0.0f, 0.0f, 0.5f));
        EXPECT_TRUE(center.valid);
        EXPECT_TRUE(center.insideViewport);
        EXPECT_NEAR(300.0f, center.screenPosition.x, 0.0001f);
        EXPECT_NEAR(230.0f, center.screenPosition.y, 0.0001f);

        const EditorViewportProjectedPoint upperRight =
            EditorViewportProjection::ProjectWorldPoint(frame, Vec3(0.5f, 0.5f, 0.5f));
        EXPECT_TRUE(upperRight.valid);
        EXPECT_TRUE(upperRight.insideViewport);
        EXPECT_NEAR(400.0f, upperRight.screenPosition.x, 0.0001f);
        EXPECT_NEAR(155.0f, upperRight.screenPosition.y, 0.0001f);

        const EditorViewportProjectedPoint offscreen =
            EditorViewportProjection::ProjectWorldPoint(frame, Vec3(2.0f, 0.0f, 0.5f));
        EXPECT_TRUE(offscreen.valid);
        EXPECT_FALSE(offscreen.insideViewport);
    }

    TEST_F(EditorContextValidation, EditorViewportProjectionBuildsScreenRayAndPlaneHit)
    {
        EditorViewportCameraFrame frame;
        frame.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        frame.viewMatrix = Mat4(1.0f);
        frame.projectionMatrix = Mat4(1.0f);
        frame.valid = true;

        const EditorViewportScreenRay centerRay =
            EditorViewportProjection::BuildScreenRay(frame, Vec2(300.0f, 230.0f));
        EXPECT_TRUE(centerRay.valid);
        EXPECT_TRUE(centerRay.insideViewport);
        EXPECT_NEAR(0.0f, centerRay.ndc.x, 0.0001f);
        EXPECT_NEAR(0.0f, centerRay.ndc.y, 0.0001f);
        EXPECT_NEAR(0.0f, centerRay.nearPoint.x, 0.0001f);
        EXPECT_NEAR(0.0f, centerRay.nearPoint.y, 0.0001f);
        EXPECT_NEAR(0.0f, centerRay.nearPoint.z, 0.0001f);
        EXPECT_NEAR(0.0f, centerRay.ray.direction.x, 0.0001f);
        EXPECT_NEAR(0.0f, centerRay.ray.direction.y, 0.0001f);
        EXPECT_NEAR(1.0f, centerRay.ray.direction.z, 0.0001f);

        const EditorViewportRayPlaneHit centerHit =
            EditorViewportProjection::IntersectRayPlane(centerRay.ray,
                                                        Vec3(0.0f, 0.0f, 0.5f),
                                                        Vec3(0.0f, 0.0f, 1.0f));
        EXPECT_TRUE(centerHit.valid);
        EXPECT_NEAR(0.5f, centerHit.position.z, 0.0001f);

        const EditorViewportScreenRay outsideRay =
            EditorViewportProjection::BuildScreenRay(frame, Vec2(700.0f, 230.0f));
        EXPECT_TRUE(outsideRay.valid);
        EXPECT_FALSE(outsideRay.insideViewport);
        EXPECT_NEAR(2.0f, outsideRay.ndc.x, 0.0001f);
    }

    TEST_F(EditorContextValidation, EditorViewportNavigationModelProjectsAxesAndBuildsViewTargets)
    {
        EditorViewportCameraFrame frame;
        frame.viewportBounds = UI::Rect(0.0f, 0.0f, 400.0f, 300.0f);
        frame.viewMatrix = Mat4(1.0f);
        frame.projectionMatrix = Mat4(1.0f);
        frame.valid = true;

        EditorViewportNavigationModel model;
        EditorViewportNavigationHUDDesc desc;
        desc.cameraFrame = frame;
        desc.localBounds = UI::Rect(0.0f, 0.0f, 120.0f, 120.0f);
        desc.axisLength = 36.0f;
        desc.hitSize = 20.0f;

        const EditorViewportNavigationHUDState& hud = model.BuildHUD(desc);
        ASSERT_TRUE(hud.valid);
        EXPECT_EQ(3u, hud.axisCount);
        EXPECT_TRUE(model.GetLastStats().hudBuilt);
        EXPECT_EQ(3u, model.GetLastStats().axisCount);

        const EditorViewportNavigationAxisVisual* xAxis =
            model.FindAxis(EditorViewportNavigationAxis::X);
        const EditorViewportNavigationAxisVisual* yAxis =
            model.FindAxis(EditorViewportNavigationAxis::Y);
        const EditorViewportNavigationAxisVisual* zAxis =
            model.FindAxis(EditorViewportNavigationAxis::Z);
        ASSERT_NE(nullptr, xAxis);
        ASSERT_NE(nullptr, yAxis);
        ASSERT_NE(nullptr, zAxis);
        EXPECT_NEAR(1.0f, xAxis->direction.x, 0.0001f);
        EXPECT_NEAR(0.0f, xAxis->direction.y, 0.0001f);
        EXPECT_NEAR(0.0f, yAxis->direction.x, 0.0001f);
        EXPECT_NEAR(-1.0f, yAxis->direction.y, 0.0001f);
        EXPECT_TRUE(zAxis->usedProjectionFallback);
        EXPECT_EQ(xAxis, model.HitTestAxis(xAxis->hitRect.Center()));
        EXPECT_EQ(yAxis, model.HitTestAxis(yAxis->hitRect.Center()));
        EXPECT_EQ(zAxis, model.HitTestAxis(zAxis->hitRect.Center()));
        EXPECT_EQ(nullptr, model.HitTestAxis(hud.center));

        const Vec3 cameraPosition(0.0f, 5.0f, 10.0f);
        const Vec3 cameraTarget(0.0f, 0.0f, 0.0f);
        const EditorViewportNavigationViewTarget xTarget =
            model.ActivateAxis(EditorViewportNavigationAxis::X,
                               cameraPosition,
                               cameraTarget);
        EXPECT_TRUE(xTarget.valid);
        EXPECT_EQ(EditorViewportNavigationAxis::X, xTarget.axis);
        EXPECT_EQ(ViewportCameraMode::Orbit, xTarget.cameraMode);
        EXPECT_NEAR(1.0f, xTarget.directionFromTarget.x, 0.0001f);
        EXPECT_NEAR(0.0f, xTarget.directionFromTarget.y, 0.0001f);
        EXPECT_NEAR(0.0f, xTarget.directionFromTarget.z, 0.0001f);
        EXPECT_NEAR(length(cameraPosition - cameraTarget),
                    xTarget.distance,
                    0.0001f);

        const EditorViewportNavigationViewTarget yTarget =
            model.ActivateAxis(EditorViewportNavigationAxis::Y,
                               cameraPosition,
                               cameraTarget);
        EXPECT_TRUE(yTarget.valid);
        EXPECT_EQ(ViewportCameraMode::TopDown, yTarget.cameraMode);
        EXPECT_EQ(2u, model.GetLastStats().activationCount);
        EXPECT_EQ(EditorViewportNavigationAxis::Y,
                  model.GetLastStats().lastActivatedAxis);
    }

    TEST_F(EditorContextValidation, EditorViewportInteractionModelCapturesNavigationInput)
    {
        auto makeInput = [](const Vec2& previousPosition,
                            const Vec2& currentPosition,
                            bool previousRight,
                            bool currentRight,
                            bool previousMiddle = false,
                            bool currentMiddle = false,
                            const Vec2& scrollDelta = Vec2(0.0f)) {
            UI::UIInputState input;
            input.previous.mousePosition = previousPosition;
            input.current.mousePosition = currentPosition;
            input.mouseDelta = currentPosition - previousPosition;
            input.previous.SetMouseButtonDown(UI::UIMouseButton::Right,
                                              previousRight);
            input.current.SetMouseButtonDown(UI::UIMouseButton::Right,
                                             currentRight);
            input.previous.SetMouseButtonDown(UI::UIMouseButton::Middle,
                                              previousMiddle);
            input.current.SetMouseButtonDown(UI::UIMouseButton::Middle,
                                             currentMiddle);
            input.mouseButtonsPressed[static_cast<size_t>(UI::UIMouseButton::Right)] =
                !previousRight && currentRight;
            input.mouseButtonsReleased[static_cast<size_t>(UI::UIMouseButton::Right)] =
                previousRight && !currentRight;
            input.mouseButtonsPressed[static_cast<size_t>(UI::UIMouseButton::Middle)] =
                !previousMiddle && currentMiddle;
            input.mouseButtonsReleased[static_cast<size_t>(UI::UIMouseButton::Middle)] =
                previousMiddle && !currentMiddle;
            input.current.scrollDelta = scrollDelta;
            return input;
        };

        EditorViewportInteractionModel model;
        EditorViewportInteractionDesc desc;
        desc.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);

        const EditorViewportInteractionState& idle =
            model.Update(makeInput(Vec2(10.0f), Vec2(10.0f), false, false),
                         desc);
        EXPECT_FALSE(idle.hovered);
        EXPECT_FALSE(idle.routesCameraInput);
        EXPECT_FALSE(idle.requestsMouseCapture);
        EXPECT_FALSE(idle.requestsCursorHidden);
        EXPECT_FALSE(idle.requestsCursorLock);
        EXPECT_EQ(EditorViewportInteractionAction::None, idle.action);
        EXPECT_EQ(EditorViewportCursorMode::Normal, idle.cursorMode);

        const Vec2 pressPosition(180.0f, 160.0f);
        const EditorViewportInteractionState& begin =
            model.Update(makeInput(pressPosition,
                                   pressPosition,
                                   false,
                                   true),
                         desc);
        EXPECT_TRUE(begin.hovered);
        EXPECT_TRUE(begin.focused);
        EXPECT_TRUE(begin.navigating);
        EXPECT_TRUE(begin.navigationStarted);
        EXPECT_TRUE(begin.routesCameraInput);
        EXPECT_TRUE(begin.blocksSceneTools);
        EXPECT_TRUE(begin.requestsMouseCapture);
        EXPECT_TRUE(begin.requestsCursorHidden);
        EXPECT_TRUE(begin.requestsCursorLock);
        EXPECT_EQ(EditorViewportInteractionAction::Orbit, begin.action);
        EXPECT_EQ(EditorViewportCursorMode::Locked, begin.cursorMode);
        EXPECT_EQ(UI::UIMouseButton::Right, begin.captureButton);
        EXPECT_EQ(Vec2(80.0f, 80.0f), begin.localMousePosition);

        const EditorViewportInteractionState& dragOutside =
            model.Update(makeInput(pressPosition,
                                   Vec2(620.0f, 460.0f),
                                   true,
                                   true),
                         desc);
        EXPECT_FALSE(dragOutside.hovered);
        EXPECT_TRUE(dragOutside.focused);
        EXPECT_TRUE(dragOutside.navigating);
        EXPECT_TRUE(dragOutside.routesCameraInput);
        EXPECT_TRUE(dragOutside.blocksSceneTools);
        EXPECT_TRUE(dragOutside.requestsMouseCapture);
        EXPECT_TRUE(dragOutside.requestsCursorHidden);
        EXPECT_TRUE(dragOutside.requestsCursorLock);
        EXPECT_EQ(EditorViewportInteractionAction::Orbit, dragOutside.action);
        EXPECT_EQ(EditorViewportCursorMode::Locked, dragOutside.cursorMode);
        EXPECT_EQ(Vec2(440.0f, 300.0f), dragOutside.dragDelta);

        const EditorViewportInteractionState& end =
            model.Update(makeInput(Vec2(620.0f, 460.0f),
                                   Vec2(620.0f, 460.0f),
                                   true,
                                   false),
                         desc);
        EXPECT_TRUE(end.navigationEnded);
        EXPECT_FALSE(end.navigating);
        EXPECT_FALSE(end.routesCameraInput);
        EXPECT_FALSE(end.blocksSceneTools);
        EXPECT_FALSE(end.requestsMouseCapture);
        EXPECT_FALSE(end.requestsCursorHidden);
        EXPECT_FALSE(end.requestsCursorLock);
        EXPECT_EQ(EditorViewportCursorMode::Normal, end.cursorMode);
        EXPECT_EQ(1u, model.GetLastStats().navigationBeginCount);
        EXPECT_EQ(1u, model.GetLastStats().navigationEndCount);

        const EditorViewportInteractionState& pan =
            model.Update(makeInput(pressPosition,
                                   pressPosition,
                                   false,
                                   false,
                                   false,
                                   true),
                         desc);
        EXPECT_TRUE(pan.navigating);
        EXPECT_EQ(EditorViewportInteractionAction::Pan, pan.action);
        EXPECT_EQ(EditorViewportCursorMode::Locked, pan.cursorMode);
        EXPECT_TRUE(pan.requestsMouseCapture);
        EXPECT_TRUE(pan.requestsCursorLock);
        EXPECT_EQ(UI::UIMouseButton::Middle, pan.captureButton);

        model.Reset();
        const EditorViewportInteractionState& zoom =
            model.Update(makeInput(pressPosition,
                                   pressPosition,
                                   false,
                                   false,
                                   false,
                                   false,
                                   Vec2(0.0f, 1.0f)),
                         desc);
        EXPECT_TRUE(zoom.hovered);
        EXPECT_FALSE(zoom.navigating);
        EXPECT_TRUE(zoom.routesCameraInput);
        EXPECT_FALSE(zoom.blocksSceneTools);
        EXPECT_FALSE(zoom.requestsMouseCapture);
        EXPECT_FALSE(zoom.requestsCursorHidden);
        EXPECT_FALSE(zoom.requestsCursorLock);
        EXPECT_EQ(EditorViewportInteractionAction::Zoom, zoom.action);
        EXPECT_EQ(EditorViewportCursorMode::Normal, zoom.cursorMode);

        model.Reset();
        EditorViewportInteractionDesc hiddenCursorDesc = desc;
        hiddenCursorDesc.cursorLockEnabled = false;
        const EditorViewportInteractionState& hiddenCursor =
            model.Update(makeInput(pressPosition,
                                   pressPosition,
                                   false,
                                   true),
                         hiddenCursorDesc);
        EXPECT_TRUE(hiddenCursor.navigating);
        EXPECT_TRUE(hiddenCursor.requestsMouseCapture);
        EXPECT_TRUE(hiddenCursor.requestsCursorHidden);
        EXPECT_FALSE(hiddenCursor.requestsCursorLock);
        EXPECT_EQ(EditorViewportCursorMode::Hidden, hiddenCursor.cursorMode);

        model.Reset();
        EditorViewportInteractionDesc noCaptureDesc = desc;
        noCaptureDesc.cursorCaptureEnabled = false;
        const EditorViewportInteractionState& noCapture =
            model.Update(makeInput(pressPosition,
                                   pressPosition,
                                   false,
                                   true),
                         noCaptureDesc);
        EXPECT_TRUE(noCapture.navigating);
        EXPECT_FALSE(noCapture.requestsMouseCapture);
        EXPECT_FALSE(noCapture.requestsCursorHidden);
        EXPECT_FALSE(noCapture.requestsCursorLock);
        EXPECT_EQ(EditorViewportCursorMode::Normal, noCapture.cursorMode);
    }

    TEST_F(EditorContextValidation, EditorViewportSelectionModelSelectsAndClearsRaycastHits)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();

        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams params;
        params.name = "ViewportSelectionTarget";
        params.localPosition = Vec3(0.0f, 0.0f, 0.5f);
        SceneEntity* entity = sceneManager->SpawnActor(params);
        ASSERT_NE(nullptr, entity);
        entity->SetLocalBounds(AABB(Vec3(-0.1f), Vec3(0.1f)));

        EditorViewportCameraFrame frame;
        frame.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        frame.viewMatrix = Mat4(1.0f);
        frame.projectionMatrix = Mat4(1.0f);
        frame.valid = true;

        EditorViewportSelectionPickDesc desc;
        desc.sceneManager = sceneManager;
        desc.cameraFrame = frame;
        desc.screenPosition = Vec2(300.0f, 230.0f);

        EditorSelectionService selectionService(context);
        EditorViewportSelectionModel model;
        EXPECT_TRUE(model.ApplyClickSelection(selectionService, desc));
        EXPECT_EQ(SelectionType::Entity, selectionService.GetSelectionType());
        EXPECT_EQ(entity, selectionService.GetSelectedEntity());
        EXPECT_TRUE(model.GetLastStats().receivedClick);
        EXPECT_TRUE(model.GetLastStats().hasScene);
        EXPECT_TRUE(model.GetLastStats().cameraValid);
        EXPECT_TRUE(model.GetLastStats().rayValid);
        EXPECT_TRUE(model.GetLastStats().insideViewport);
        EXPECT_TRUE(model.GetLastStats().hit);
        EXPECT_TRUE(model.GetLastStats().selected);
        EXPECT_FALSE(model.GetLastStats().clearedSelection);
        EXPECT_EQ(entity, model.GetLastStats().hitEntity);
        EXPECT_GT(model.GetLastStats().hitDistance, 0.0f);

        desc.screenPosition = Vec2(490.0f, 230.0f);
        EXPECT_TRUE(model.ApplyClickSelection(selectionService, desc));
        EXPECT_EQ(SelectionType::None, selectionService.GetSelectionType());
        EXPECT_EQ(nullptr, selectionService.GetSelectedEntity());
        EXPECT_TRUE(model.GetLastStats().receivedClick);
        EXPECT_TRUE(model.GetLastStats().rayValid);
        EXPECT_TRUE(model.GetLastStats().insideViewport);
        EXPECT_FALSE(model.GetLastStats().hit);
        EXPECT_TRUE(model.GetLastStats().clearedSelection);

        context.SelectEntity(entity);
        desc.screenPosition = Vec2(620.0f, 230.0f);
        EXPECT_FALSE(model.ApplyClickSelection(context, desc));
        EXPECT_EQ(entity, context.GetSelectedEntity());
        EXPECT_TRUE(model.GetLastStats().rayValid);
        EXPECT_FALSE(model.GetLastStats().insideViewport);
        EXPECT_FALSE(model.GetLastStats().clearedSelection);
    }

