        ASSERT_NE(nullptr, entity);
        entity->SetPosition(Vec3(0.0f));
        context.SelectEntity(entity);

        EditorViewportToolModel toolModel;
        EditorViewportManipulatorBuildDesc desc;
        desc.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        desc.toolState = toolModel.CaptureState();
        desc.cameraFrame.viewportBounds = desc.viewportBounds;
        desc.cameraFrame.viewMatrix =
            rotate(Mat4(1.0f), radians(45.0f), Vec3(1.0f, 0.0f, 0.0f));
        desc.cameraFrame.projectionMatrix = Mat4(1.0f);
        desc.cameraFrame.valid = true;

        EditorViewportManipulatorModel model;
        model.Build(context, desc);
        EXPECT_EQ(7u, model.GetHandleCount());
        EXPECT_EQ(3u, model.GetLastStats().projectedSegmentHandleCount);

        const EditorViewportManipulatorHandleInfo* zHandle =
            model.FindHandle(EditorViewportManipulatorHandle::AxisZ);
        ASSERT_NE(nullptr, zHandle);
        ASSERT_TRUE(zHandle->hitSegment);
        ASSERT_TRUE(zHandle->usesProjectedSegment);
        EXPECT_NEAR(0.0f, zHandle->axis.x, 0.0001f);
        EXPECT_NEAR(0.0f, zHandle->axis.y, 0.0001f);
        EXPECT_NEAR(1.0f, zHandle->axis.z, 0.0001f);

        const Vec2 segment = zHandle->screenEnd - zHandle->screenStart;
        ASSERT_GT(length(segment), 1.0f);
        const Vec2 segmentDirection = segment / length(segment);
        const Vec2 dragStart = zHandle->screenStart + segment * 0.5f;
        const Vec2 dragEnd = dragStart + segmentDirection * 80.0f;

        EXPECT_TRUE(model.BeginDrag(context, dragStart));
        EXPECT_EQ(EditorViewportManipulatorHandle::AxisZ,
                  model.GetLastStats().activeHandle);
        EXPECT_TRUE(model.GetLastStats().usesRayPlaneConstraint);
