    TEST_F(EditorContextValidation, EditorViewportManipulatorModelAppliesSnappedUndoableTranslation)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        context.SetGizmoMode(EditorContext::GizmoMode::Translate);
        context.SetGizmoSpace(EditorContext::GizmoSpace::World);
        context.SetSnapEnabled(true);
        context.SetSnapValue(0.5f);

        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams params;
        params.name = "ManipulatorTarget";
        SceneEntity* entity = sceneManager->SpawnActor(params);
        ASSERT_NE(nullptr, entity);
        entity->SetPosition(Vec3(1.0f, 2.0f, 3.0f));
        context.SelectEntity(entity);

        EditorViewportToolModel toolModel;
        EditorViewportManipulatorBuildDesc desc;
        desc.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        desc.toolState = toolModel.CaptureState();
        desc.worldUnitsPerPixel = 0.01f;

        EditorViewportManipulatorModel model;
        model.Build(context, desc);
        EXPECT_TRUE(model.GetLastStats().built);
        EXPECT_TRUE(model.GetLastStats().hasSelection);
        EXPECT_FALSE(model.GetLastStats().unsupportedMode);
        EXPECT_EQ(7u, model.GetHandleCount());
        EXPECT_EQ(0u, model.GetLastStats().projectedSegmentHandleCount);
        EXPECT_FALSE(model.GetLastStats().usesLegacyGizmoAdapter);

        const EditorViewportManipulatorHandleInfo* xHandle =
            model.FindHandle(EditorViewportManipulatorHandle::AxisX);
        ASSERT_NE(nullptr, xHandle);

        const Vec2 dragStart = xHandle->bounds.Center();
        const Vec2 dragEnd(dragStart.x + 126.0f, dragStart.y + 18.0f);
        EXPECT_TRUE(model.BeginDrag(context, dragStart));
        EXPECT_TRUE(model.UpdateDrag(dragEnd));
        EXPECT_TRUE(model.GetLastStats().dragging);
        EXPECT_NEAR(1.5f, model.GetLastStats().previewDelta.x, 0.0001f);
        EXPECT_NEAR(0.0f, model.GetLastStats().previewDelta.y, 0.0001f);

        EXPECT_TRUE(model.EndDrag(context, dragEnd));
        EXPECT_TRUE(model.GetLastStats().appliedTransform);
        EXPECT_NEAR(1.5f, model.GetLastStats().committedDelta.x, 0.0001f);
        EXPECT_NEAR(2.5f, entity->GetPosition().x, 0.0001f);
        EXPECT_NEAR(2.0f, entity->GetPosition().y, 0.0001f);
        EXPECT_NEAR(3.0f, entity->GetPosition().z, 0.0001f);
        EXPECT_TRUE(context.CanUndo());

        context.Undo();
        EXPECT_NEAR(1.0f, entity->GetPosition().x, 0.0001f);
        EXPECT_NEAR(2.0f, entity->GetPosition().y, 0.0001f);
        EXPECT_TRUE(context.CanRedo());

        context.Redo();
        EXPECT_NEAR(2.5f, entity->GetPosition().x, 0.0001f);
        EXPECT_NEAR(2.0f, entity->GetPosition().y, 0.0001f);

        context.SetGizmoMode(EditorContext::GizmoMode::Rotate);
        desc.toolState = toolModel.CaptureState();
        model.Build(context, desc);
        EXPECT_FALSE(model.GetLastStats().unsupportedMode);
        EXPECT_EQ(4u, model.GetHandleCount());
        const EditorViewportManipulatorHandleInfo* rotateX =
            model.FindHandle(EditorViewportManipulatorHandle::AxisX);
        const EditorViewportManipulatorHandleInfo* rotateY =
            model.FindHandle(EditorViewportManipulatorHandle::AxisY);
        const EditorViewportManipulatorHandleInfo* rotateZ =
            model.FindHandle(EditorViewportManipulatorHandle::AxisZ);
        ASSERT_NE(nullptr, rotateX);
        ASSERT_NE(nullptr, rotateY);
        ASSERT_NE(nullptr, rotateZ);
        EXPECT_TRUE(rotateX->hitRing);
        EXPECT_TRUE(rotateY->hitRing);
        EXPECT_TRUE(rotateZ->hitRing);
        EXPECT_EQ(RVX_EDITOR_MANIPULATOR_RING_SAMPLE_COUNT,
                  rotateX->screenRingSampleCount);
        EXPECT_FALSE(rotateX->hitSegment);
        EXPECT_EQ(nullptr, model.FindHandle(EditorViewportManipulatorHandle::PlaneXY));
    }

    TEST_F(EditorContextValidation, EditorViewportManipulatorModelAppliesAxisRotateUndoable)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        context.SetGizmoMode(EditorContext::GizmoMode::Rotate);
        context.SetGizmoSpace(EditorContext::GizmoSpace::World);
        context.SetSnapEnabled(false);

        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams params;
        params.name = "ManipulatorAxisRotateTarget";
        SceneEntity* entity = sceneManager->SpawnActor(params);
        ASSERT_NE(nullptr, entity);
        entity->SetPosition(Vec3(1.0f, 2.0f, 3.0f));
        entity->SetRotation(Quat(1.0f, 0.0f, 0.0f, 0.0f));
        entity->SetScale(Vec3(2.0f, 3.0f, 4.0f));
        context.SelectEntity(entity);

        EditorViewportToolModel toolModel;
        EditorViewportManipulatorBuildDesc desc;
        desc.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        desc.toolState = toolModel.CaptureState();
        desc.worldUnitsPerPixel = 0.01f;

        EditorViewportManipulatorModel model;
        model.Build(context, desc);
        EXPECT_TRUE(model.GetLastStats().built);
        EXPECT_TRUE(model.GetLastStats().hasSelection);
        EXPECT_FALSE(model.GetLastStats().unsupportedMode);
        EXPECT_EQ(4u, model.GetHandleCount());
        EXPECT_EQ(nullptr, model.FindHandle(EditorViewportManipulatorHandle::PlaneXY));

        const EditorViewportManipulatorHandleInfo* xHandle =
            model.FindHandle(EditorViewportManipulatorHandle::AxisX);
        ASSERT_NE(nullptr, xHandle);
        ASSERT_TRUE(xHandle->hitRing);
        ASSERT_EQ(RVX_EDITOR_MANIPULATOR_RING_SAMPLE_COUNT,
                  xHandle->screenRingSampleCount);

        const Vec2 dragStart =
            xHandle->screenCenter + Vec2(xHandle->ringRadius, 0.0f);
        const Vec2 dragEnd =
            xHandle->screenCenter + Vec2(0.0f, -xHandle->ringRadius);
        EXPECT_TRUE(model.BeginDrag(context, dragStart));
        EXPECT_EQ(EditorViewportManipulatorHandle::AxisX,
                  model.GetLastStats().activeHandle);
        EXPECT_TRUE(model.UpdateDrag(dragEnd));
        EXPECT_TRUE(model.GetLastStats().dragging);
        EXPECT_NEAR(1.5708f,
                    std::abs(model.GetLastStats().previewAngleRadians),
                    0.0002f);
        EXPECT_NEAR(1.5708f,
                    std::abs(QuatToEuler(model.GetLastStats().previewRotation).x),
                    0.0002f);

        EXPECT_TRUE(model.EndDrag(context, dragEnd));
        EXPECT_TRUE(model.GetLastStats().appliedTransform);
        EXPECT_NEAR(1.5708f,
                    std::abs(model.GetLastStats().committedAngleRadians),
                    0.0002f);
        EXPECT_NEAR(1.5708f, std::abs(QuatToEuler(entity->GetRotation()).x), 0.0002f);
        EXPECT_NEAR(0.0f, QuatToEuler(entity->GetRotation()).y, 0.0001f);
        EXPECT_NEAR(0.0f, QuatToEuler(entity->GetRotation()).z, 0.0001f);
        EXPECT_NEAR(1.0f, entity->GetPosition().x, 0.0001f);
        EXPECT_NEAR(2.0f, entity->GetPosition().y, 0.0001f);
        EXPECT_NEAR(3.0f, entity->GetPosition().z, 0.0001f);
        EXPECT_NEAR(2.0f, entity->GetScale().x, 0.0001f);
        EXPECT_NEAR(3.0f, entity->GetScale().y, 0.0001f);
        EXPECT_NEAR(4.0f, entity->GetScale().z, 0.0001f);
        EXPECT_TRUE(context.CanUndo());

        context.Undo();
        EXPECT_NEAR(0.0f, QuatToEuler(entity->GetRotation()).x, 0.0001f);
        EXPECT_TRUE(context.CanRedo());

        context.Redo();
        EXPECT_NEAR(1.5708f, std::abs(QuatToEuler(entity->GetRotation()).x), 0.0002f);
    }

    TEST_F(EditorContextValidation, EditorViewportManipulatorBuildsProjectedRotationRings)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        context.SetGizmoMode(EditorContext::GizmoMode::Rotate);
        context.SetGizmoSpace(EditorContext::GizmoSpace::World);
        context.SetSnapEnabled(false);

        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams params;
        params.name = "ProjectedRotateRingTarget";
        SceneEntity* entity = sceneManager->SpawnActor(params);
        ASSERT_NE(nullptr, entity);
        entity->SetPosition(Vec3(0.0f));
        context.SelectEntity(entity);

        EditorViewportToolModel toolModel;
        EditorViewportManipulatorBuildDesc desc;
        desc.viewportBounds = UI::Rect(100.0f, 80.0f, 400.0f, 300.0f);
        desc.toolState = toolModel.CaptureState();
        desc.cameraFrame.viewportBounds = desc.viewportBounds;
        desc.cameraFrame.viewMatrix =
            rotate(rotate(Mat4(1.0f), radians(35.0f), Vec3(1.0f, 0.0f, 0.0f)),
                   radians(30.0f),
                   Vec3(0.0f, 1.0f, 0.0f));
        desc.cameraFrame.projectionMatrix = Mat4(1.0f);
        desc.cameraFrame.valid = true;

        EditorViewportManipulatorModel model;
        model.Build(context, desc);
        EXPECT_FALSE(model.GetLastStats().unsupportedMode);
        EXPECT_EQ(4u, model.GetHandleCount());
        EXPECT_EQ(3u, model.GetLastStats().projectedRingHandleCount);
        EXPECT_EQ(0u, model.GetLastStats().projectedPlaneHandleCount);

        for (EditorViewportManipulatorHandle handle :
             {EditorViewportManipulatorHandle::AxisX,
              EditorViewportManipulatorHandle::AxisY,
              EditorViewportManipulatorHandle::AxisZ})
        {
            const EditorViewportManipulatorHandleInfo* ring = model.FindHandle(handle);
            ASSERT_NE(nullptr, ring);
            EXPECT_TRUE(ring->hitRing);
            EXPECT_TRUE(ring->usesProjectedRing);
            EXPECT_EQ(RVX_EDITOR_MANIPULATOR_RING_SAMPLE_COUNT,
                      ring->screenRingSampleCount);
            EXPECT_GT(ring->ringRadius, 12.0f);
            EXPECT_GT(ring->bounds.width, 12.0f);
            EXPECT_GT(ring->bounds.height, 12.0f);
        }
    }

