    TEST_F(EditorContextValidation, NativeViewportClickSelectsSceneEntityAndBuildsManipulator)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        context.SetGizmoMode(EditorContext::GizmoMode::Translate);
        context.SetGizmoSpace(EditorContext::GizmoSpace::World);
        context.SetSnapEnabled(false);

        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams params;
        params.name = "NativeViewportSelectableTarget";
        params.localPosition = Vec3(0.0f, 0.0f, 0.0f);
        SceneEntity* entity = sceneManager->SpawnActor(params);
        ASSERT_NE(nullptr, entity);
        entity->SetLocalBounds(AABB(Vec3(-1.0f), Vec3(1.0f)));

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 900;
        desc.surfaceHeight = 520;
        ASSERT_TRUE(host.Initialize(desc));

        EditorSelectionService selectionService(context);
        auto panel = std::make_shared<NativeViewportPanel>();
        NativeViewportPanel* panelPtr = panel.get();
        panelPtr->SetSelectionService(&selectionService);
        host.RegisterPanel(panel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 900;
        frameDesc.surfaceHeight = 520;
        frameDesc.deltaTime = 0.016f;

        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        EXPECT_EQ(SelectionType::None, selectionService.GetSelectionType());
        EXPECT_FALSE(panelPtr->GetLastBuildStats().manipulatorStats.hasSelection);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().selectionOverlayStats.hasSelection);
        EXPECT_EQ(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget("NativeViewport.Selection"));
        const Vec2 clickPosition = panelPtr->GetLastBuildStats().contentBounds.Center();
        UI::Widget::Ptr contentWidget =
            host.GetUIContext().GetCanvas().FindWidget("NativeViewport.Content");
        ASSERT_NE(nullptr, contentWidget);
        EXPECT_NEAR(clickPosition.x,
                    contentWidget->GetGlobalRect().Center().x,
                    0.0001f);
        EXPECT_NEAR(clickPosition.y,
                    contentWidget->GetGlobalRect().Center().y,
                    0.0001f);
        host.EndFrame();

        UI::UIInputSnapshot input;
        input.mousePosition = clickPosition;
        input.SetMouseButtonDown(UI::UIMouseButton::Left, true);
        frameDesc.input = input;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        EXPECT_EQ(SelectionType::Entity, selectionService.GetSelectionType());
        EXPECT_EQ(entity, selectionService.GetSelectedEntity());
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionStats.receivedClick);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionStats.hasScene);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionStats.rayValid);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionStats.insideViewport);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionStats.hit);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionStats.selected);
        EXPECT_EQ(entity, panelPtr->GetLastBuildStats().selectionStats.hitEntity);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionOverlayStats.hasSelection);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionOverlayStats.visible);
        EXPECT_EQ(RVX_EDITOR_SELECTION_OVERLAY_EDGE_SAMPLE_COUNT,
                  panelPtr->GetLastBuildStats().selectionOverlayStats.edgeSampleCount);
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget("NativeViewport.Selection"));
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "NativeViewport.Selection.Outline.0"));
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "NativeViewport.Selection.Anchor"));
        EXPECT_FALSE(panelPtr->GetLastBuildStats().manipulatorStats.hasSelection);
        host.EndFrame();

        input.SetMouseButtonDown(UI::UIMouseButton::Left, false);
        frameDesc.input = input;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        EXPECT_TRUE(panelPtr->GetLastBuildStats().manipulatorStats.hasSelection);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().manipulatorStats.anchorProjected);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().manipulatorStats.anchorVisible);
        EXPECT_EQ(7u, panelPtr->GetLastBuildStats().manipulatorStats.handleCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectionOverlayStats.visible);
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "NativeViewport.Selection.Outline.0"));
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "NativeViewport.Manipulator.AxisX"));
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "NativeViewport.Manipulator.Center"));
        host.EndFrame();

        host.Shutdown();
    }

