    TEST_F(EditorContextValidation, NativeViewportToolbarRoutesToolModelClicks)
    {
        auto& editorContext = EditorContext::Get();
        editorContext.SetGizmoMode(EditorContext::GizmoMode::Translate);
        editorContext.SetGizmoSpace(EditorContext::GizmoSpace::World);
        editorContext.SetSnapEnabled(false);

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 900;
        desc.surfaceHeight = 520;
        ASSERT_TRUE(host.Initialize(desc));

        EditorViewportToolService toolService;
        auto panel = std::make_shared<NativeViewportPanel>();
        NativeViewportPanel* panelPtr = panel.get();
        panelPtr->SetToolService(&toolService);
        host.RegisterPanel(panel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 900;
        frameDesc.surfaceHeight = 520;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        auto clickWidget = [&host](const std::string& name) {
            UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
            UI::Widget::Ptr widget = canvas.FindWidget(name);
            ASSERT_NE(nullptr, widget);
            const UI::Rect rect = widget->GetGlobalRect();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            mouseDown.position = rect.Center();
            mouseDown.button = static_cast<int>(UI::UIMouseButton::Left);
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        };

        clickWidget("NativeViewport.Gizmo.Rotate");
        EXPECT_EQ(EditorContext::GizmoMode::Rotate, editorContext.GetGizmoMode());
        EXPECT_EQ(1u, toolService.GetLastStats().modeCommandCount);

        host.EndFrame();
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        EXPECT_EQ(EditorContext::GizmoMode::Rotate,
                  panelPtr->GetLastBuildStats().toolStats.state.mode);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().toolStats.modeCommandCount);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().toolStats.usesLegacyGizmoAdapter);

        clickWidget("NativeViewport.Space.Local");
        EXPECT_EQ(EditorContext::GizmoSpace::Local, editorContext.GetGizmoSpace());
        EXPECT_EQ(1u, toolService.GetLastStats().spaceCommandCount);

        host.EndFrame();
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        EXPECT_EQ(EditorContext::GizmoSpace::Local,
                  panelPtr->GetLastBuildStats().toolStats.state.space);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().toolStats.spaceCommandCount);

        clickWidget("NativeViewport.Toggle.Snap");
        EXPECT_TRUE(editorContext.IsSnapEnabled());
        EXPECT_EQ(1u, toolService.GetLastStats().snapCommandCount);

        host.EndFrame();
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        EXPECT_TRUE(panelPtr->GetLastBuildStats().toolStats.state.snapEnabled);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().toolStats.snapCommandCount);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().toolStats.usesLegacyGizmoAdapter);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().toolbarStatusBuilt);
        EXPECT_EQ("Rotate | Local | Snap On | Orbit | Lit",
                  panelPtr->GetLastBuildStats().toolbarStatusText);
        UI::Widget::Ptr statusLabelWidget =
            host.GetUIContext()
                .GetCanvas()
                .FindWidget("NativeViewport.ToolStatus.Text");
        ASSERT_NE(nullptr, statusLabelWidget);
        std::shared_ptr<UI::Label> statusLabel =
            std::dynamic_pointer_cast<UI::Label>(statusLabelWidget);
        ASSERT_NE(nullptr, statusLabel);
        EXPECT_EQ("Rotate | Local | Snap On | Orbit | Lit",
                  statusLabel->GetText());

        host.EndFrame();
        host.Shutdown();
    }

