    TEST_F(EditorContextValidation, NativeViewportRightMouseDragCapturesOrbitCamera)
    {
        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 900;
        desc.surfaceHeight = 520;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeViewportPanel>();
        NativeViewportPanel* panelPtr = panel.get();
        host.RegisterPanel(panel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = desc.surfaceWidth;
        frameDesc.surfaceHeight = desc.surfaceHeight;
        frameDesc.deltaTime = 0.016f;

        auto runFrame = [&](const UI::UIInputSnapshot& input) {
            frameDesc.input = input;
            ASSERT_TRUE(host.BeginFrame(frameDesc));
            host.BuildPanels();
            host.Update(frameDesc.deltaTime);
            host.EndFrame();
        };

        runFrame({});
        const UI::Rect contentBounds = panelPtr->GetLastBuildStats().contentBounds;
        ASSERT_GT(contentBounds.width, 100.0f);
        ASSERT_GT(contentBounds.height, 100.0f);

        UI::UIInputSnapshot hover;
        hover.mousePosition = contentBounds.Center();
        runFrame(hover);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.hovered);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().interactionStats.navigating);

        UI::UIInputSnapshot press = hover;
        press.SetMouseButtonDown(UI::UIMouseButton::Right, true);
        runFrame(press);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.navigating);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.routesCameraInput);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.blocksSceneTools);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.requestsMouseCapture);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.requestsCursorHidden);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.requestsCursorLock);
        EXPECT_EQ(EditorViewportInteractionAction::Orbit,
                  panelPtr->GetLastBuildStats().interactionStats.action);
        EXPECT_EQ(EditorViewportCursorMode::Locked,
                  panelPtr->GetLastBuildStats().interactionStats.cursorMode);
        EXPECT_TRUE(host.GetCursorRequest().requestsMouseCapture);
        EXPECT_TRUE(host.GetCursorRequest().requestsCursorHidden);
        EXPECT_TRUE(host.GetCursorRequest().requestsCursorLock);
        EXPECT_EQ(EditorUICursorMode::Locked,
                  host.GetCursorRequest().cursorMode);
        EXPECT_EQ(NativeViewportPanel::PanelId(),
                  host.GetCursorRequest().ownerPanelId);
        EXPECT_EQ(1u,
                  panelPtr->GetLastBuildStats().interactionStats.navigationBeginCount);

        const Vec3 cameraBeforeDrag =
            panelPtr->GetViewportCore().GetCameraPosition();

        UI::UIInputSnapshot drag = press;
        drag.mousePosition = hover.mousePosition + Vec2(80.0f, 24.0f);
        runFrame(drag);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.navigating);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.blocksSceneTools);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.requestsMouseCapture);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().interactionStats.requestsCursorLock);
        EXPECT_EQ(EditorViewportInteractionAction::Orbit,
                  panelPtr->GetLastBuildStats().interactionStats.action);
        EXPECT_EQ(EditorViewportCursorMode::Locked,
                  panelPtr->GetLastBuildStats().interactionStats.cursorMode);
        EXPECT_TRUE(host.GetCursorRequest().requestsMouseCapture);
        EXPECT_EQ(EditorUICursorMode::Locked,
                  host.GetCursorRequest().cursorMode);

        const Vec3 cameraAfterDrag =
            panelPtr->GetViewportCore().GetCameraPosition();
        EXPECT_GT(length(cameraAfterDrag - cameraBeforeDrag), 0.01f);

        UI::UIInputSnapshot release;
        release.mousePosition = drag.mousePosition;
        runFrame(release);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().interactionStats.navigating);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().interactionStats.requestsMouseCapture);
        EXPECT_EQ(EditorViewportCursorMode::Normal,
                  panelPtr->GetLastBuildStats().interactionStats.cursorMode);
        EXPECT_FALSE(host.GetCursorRequest().IsActive());
        EXPECT_EQ(EditorUICursorMode::Normal,
                  host.GetCursorRequest().cursorMode);
        EXPECT_EQ(1u,
                  panelPtr->GetLastBuildStats().interactionStats.navigationEndCount);

        host.Shutdown();
    }

    TEST_F(EditorContextValidation, ViewportAllocatesRHIRenderTargetsForBoundDevice)
    {
        ViewportPanel viewport;
        EXPECT_FALSE(viewport.IsRHIRenderTargetReady());
        EXPECT_FALSE(viewport.EnsureRenderTargetSize(320, 180));
        EXPECT_EQ(ViewportRenderBackend::Placeholder,
                  viewport.GetRenderTargetState().backend);
        EXPECT_FALSE(viewport.GetRenderTargetState().hasDevice);

        EditorViewportFakeDevice device;
        viewport.SetRenderDevice(&device);

        ASSERT_TRUE(viewport.EnsureRenderTargetSize(320, 180));
        EXPECT_TRUE(viewport.IsRHIRenderTargetReady());
        EXPECT_EQ(ViewportRenderBackend::RHI, viewport.GetRenderTargetState().backend);
        EXPECT_TRUE(viewport.GetRenderTargetState().hasDevice);
        EXPECT_EQ(320u, viewport.GetRenderTargetState().width);
        EXPECT_EQ(180u, viewport.GetRenderTargetState().height);
        EXPECT_EQ(RHIFormat::RGBA8_UNORM, viewport.GetRenderTargetState().colorFormat);
        EXPECT_EQ(RHIFormat::D32_FLOAT, viewport.GetRenderTargetState().depthFormat);
        EXPECT_NE(nullptr, viewport.GetColorTarget());
        EXPECT_NE(nullptr, viewport.GetColorTargetView());
        EXPECT_NE(nullptr, viewport.GetColorShaderResourceView());
        EXPECT_NE(nullptr, viewport.GetDepthTarget());
        EXPECT_NE(nullptr, viewport.GetDepthTargetView());

        ASSERT_EQ(static_cast<size_t>(2), device.createdTextureDescs.size());
        EXPECT_EQ(320u, device.createdTextureDescs[0].width);
        EXPECT_EQ(180u, device.createdTextureDescs[0].height);
        EXPECT_EQ(RHIFormat::RGBA8_UNORM, device.createdTextureDescs[0].format);
        EXPECT_TRUE(HasFlag(device.createdTextureDescs[0].usage, RHITextureUsage::RenderTarget));
        EXPECT_TRUE(HasFlag(device.createdTextureDescs[0].usage, RHITextureUsage::ShaderResource));
        EXPECT_EQ(RHIFormat::D32_FLOAT, device.createdTextureDescs[1].format);
        EXPECT_TRUE(HasFlag(device.createdTextureDescs[1].usage, RHITextureUsage::DepthStencil));

        ASSERT_EQ(static_cast<size_t>(3), device.createdTextureViewDescs.size());
        EXPECT_EQ(RHITextureViewType::RenderTarget, device.createdTextureViewDescs[0].type);
        EXPECT_EQ(RHITextureViewType::ShaderResource, device.createdTextureViewDescs[1].type);
        EXPECT_EQ(RHITextureViewType::DepthStencil, device.createdTextureViewDescs[2].type);
        EXPECT_EQ(RHITextureAspect::Depth,
                  device.createdTextureViewDescs[2].subresourceRange.aspect);

        EditorViewportRecordingCommandContext commandContext;
        EXPECT_TRUE(viewport.RenderRHI(commandContext));
        EXPECT_TRUE(viewport.GetRenderTargetState().lastRenderRecorded);
        EXPECT_EQ(1u, viewport.GetRenderTargetState().frameCount);
        EXPECT_EQ(RHIResourceState::ShaderResource, viewport.GetRenderTargetState().colorState);
        EXPECT_EQ(RHIResourceState::DepthWrite, viewport.GetRenderTargetState().depthState);

        ASSERT_EQ(static_cast<size_t>(3), commandContext.textureBarriers.size());
        EXPECT_EQ(RHIResourceState::Undefined, commandContext.textureBarriers[0].stateBefore);
        EXPECT_EQ(RHIResourceState::RenderTarget, commandContext.textureBarriers[0].stateAfter);
        EXPECT_EQ(RHIResourceState::Undefined, commandContext.textureBarriers[1].stateBefore);
        EXPECT_EQ(RHIResourceState::DepthWrite, commandContext.textureBarriers[1].stateAfter);
        EXPECT_EQ(RHIResourceState::RenderTarget, commandContext.textureBarriers[2].stateBefore);
        EXPECT_EQ(RHIResourceState::ShaderResource, commandContext.textureBarriers[2].stateAfter);

        ASSERT_EQ(static_cast<size_t>(1), commandContext.renderPasses.size());
        const RHIRenderPassDesc& renderPass = commandContext.renderPasses[0];
        EXPECT_EQ(1u, renderPass.colorAttachmentCount);
        EXPECT_EQ(RHILoadOp::Clear, renderPass.colorAttachments[0].loadOp);
        EXPECT_EQ(RHIStoreOp::Store, renderPass.colorAttachments[0].storeOp);
        EXPECT_TRUE(renderPass.hasDepthStencil);
        EXPECT_EQ(RHILoadOp::Clear, renderPass.depthStencilAttachment.depthLoadOp);
        EXPECT_EQ(320u, renderPass.renderArea.width);
        EXPECT_EQ(180u, renderPass.renderArea.height);
        ASSERT_EQ(static_cast<size_t>(1), commandContext.viewports.size());
        EXPECT_FLOAT_EQ(320.0f, commandContext.viewports[0].width);
        EXPECT_FLOAT_EQ(180.0f, commandContext.viewports[0].height);
        ASSERT_EQ(static_cast<size_t>(1), commandContext.scissors.size());
        EXPECT_EQ(320u, commandContext.scissors[0].width);
        EXPECT_EQ(180u, commandContext.scissors[0].height);
        EXPECT_EQ(1u, commandContext.beginEventCount);
        EXPECT_EQ(1u, commandContext.endEventCount);
        EXPECT_EQ(1u, commandContext.endRenderPassCount);

        EXPECT_TRUE(viewport.EnsureRenderTargetSize(320, 180));
        EXPECT_EQ(static_cast<size_t>(2), device.createdTextureDescs.size());
        EXPECT_EQ(static_cast<size_t>(3), device.createdTextureViewDescs.size());

        EXPECT_TRUE(viewport.EnsureRenderTargetSize(640, 360));
        EXPECT_EQ(640u, viewport.GetRenderTargetState().width);
        EXPECT_EQ(360u, viewport.GetRenderTargetState().height);
        EXPECT_EQ(static_cast<size_t>(4), device.createdTextureDescs.size());
        EXPECT_EQ(static_cast<size_t>(6), device.createdTextureViewDescs.size());

        viewport.SetRenderDevice(nullptr);
        EXPECT_FALSE(viewport.IsRHIRenderTargetReady());
        EXPECT_EQ(ViewportRenderBackend::Placeholder,
                  viewport.GetRenderTargetState().backend);
        EXPECT_FALSE(viewport.GetRenderTargetState().hasDevice);
    }

    TEST_F(EditorContextValidation, ViewportBuildsRenderCameraAndRecordsSceneRenderState)
    {
        ViewportPanel viewport;
        viewport.SetCameraPosition(Vec3(1.0f, 2.0f, 3.0f));
        viewport.SetCameraTarget(Vec3(0.0f, 0.0f, 0.0f));

        Camera perspectiveCamera = viewport.BuildRenderCamera();
        EXPECT_EQ(Vec3(1.0f, 2.0f, 3.0f), perspectiveCamera.GetPosition());
        EXPECT_NEAR(0.0f, perspectiveCamera.GetProjection()[3][3], 0.0001f);

        viewport.SetCameraMode(ViewportCameraMode::TopDown);
        Camera topDownCamera = viewport.BuildRenderCamera();
        EXPECT_EQ(Vec3(1.0f, 2.0f, 3.0f), topDownCamera.GetPosition());
        EXPECT_NEAR(1.0f, topDownCamera.GetProjection()[3][3], 0.0001f);

        viewport.MarkSceneRenderResult(false,
                                       RHIResourceState::RenderTarget,
                                       RHIResourceState::DepthWrite,
                                       "SceneRenderer unavailable");
        EXPECT_FALSE(viewport.GetRenderTargetState().lastRenderRecorded);
        EXPECT_EQ(0u, viewport.GetRenderTargetState().frameCount);
        EXPECT_EQ("SceneRenderer unavailable",
                  viewport.GetRenderTargetState().fallbackReason);

        ViewportRenderGraphDiagnostics diagnostics;
        diagnostics.graphCompiled = true;
        diagnostics.graphCompileValid = false;
        diagnostics.graphExecutionSkipped = true;
        diagnostics.totalPasses = 8;
        diagnostics.culledPasses = 2;
        diagnostics.barrierCount = 5;
        diagnostics.textureBarrierCount = 4;
        diagnostics.bufferBarrierCount = 1;
        diagnostics.validationWarningCount = 1;
        diagnostics.validationErrorCount = 2;
        diagnostics.skippedReason = "RenderGraph compile failed";
        diagnostics.firstDiagnostic = "Attachment format mismatch";
        viewport.SetRenderGraphDiagnostics(diagnostics);
        EXPECT_TRUE(viewport.GetRenderTargetState()
                        .renderGraphDiagnostics.graphCompiled);
        EXPECT_FALSE(viewport.GetRenderTargetState()
                         .renderGraphDiagnostics.graphCompileValid);
        EXPECT_EQ(8u,
                  viewport.GetRenderTargetState()
                      .renderGraphDiagnostics.totalPasses);
        EXPECT_EQ("Attachment format mismatch",
                  viewport.GetRenderTargetState()
                      .renderGraphDiagnostics.firstDiagnostic);

        viewport.ClearRenderGraphDiagnostics();
        EXPECT_FALSE(viewport.GetRenderTargetState()
                         .renderGraphDiagnostics.graphCompiled);
        EXPECT_EQ(0u,
                  viewport.GetRenderTargetState()
                      .renderGraphDiagnostics.barrierCount);

        viewport.MarkSceneRenderResult(true,
                                       RHIResourceState::ShaderResource,
                                       RHIResourceState::DepthWrite,
                                       std::string());
        EXPECT_TRUE(viewport.GetRenderTargetState().lastRenderRecorded);
        EXPECT_EQ(1u, viewport.GetRenderTargetState().frameCount);
        EXPECT_EQ(RHIResourceState::ShaderResource,
                  viewport.GetRenderTargetState().colorState);
        EXPECT_EQ(RHIResourceState::DepthWrite,
                  viewport.GetRenderTargetState().depthState);
        EXPECT_TRUE(viewport.GetRenderTargetState().fallbackReason.empty());
    }

