    TEST_F(EditorContextValidation, ViewportRuntimeUIOverlayIsDisabledByDefault)
    {
        ViewportPanel viewport;
        EditorViewportFakeDevice device;
        viewport.SetRenderDevice(&device);

        ASSERT_TRUE(viewport.EnsureRenderTargetSize(320, 180));

        EditorViewportRecordingCommandContext commandContext;
        ASSERT_TRUE(viewport.RenderRHI(commandContext));
        EXPECT_EQ(RHIResourceState::ShaderResource,
                  viewport.GetRenderTargetState().colorState);
        EXPECT_FALSE(viewport.IsRuntimeUIOverlayEnabled());

        UI::UIRenderer renderer;
        ASSERT_TRUE(renderer.Initialize(&device));

        RHIDescriptorSetLayoutDesc textureLayoutDesc;
        textureLayoutDesc.debugName = "EditorViewportRuntimeUITextureLayout";
        textureLayoutDesc.AddBinding(0,
                                     RHIBindingType::CombinedTextureSampler,
                                     RHIShaderStage::Pixel);
        RHIDescriptorSetLayoutRef textureLayout =
            device.CreateDescriptorSetLayout(textureLayoutDesc);
        ASSERT_NE(nullptr, textureLayout.Get());

        EditorViewportFakePipeline pipeline;
        EXPECT_FALSE(viewport.RenderRuntimeUIOverlay(commandContext,
                                                     renderer,
                                                     &pipeline,
                                                     textureLayout.Get()));

        const ViewportRenderTargetState& state = viewport.GetRenderTargetState();
        EXPECT_FALSE(state.runtimeUIOverlayRecorded);
        EXPECT_EQ(0u, state.runtimeUIOverlayFrameCount);
        EXPECT_EQ(0u, state.runtimeUIOverlayDrawCallCount);
        EXPECT_EQ(RHIResourceState::ShaderResource, state.colorState);
        EXPECT_EQ("Runtime UI overlay disabled",
                  state.runtimeUIOverlayFallbackReason);

        renderer.Shutdown();
    }

    TEST_F(EditorContextValidation, ViewportSubmitsRuntimeUIOverlayThroughRHI)
    {
        ViewportPanel viewport;
        EditorViewportFakeDevice device;
        viewport.SetRenderDevice(&device);
        viewport.SetRuntimeUIOverlayEnabled(true);
        EXPECT_TRUE(viewport.IsRuntimeUIOverlayEnabled());

        ASSERT_TRUE(viewport.EnsureRenderTargetSize(320, 180));

        EditorViewportRecordingCommandContext commandContext;
        ASSERT_TRUE(viewport.RenderRHI(commandContext));
        EXPECT_EQ(RHIResourceState::ShaderResource, viewport.GetRenderTargetState().colorState);

        UI::UIRenderer renderer;
        ASSERT_TRUE(renderer.Initialize(&device));

        RHIDescriptorSetLayoutDesc textureLayoutDesc;
        textureLayoutDesc.debugName = "EditorViewportRuntimeUITextureLayout";
        textureLayoutDesc.AddBinding(0, RHIBindingType::CombinedTextureSampler, RHIShaderStage::Pixel);
        RHIDescriptorSetLayoutRef textureLayout = device.CreateDescriptorSetLayout(textureLayoutDesc);
        ASSERT_NE(nullptr, textureLayout.Get());

        EditorViewportFakePipeline pipeline;
        ASSERT_TRUE(viewport.RenderRuntimeUIOverlay(commandContext,
                                                    renderer,
                                                    &pipeline,
                                                    textureLayout.Get()));

        const ViewportRenderTargetState& state = viewport.GetRenderTargetState();
        EXPECT_TRUE(state.runtimeUIOverlayRecorded);
        EXPECT_EQ(RHIResourceState::ShaderResource, state.colorState);
        EXPECT_EQ(1u, state.runtimeUIOverlayFrameCount);
        EXPECT_GT(state.runtimeUIOverlayDrawCallCount, 0u);
        EXPECT_TRUE(state.runtimeUIOverlayFallbackReason.empty());

        EXPECT_EQ(&pipeline, commandContext.boundPipeline);
        EXPECT_NE(nullptr, commandContext.boundVertexBuffer);
        EXPECT_NE(nullptr, commandContext.boundIndexBuffer);
        EXPECT_EQ(RHIFormat::R32_UINT, commandContext.indexFormat);
        EXPECT_EQ(16u, commandContext.pushConstantSize);
        EXPECT_GE(commandContext.renderPasses.size(), static_cast<size_t>(2));
        const RHIRenderPassDesc& uiRenderPass = commandContext.renderPasses.back();
        EXPECT_EQ(1u, uiRenderPass.colorAttachmentCount);
        EXPECT_EQ(RHILoadOp::Load, uiRenderPass.colorAttachments[0].loadOp);
        EXPECT_FALSE(uiRenderPass.hasDepthStencil);
        EXPECT_EQ(320u, uiRenderPass.renderArea.width);
        EXPECT_EQ(180u, uiRenderPass.renderArea.height);
        EXPECT_EQ(state.runtimeUIOverlayDrawCallCount,
                  static_cast<uint32>(commandContext.drawIndexedIndexCounts.size()));

        ASSERT_FALSE(device.createdDescriptorSetDescs.empty());
        for (const RHIDescriptorSetDesc& desc : device.createdDescriptorSetDescs)
        {
            EXPECT_EQ(textureLayout.Get(), desc.layout);
        }
        EXPECT_EQ(static_cast<size_t>(1), device.createdDescriptorSetLayoutDescs.size());
        EXPECT_FALSE(device.createdBufferDescs.empty());
        EXPECT_FALSE(device.createdStagingBufferDescs.empty());

        renderer.Shutdown();
    }

