    TEST_F(EditorContextValidation,
           NativePanelCatalogPanelRoutesLayoutToolbarThroughCommands)
    {
        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 800;
        desc.surfaceHeight = 480;
        ASSERT_TRUE(host.Initialize(desc));

        uint32 saveLayoutCount = 0;
        uint32 reloadLayoutCount = 0;
        uint32 resetLayoutCount = 0;
        EditorCommandCatalogCallbacks callbacks;
        callbacks.saveLayout = [&saveLayoutCount]() {
            ++saveLayoutCount;
        };
        callbacks.reloadLayout = [&reloadLayoutCount]() {
            ++reloadLayoutCount;
        };
        callbacks.resetLayout = [&resetLayoutCount]() {
            ++resetLayoutCount;
        };
        ASSERT_TRUE(RegisterEditorCommandCatalog(host.GetCommandRegistry(),
                                                 callbacks));

        auto catalog = std::make_shared<NativePanelCatalogPanel>();
        NativePanelCatalogPanel* catalogPtr = catalog.get();
        host.RegisterPanel(catalog);
        host.SetPanelVisible(NativePanelCatalogPanel::PanelId(), true);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 800;
        frameDesc.surfaceHeight = 480;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        const NativePanelCatalogStats& stats = catalogPtr->GetLastBuildStats();
        EXPECT_EQ(3u, stats.layoutCommandButtonCount);
        EXPECT_EQ(3u, stats.layoutCommandIconButtonCount);
        EXPECT_EQ(3u, stats.layoutCommandExecutableCount);

        auto expectIconButton = [&canvas](const std::string& widgetName,
                                          const std::string& text,
                                          const std::string& iconName) {
            UI::Widget::Ptr widget = canvas.FindWidget(widgetName);
            ASSERT_NE(nullptr, widget);
            const EditorIconButton* iconButton =
                dynamic_cast<const EditorIconButton*>(widget.get());
            ASSERT_NE(nullptr, iconButton);
            EXPECT_EQ(text, iconButton->GetText());
            EXPECT_FALSE(iconButton->GetShowText());
            EXPECT_EQ(iconName, iconButton->GetIconName());
            EXPECT_TRUE(EditorVectorIconLibrary::IsKnownIcon(iconName));
        };
        expectIconButton("NativePanelCatalog.Layout.Save",
                         "Save",
                         "layout-save");
        expectIconButton("NativePanelCatalog.Layout.Reload",
                         "Reload",
                         "refresh");
        expectIconButton("NativePanelCatalog.Layout.Reset",
                         "Reset",
                         "reset");

        EditorViewportFakeDevice iconDevice;
        UI::UIRenderer iconRenderer;
        ASSERT_TRUE(iconRenderer.Initialize(&iconDevice));
        EXPECT_TRUE(host.RenderNativeUI(iconRenderer));
        for (const char* widgetName : {"NativePanelCatalog.Layout.Save",
                                       "NativePanelCatalog.Layout.Reload",
                                       "NativePanelCatalog.Layout.Reset"})
        {
            UI::Widget::Ptr widget = canvas.FindWidget(widgetName);
            ASSERT_NE(nullptr, widget);
            const EditorIconButton* iconButton =
                dynamic_cast<const EditorIconButton*>(widget.get());
            ASSERT_NE(nullptr, iconButton);
            EXPECT_TRUE(iconButton->GetLastIconDrawStats().knownIcon);
            EXPECT_EQ(0u,
                      iconButton->GetLastIconDrawStats().textFallbackCount);
        }
        iconRenderer.Shutdown();

        auto clickButton = [&canvas](const std::string& widgetName) {
            UI::Widget::Ptr widget = canvas.FindWidget(widgetName);
            ASSERT_NE(nullptr, widget);
            std::shared_ptr<UI::Button> button =
                std::dynamic_pointer_cast<UI::Button>(widget);
            ASSERT_NE(nullptr, button);
            EXPECT_TRUE(button->IsEnabled());
            const UI::Rect rect = button->GetGlobalRect();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            mouseDown.position = rect.Center();
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        };

        clickButton("NativePanelCatalog.Layout.Save");
        clickButton("NativePanelCatalog.Layout.Reload");
        clickButton("NativePanelCatalog.Layout.Reset");
        EXPECT_EQ(1u, saveLayoutCount);
        EXPECT_EQ(1u, reloadLayoutCount);
        EXPECT_EQ(1u, resetLayoutCount);
        EXPECT_EQ(3u, host.GetCommandDiagnostics().succeededCount);
        EXPECT_GE(host.GetCommandHistory().size(), static_cast<size_t>(3));

        host.EndFrame();
        host.Shutdown();
    }

    TEST_F(EditorContextValidation, NativeSceneHierarchyPanelBuildsTreeAndRoutesSelection)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 800;
        desc.surfaceHeight = 480;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeSceneHierarchyPanel>();
        host.RegisterPanel(panel);
        ASSERT_EQ(panel.get(), host.GetPanel("native.sceneHierarchy"));
        ASSERT_NE(nullptr, host.GetDockingModel().FindPlacement("native.sceneHierarchy"));
        EXPECT_EQ(EditorUIPanelDockArea::Left,
                  host.GetDockingModel().FindPlacement("native.sceneHierarchy")->area);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 800;
        frameDesc.surfaceHeight = 480;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        EXPECT_NE(nullptr,
                  canvas.FindWidget("Editor.PanelSurface.Panel.native.sceneHierarchy.Frame"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.NewScene"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.NoScene"));
        EXPECT_EQ(nullptr, canvas.FindWidget("NativeSceneHierarchy.CreateEmpty"));

        auto clickWidget = [&canvas](const UI::Widget::Ptr& widget) {
            ASSERT_NE(nullptr, widget);
            const UI::Rect rect = widget->GetGlobalRect();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            mouseDown.position = rect.Center();
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        };
        auto rightClickWidget = [&canvas](const UI::Widget::Ptr& widget) {
            ASSERT_NE(nullptr, widget);
            const UI::Rect rect = widget->GetGlobalRect();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            mouseDown.position = rect.Center();
            mouseDown.button = static_cast<int>(UI::UIMouseButton::Right);
            EXPECT_TRUE(canvas.HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        };

        clickWidget(canvas.FindWidget("NativeSceneHierarchy.NewScene"));

        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);
        EXPECT_TRUE(sceneManager->IsInitialized());

        host.BuildPanels();
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.CreateEmpty"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.Empty"));

        ActorSpawnParams rootParams;
        rootParams.name = "Root";
        SceneEntity* root = sceneManager->SpawnActor(rootParams);
        ASSERT_NE(nullptr, root);

        ActorSpawnParams childParams;
        childParams.name = "Child";
        childParams.parent = root;
        SceneEntity* child = sceneManager->SpawnActor(childParams);
        ASSERT_NE(nullptr, child);
        EXPECT_EQ(static_cast<size_t>(2), sceneManager->GetEntityCount());

        host.BuildPanels();
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(root->GetHandle())));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(child->GetHandle())));

        clickWidget(canvas.FindWidget("NativeSceneHierarchy.Row." +
                                      std::to_string(child->GetHandle())));
        EXPECT_EQ(child, context.GetSelectedEntity());

        clickWidget(canvas.FindWidget("NativeSceneHierarchy.CreateEmpty"));
        SceneEntity* created = context.GetSelectedEntity();
        ASSERT_NE(nullptr, created);
        EXPECT_NE(child, created);
        EXPECT_EQ(static_cast<size_t>(3), sceneManager->GetEntityCount());

        host.BuildPanels();
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(created->GetHandle())));

        rightClickWidget(canvas.FindWidget("NativeSceneHierarchy.Row." +
                                           std::to_string(child->GetHandle())));
        EXPECT_EQ(child, context.GetSelectedEntity());
        EXPECT_TRUE(host.GetContextMenu().IsOpen());

        host.BuildPanels();
        EXPECT_TRUE(host.GetContextMenu().GetLastBuildStats().open);
        EXPECT_EQ(4u, host.GetContextMenu().GetLastBuildStats().itemCount);
        EXPECT_EQ(1u, host.GetPopupLayer().GetLastBuildStats().popupCount);
        EXPECT_NE(nullptr,
                  canvas.FindWidget("Editor.ContextMenu.NativeSceneHierarchy.Entity"));
        UI::Widget::Ptr createChildButton =
            canvas.FindWidget(
                "Editor.ContextMenu.NativeSceneHierarchy.Entity.Item.entity.createChild");
        ASSERT_NE(nullptr, createChildButton);

        EditorViewportFakeDevice device;
        UI::UIRenderer renderer;
        ASSERT_TRUE(renderer.Initialize(&device));
        EXPECT_TRUE(host.RenderNativeUI(renderer));
        EXPECT_TRUE(host.GetNativeRenderStats().contextMenuOpen);
        EXPECT_EQ(4u, host.GetNativeRenderStats().contextMenuItemCount);

        clickWidget(createChildButton);
        SceneEntity* createdChild = context.GetSelectedEntity();
        ASSERT_NE(nullptr, createdChild);
        EXPECT_EQ(child, createdChild->GetParent());
        EXPECT_EQ(static_cast<size_t>(4), sceneManager->GetEntityCount());
        EXPECT_FALSE(host.GetContextMenu().IsOpen());

        host.BuildPanels();
        EXPECT_EQ(nullptr,
                  canvas.FindWidget("Editor.ContextMenu.NativeSceneHierarchy.Entity"));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(createdChild->GetHandle())));

        host.EndFrame();
        host.Shutdown();
    }

    TEST_F(EditorContextValidation, NativeSceneHierarchyPanelVirtualizesAndScrollsRows)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        std::vector<SceneEntity*> entities;
        entities.reserve(40);
        for (uint32 index = 0; index < 40u; ++index)
        {
            ActorSpawnParams params;
            params.name = "Root" + (index < 10u ? std::string("0") : std::string()) +
                          std::to_string(index);
            SceneEntity* entity = sceneManager->SpawnActor(params);
            ASSERT_NE(nullptr, entity);
            entities.push_back(entity);
        }

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 800;
        desc.surfaceHeight = 480;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeSceneHierarchyPanel>();
        host.RegisterPanel(panel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 800;
        frameDesc.surfaceHeight = 480;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.Viewport"));
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.Scrollbar.Thumb"));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(entities[0]->GetHandle())));
        EXPECT_EQ(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(entities.back()->GetHandle())));

        UI::Widget::Ptr viewport = canvas.FindWidget("NativeSceneHierarchy.Viewport");
        ASSERT_NE(nullptr, viewport);
        UI::UIEvent scroll;
        scroll.type = UI::UIEventType::Scroll;
        scroll.position = viewport->GetGlobalRect().Center();
        scroll.delta = Vec2(0.0f, -1.0f);
        EXPECT_TRUE(canvas.HandleEvent(scroll));

        host.BuildPanels();
        EXPECT_EQ(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(entities[0]->GetHandle())));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(entities[3]->GetHandle())));

        host.EndFrame();
        host.Shutdown();
    }

    TEST_F(EditorContextValidation, NativeSceneHierarchyPanelSearchFiltersRowsAndKeepsFocus)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams rootParams;
        rootParams.name = "Root";
        SceneEntity* root = sceneManager->SpawnActor(rootParams);
        ASSERT_NE(nullptr, root);

        ActorSpawnParams childParams;
        childParams.name = "Child";
        childParams.parent = root;
        SceneEntity* child = sceneManager->SpawnActor(childParams);
        ASSERT_NE(nullptr, child);

        ActorSpawnParams otherParams;
        otherParams.name = "Other";
        SceneEntity* other = sceneManager->SpawnActor(otherParams);
        ASSERT_NE(nullptr, other);

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 800;
        desc.surfaceHeight = 480;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeSceneHierarchyPanel>();
        host.RegisterPanel(panel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 800;
        frameDesc.surfaceHeight = 480;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        UI::Widget::Ptr searchWidget = canvas.FindWidget("NativeSceneHierarchy.Search");
        ASSERT_NE(nullptr, searchWidget);
        const UI::Rect searchRect = searchWidget->GetGlobalRect();
        UI::UIEvent mouseDown;
        mouseDown.type = UI::UIEventType::MouseDown;
        mouseDown.position = searchRect.Center();
        EXPECT_TRUE(canvas.HandleEvent(mouseDown));
        UI::UIEvent mouseUp = mouseDown;
        mouseUp.type = UI::UIEventType::MouseUp;
        EXPECT_TRUE(canvas.HandleEvent(mouseUp));

        host.BuildPanels();
        ASSERT_NE(nullptr, canvas.GetFocusedWidget());
        EXPECT_EQ("NativeSceneHierarchy.Search", canvas.GetFocusedWidget()->GetName());

        UI::UIEvent textInput;
        textInput.type = UI::UIEventType::TextInput;
        textInput.text = "ChildX";
        EXPECT_TRUE(canvas.HandleEvent(textInput));
        host.BuildPanels();
        EXPECT_NE(nullptr, canvas.FindWidget("NativeSceneHierarchy.NoMatches"));
        EXPECT_EQ(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(root->GetHandle())));
        ASSERT_NE(nullptr, canvas.GetFocusedWidget());
        EXPECT_EQ("NativeSceneHierarchy.Search", canvas.GetFocusedWidget()->GetName());

        UI::UIEvent backspace;
        backspace.type = UI::UIEventType::KeyDown;
        backspace.keyCode = static_cast<int>(UI::RVX_UI_KEY_BACKSPACE);
        EXPECT_TRUE(canvas.HandleEvent(backspace));
        host.BuildPanels();
        EXPECT_EQ(nullptr, canvas.FindWidget("NativeSceneHierarchy.NoMatches"));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(root->GetHandle())));
        EXPECT_NE(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(child->GetHandle())));
        EXPECT_EQ(nullptr,
                  canvas.FindWidget("NativeSceneHierarchy.Row." +
                                    std::to_string(other->GetHandle())));

        auto searchInput =
            std::dynamic_pointer_cast<EditorTextInput>(
                canvas.FindWidget("NativeSceneHierarchy.Search"));
        ASSERT_NE(nullptr, searchInput);
        EXPECT_EQ("Child", searchInput->GetText());

        host.EndFrame();
        host.Shutdown();
    }

    TEST_F(EditorContextValidation, NativeSceneHierarchyCachesSnapshotsUntilSceneOrFilterChanges)
    {
        auto& context = EditorContext::Get();
        context.CloseProject();
        context.NewScene();
        SceneManager* sceneManager = context.GetActiveSceneManager();
        ASSERT_NE(nullptr, sceneManager);

        ActorSpawnParams rootParams;
        rootParams.name = "Root";
        SceneEntity* root = sceneManager->SpawnActor(rootParams);
        ASSERT_NE(nullptr, root);

        ActorSpawnParams childParams;
        childParams.name = "Child";
        childParams.parent = root;
        SceneEntity* child = sceneManager->SpawnActor(childParams);
        ASSERT_NE(nullptr, child);

        ActorSpawnParams otherParams;
        otherParams.name = "Other";
        SceneEntity* other = sceneManager->SpawnActor(otherParams);
        ASSERT_NE(nullptr, other);

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 800;
        desc.surfaceHeight = 480;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<NativeSceneHierarchyPanel>();
        NativeSceneHierarchyPanel* panelPtr = panel.get();
        host.RegisterPanel(panel);

        auto runFrame = [&host]() {
            EditorUIFrameDesc frameDesc;
            frameDesc.surfaceWidth = 800;
            frameDesc.surfaceHeight = 480;
            frameDesc.deltaTime = 0.016f;
            ASSERT_TRUE(host.BeginFrame(frameDesc));
            host.BuildPanels();
            host.EndFrame();
        };

        runFrame();
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().totalEntityCount);
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().visibleRowCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().sceneSnapshotRefreshCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedSceneSnapshot);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        runFrame();
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().totalEntityCount);
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().visibleRowCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().sceneSnapshotRefreshCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedSceneSnapshot);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        context.SelectEntity(child);
        runFrame();
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectedRowVisible);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().sceneSnapshotRefreshCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedSceneSnapshot);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        EditorUIFrameDesc editFrame;
        editFrame.surfaceWidth = 800;
        editFrame.surfaceHeight = 480;
        editFrame.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(editFrame));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        UI::Widget::Ptr searchWidget = canvas.FindWidget("NativeSceneHierarchy.Search");
        ASSERT_NE(nullptr, searchWidget);
        const UI::Rect searchRect = searchWidget->GetGlobalRect();
        UI::UIEvent mouseDown;
        mouseDown.type = UI::UIEventType::MouseDown;
        mouseDown.position = searchRect.Center();
        EXPECT_TRUE(canvas.HandleEvent(mouseDown));
        UI::UIEvent mouseUp = mouseDown;
        mouseUp.type = UI::UIEventType::MouseUp;
        EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        UI::UIEvent textInput;
        textInput.type = UI::UIEventType::TextInput;
        textInput.text = "Child";
        EXPECT_TRUE(canvas.HandleEvent(textInput));
        host.EndFrame();

        runFrame();
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().totalEntityCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleRowCount);
        EXPECT_EQ(1u, panelPtr->GetLastBuildStats().sceneSnapshotRefreshCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().reusedSceneSnapshot);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);
        EXPECT_TRUE(panelPtr->GetLastBuildStats().selectedRowVisible);

        ActorSpawnParams extraParams;
        extraParams.name = "ChildExtra";
        extraParams.parent = root;
        SceneEntity* extra = sceneManager->SpawnActor(extraParams);
        ASSERT_NE(nullptr, extra);

        runFrame();
        EXPECT_EQ(4u, panelPtr->GetLastBuildStats().totalEntityCount);
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().visibleRowCount);
        EXPECT_EQ(2u, panelPtr->GetLastBuildStats().sceneSnapshotRefreshCount);
        EXPECT_EQ(3u, panelPtr->GetLastBuildStats().visibleSnapshotRefreshCount);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedSceneSnapshot);
        EXPECT_FALSE(panelPtr->GetLastBuildStats().reusedVisibleSnapshot);

        host.Shutdown();
        context.CloseProject();
    }

    TEST_F(EditorContextValidation, EditorUIHostRoutesCommandsShortcutsAndPropertyDrawers)
    {
        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 640;
        desc.surfaceHeight = 360;
        ASSERT_TRUE(host.Initialize(desc));

        uint32 saveCount = 0;
        EditorCommandDesc saveCommand;
        saveCommand.id = "file.save";
        saveCommand.displayName = "Save";
        saveCommand.category = "File";
        saveCommand.shortcut =
            EditorShortcut::Key('S', UI::ToMask(UI::UIInputModifier::Ctrl));
        saveCommand.callback = [&saveCount](EditorCommandContext& context) {
            ASSERT_NE(nullptr, context.host);
            ++saveCount;
        };
        EXPECT_TRUE(host.GetCommandRegistry().RegisterCommand(std::move(saveCommand)));
        EXPECT_FALSE(host.GetCommandRegistry().RegisterCommand(EditorCommandDesc{"file.save"}));
        EXPECT_TRUE(host.ExecuteCommand("file.save"));
        EXPECT_EQ(1u, saveCount);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 640;
        frameDesc.surfaceHeight = 360;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.EndFrame();

        frameDesc.input.SetKeyDown('S', true);
        frameDesc.input.modifiers = UI::ToMask(UI::UIInputModifier::Ctrl);
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.EndFrame();
        EXPECT_EQ(2u, saveCount);
        EXPECT_TRUE(host.GetLastShortcutRouteResult().shortcutInputDetected);
        EXPECT_TRUE(host.GetLastShortcutRouteResult().shortcutDispatchAttempted);
        EXPECT_FALSE(host.GetLastShortcutRouteResult().shortcutDispatchBlocked);
        EXPECT_EQ(EditorShortcutRouteBlockReason::None,
                  host.GetLastShortcutRouteResult().blockReason);
        EXPECT_EQ("file.save",
                  host.GetLastShortcutRouteResult().commandResult.commandId);

        frameDesc.input.wantsKeyboardCapture = true;
        frameDesc.input.SetKeyDown('S', false);
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.EndFrame();
        frameDesc.input.SetKeyDown('S', true);
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.EndFrame();
        EXPECT_EQ(2u, saveCount);
        EXPECT_TRUE(host.GetLastShortcutRouteResult().shortcutInputDetected);
        EXPECT_TRUE(host.GetLastShortcutRouteResult().shortcutDispatchAttempted);
        EXPECT_TRUE(host.GetLastShortcutRouteResult().shortcutDispatchBlocked);
        EXPECT_EQ(EditorShortcutRouteBlockReason::KeyboardCapture,
                  host.GetLastShortcutRouteResult().blockReason);
        EXPECT_EQ(EditorCommandExecutionStatus::BlockedByKeyboardCapture,
                  host.GetLastShortcutRouteResult().commandResult.status);

        host.GetCommandRegistry().SetCommandEnabled("file.save", false);
        EXPECT_FALSE(host.ExecuteCommand("file.save"));

        EditorAssetReferenceFixture fixture;
        Property weightProperty = MakeWeightProperty();
        uint32 drawCount = 0;
        EditorPropertyDrawerDesc drawer;
        drawer.propertyType = PropertyType::Float;
        drawer.debugName = "Float Drawer";
        drawer.callback = [&drawCount, &fixture](EditorPropertyDrawerContext& context) {
            EXPECT_EQ(&fixture, context.instance);
            EXPECT_NE(nullptr, context.property);
            if (context.property)
            {
                EXPECT_EQ(PropertyType::Float, context.property->GetType());
            }
            ++drawCount;
            return true;
        };
        EXPECT_TRUE(host.GetPropertyDrawerRegistry().RegisterDrawer(std::move(drawer)));
        EXPECT_TRUE(host.GetPropertyDrawerRegistry().HasDrawer(PropertyType::Float));

        EditorPropertyDrawerContext drawerContext;
        drawerContext.host = &host;
        drawerContext.ui = &host.GetUIContext();
        drawerContext.canvas = &host.GetUIContext().GetCanvas();
        drawerContext.property = &weightProperty;
        drawerContext.instance = &fixture;
        EXPECT_TRUE(host.GetPropertyDrawerRegistry().DrawProperty(drawerContext));
        EXPECT_EQ(1u, drawCount);

        Property visibleProperty = MakeVisibleProperty();
        drawerContext.property = &visibleProperty;
        EXPECT_FALSE(host.GetPropertyDrawerRegistry().DrawProperty(drawerContext));

        host.Shutdown();
    }

    TEST_F(EditorContextValidation, EditorUIHostTracksNativePanelInputRouting)
    {
        class RoutingProbePanel final : public IEditorUIPanel
        {
        public:
            RoutingProbePanel()
            {
                desc.id = "native.routing.probe";
                desc.title = "Routing Probe";
                desc.defaultDockArea = EditorUIPanelDockArea::Center;
                desc.visibleByDefault = true;
                desc.closable = false;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }

            void BuildUI(EditorUIPanelFrameContext& context) override
            {
                ++buildCount;
                contentBounds = context.contentBounds;
                sawHovered = context.isHovered;
                sawActive = context.isActive;
                sawKeyboardFocus = context.hasKeyboardFocus;
                sawMouseCapture = context.hasMouseCapture;
            }

            EditorUIPanelDesc desc;
            UI::Rect contentBounds;
            uint32 buildCount = 0;
            bool sawHovered = false;
            bool sawActive = false;
            bool sawKeyboardFocus = false;
            bool sawMouseCapture = false;
        };

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 640;
        desc.surfaceHeight = 360;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<RoutingProbePanel>();
        RoutingProbePanel* probe = panel.get();
        host.RegisterPanel(std::move(panel));

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 640;
        frameDesc.surfaceHeight = 360;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();
        host.EndFrame();

        ASSERT_GT(probe->buildCount, 0u);
        ASSERT_GT(probe->contentBounds.width, 1.0f);
        ASSERT_GT(probe->contentBounds.height, 1.0f);
        EXPECT_FALSE(host.WantsMouseCapture());
        EXPECT_FALSE(host.WantsKeyboardCapture());

        frameDesc.input = {};
        frameDesc.input.mousePosition = probe->contentBounds.Position() + Vec2(8.0f, 8.0f);
        frameDesc.input.SetMouseButtonDown(UI::UIMouseButton::Left, true);
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        const EditorPanelInputRoutingState& clickRoute = host.GetInputRoutingState();
        EXPECT_EQ("native.routing.probe", clickRoute.hoveredPanelId);
        EXPECT_EQ("native.routing.probe", clickRoute.activePanelId);
        EXPECT_EQ("native.routing.probe", clickRoute.keyboardFocusPanelId);
        EXPECT_EQ("native.routing.probe", clickRoute.mouseCapturePanelId);
        EXPECT_TRUE(clickRoute.wantsMouseCapture);
        EXPECT_TRUE(clickRoute.wantsKeyboardCapture);
        EXPECT_TRUE(host.IsPanelHovered("native.routing.probe"));
        EXPECT_TRUE(host.IsPanelActive("native.routing.probe"));
        EXPECT_TRUE(host.IsPanelKeyboardFocused("native.routing.probe"));
        EXPECT_TRUE(host.IsPanelMouseCaptured("native.routing.probe"));
        EXPECT_TRUE(probe->sawHovered);
        EXPECT_TRUE(probe->sawActive);
        EXPECT_TRUE(probe->sawKeyboardFocus);
        EXPECT_TRUE(probe->sawMouseCapture);
        host.EndFrame();

        frameDesc.input = {};
        frameDesc.input.mousePosition = probe->contentBounds.Position() + Vec2(8.0f, 8.0f);
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        const EditorPanelInputRoutingState& releaseRoute = host.GetInputRoutingState();
        EXPECT_EQ("native.routing.probe", releaseRoute.hoveredPanelId);
        EXPECT_EQ("native.routing.probe", releaseRoute.activePanelId);
        EXPECT_EQ("native.routing.probe", releaseRoute.keyboardFocusPanelId);
        EXPECT_TRUE(releaseRoute.mouseCapturePanelId.empty());
        EXPECT_TRUE(releaseRoute.wantsMouseCapture);
        EXPECT_TRUE(releaseRoute.wantsKeyboardCapture);
        EXPECT_FALSE(host.IsPanelMouseCaptured("native.routing.probe"));
        EXPECT_TRUE(probe->sawKeyboardFocus);
        EXPECT_FALSE(probe->sawMouseCapture);

        host.EndFrame();

        frameDesc.input = {};
        frameDesc.input.mousePosition = probe->contentBounds.Position() + Vec2(8.0f, 8.0f);
        frameDesc.input.SetMouseButtonDown(UI::UIMouseButton::Right, true);
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        const EditorPanelInputRoutingState& rightPressRoute =
            host.GetInputRoutingState();
        EXPECT_EQ("native.routing.probe", rightPressRoute.activePanelId);
        EXPECT_EQ("native.routing.probe", rightPressRoute.mouseCapturePanelId);
        EXPECT_TRUE(host.IsPanelMouseCaptured("native.routing.probe"));
        EXPECT_TRUE(probe->sawActive);
        EXPECT_TRUE(probe->sawMouseCapture);
        host.EndFrame();

        host.Shutdown();
    }

    TEST_F(EditorContextValidation,
           EditorUIHostActivatesViewportShortcutScopeForNativeViewportFocus)
    {
        class ViewportScopeProbePanel final : public IEditorUIPanel
        {
        public:
            ViewportScopeProbePanel()
            {
                desc.id = NativeViewportPanel::PanelId();
                desc.title = "Viewport";
                desc.defaultDockArea = EditorUIPanelDockArea::Center;
                desc.visibleByDefault = true;
                desc.closable = false;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }

            void BuildUI(EditorUIPanelFrameContext& context) override
            {
                EXPECT_EQ(NativeViewportPanel::PanelId(), context.panelId);
                contentBounds = context.contentBounds;
                sawKeyboardFocus = context.hasKeyboardFocus;
                sawMouseCapture = context.hasMouseCapture;
                ++buildCount;
            }

            EditorUIPanelDesc desc;
            UI::Rect contentBounds;
            bool sawKeyboardFocus = false;
            bool sawMouseCapture = false;
            uint32 buildCount = 0;
        };

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 640;
        desc.surfaceHeight = 360;
        ASSERT_TRUE(host.Initialize(desc));

        auto panel = std::make_shared<ViewportScopeProbePanel>();
        ViewportScopeProbePanel* probe = panel.get();
        host.RegisterPanel(std::move(panel));

        uint32 globalCount = 0;
        EditorCommandDesc globalCommand;
        globalCommand.id = "tools.globalW";
        globalCommand.displayName = "Global W";
        globalCommand.shortcut = EditorShortcut::Key('W');
        globalCommand.callback = [&globalCount](EditorCommandContext&) {
            ++globalCount;
        };
        ASSERT_TRUE(host.GetCommandRegistry().RegisterCommand(std::move(globalCommand)));

        uint32 viewportCount = 0;
        EditorCommandDesc viewportCommand;
        viewportCommand.id = "tools.viewportW";
        viewportCommand.displayName = "Viewport W";
        viewportCommand.shortcut = EditorShortcut::Key('W');
        viewportCommand.shortcutScopeMask = RVX_EDITOR_COMMAND_SCOPE_VIEWPORT_MASK;
        viewportCommand.allowWhenKeyboardCaptured = true;
        viewportCommand.callback =
            [&viewportCount](EditorCommandContext& context) {
                EXPECT_NE(0u,
                          context.activeShortcutScopeMask &
                              RVX_EDITOR_COMMAND_SCOPE_VIEWPORT_MASK);
                ++viewportCount;
            };
        ASSERT_TRUE(host.GetCommandRegistry().RegisterCommand(
            std::move(viewportCommand)));
        EXPECT_TRUE(host.GetCommandRegistry().GetShortcutConflicts().empty());

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 640;
        frameDesc.surfaceHeight = 360;
        frameDesc.deltaTime = 0.016f;

        auto runFrame = [&](UI::UIInputSnapshot input) {
            frameDesc.input = std::move(input);
            ASSERT_TRUE(host.BeginFrame(frameDesc));
            host.BuildPanels();
            host.EndFrame();
        };

        auto runFrameWithRouteResult =
            [&](UI::UIInputSnapshot input) -> EditorCommandShortcutRouteResult {
            frameDesc.input = std::move(input);
            EXPECT_TRUE(host.BeginFrame(frameDesc));
            EditorCommandShortcutRouteResult result =
                host.GetLastShortcutRouteResult();
            host.BuildPanels();
            host.EndFrame();
            return result;
        };

        runFrame({});
        ASSERT_GT(probe->buildCount, 0u);
        ASSERT_GT(probe->contentBounds.width, 1.0f);
        ASSERT_GT(probe->contentBounds.height, 1.0f);

        UI::UIInputSnapshot globalKey;
        globalKey.SetKeyDown('W', true);
        EditorCommandShortcutRouteResult result =
            runFrameWithRouteResult(globalKey);
        EXPECT_EQ(EditorCommandExecutionStatus::Succeeded,
                  result.commandResult.status);
        EXPECT_EQ("tools.globalW", result.commandResult.commandId);
        EXPECT_EQ(RVX_EDITOR_COMMAND_SCOPE_GLOBAL_MASK,
                  result.activeShortcutScopeMask);
        EXPECT_EQ(1u, globalCount);
        EXPECT_EQ(0u, viewportCount);

        runFrame({});

        UI::UIInputSnapshot clickViewport;
        clickViewport.mousePosition =
            probe->contentBounds.Position() + Vec2(8.0f, 8.0f);
        clickViewport.SetMouseButtonDown(UI::UIMouseButton::Left, true);
        runFrame(clickViewport);
        EXPECT_EQ(NativeViewportPanel::PanelId(),
                  host.GetInputRoutingState().keyboardFocusPanelId);
        EXPECT_EQ(NativeViewportPanel::PanelId(),
                  host.GetInputRoutingState().mouseCapturePanelId);
        EXPECT_TRUE(probe->sawKeyboardFocus);
        EXPECT_TRUE(probe->sawMouseCapture);

        UI::UIInputSnapshot releaseViewport;
        releaseViewport.mousePosition = clickViewport.mousePosition;
        runFrame(releaseViewport);
        EXPECT_EQ(NativeViewportPanel::PanelId(),
                  host.GetInputRoutingState().keyboardFocusPanelId);
        EXPECT_TRUE(host.GetInputRoutingState().mouseCapturePanelId.empty());
        EXPECT_TRUE(host.WantsKeyboardCapture());

        UI::UIInputSnapshot viewportKey;
        viewportKey.SetKeyDown('W', true);
        viewportKey.wantsKeyboardCapture = host.WantsKeyboardCapture();
        result = runFrameWithRouteResult(viewportKey);
        EXPECT_EQ(EditorCommandExecutionStatus::Succeeded,
                  result.commandResult.status);
        EXPECT_EQ("tools.viewportW", result.commandResult.commandId);
        EXPECT_NE(0u,
                  result.activeShortcutScopeMask &
                      RVX_EDITOR_COMMAND_SCOPE_VIEWPORT_MASK);
        EXPECT_NE(0u,
                  result.activeShortcutScopeMask &
                      RVX_EDITOR_COMMAND_SCOPE_FOCUSED_PANEL_MASK);
        EXPECT_EQ(1u, globalCount);
        EXPECT_EQ(1u, viewportCount);

        host.Shutdown();
    }

