    TEST_F(EditorContextValidation, EditorDockingModelClampsFloatingPanelBounds)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement floating;
        floating.panelId = "native.float.clamp";
        floating.area = EditorUIPanelDockArea::Floating;
        ASSERT_TRUE(model.DockPanel(floating));

        EditorDockFloatingBounds oversized;
        oversized.x = -1.0f;
        oversized.y = 2.0f;
        oversized.width = 1.4f;
        oversized.height = -0.1f;
        EXPECT_TRUE(model.SetFloatingPanelBounds("native.float.clamp", oversized));

        const EditorDockPanelPlacement* clamped =
            model.FindPlacement("native.float.clamp");
        ASSERT_NE(nullptr, clamped);
        EXPECT_TRUE(clamped->hasFloatingBounds);
        EXPECT_FLOAT_EQ(0.0f, clamped->floatingBounds.x);
        EXPECT_FLOAT_EQ(0.90f, clamped->floatingBounds.y);
        EXPECT_FLOAT_EQ(0.90f, clamped->floatingBounds.width);
        EXPECT_FLOAT_EQ(0.10f, clamped->floatingBounds.height);

        EditorDockFloatingBounds small;
        small.x = 0.40f;
        small.y = 0.35f;
        small.width = 0.02f;
        small.height = 0.03f;
        EXPECT_TRUE(model.SetFloatingPanelBounds("native.float.clamp", small));
        clamped = model.FindPlacement("native.float.clamp");
        ASSERT_NE(nullptr, clamped);
        EXPECT_FLOAT_EQ(0.40f, clamped->floatingBounds.x);
        EXPECT_FLOAT_EQ(0.35f, clamped->floatingBounds.y);
        EXPECT_FLOAT_EQ(0.10f, clamped->floatingBounds.width);
        EXPECT_FLOAT_EQ(0.10f, clamped->floatingBounds.height);

        EditorDockPanelPlacement docked;
        docked.panelId = "native.docked";
        docked.area = EditorUIPanelDockArea::Left;
        ASSERT_TRUE(model.DockPanel(docked));
        EXPECT_FALSE(model.SetFloatingPanelBounds("native.docked", small));
    }

    TEST_F(EditorContextValidation, EditorDockingModelBringsFloatingPanelsToFront)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement back;
        back.panelId = "native.float.back";
        back.area = EditorUIPanelDockArea::Floating;
        ASSERT_TRUE(model.DockPanel(back));

        EditorDockPanelPlacement front;
        front.panelId = "native.float.front";
        front.area = EditorUIPanelDockArea::Floating;
        ASSERT_TRUE(model.DockPanel(front));

        const EditorDockPanelPlacement* backPlacement =
            model.FindPlacement("native.float.back");
        const EditorDockPanelPlacement* frontPlacement =
            model.FindPlacement("native.float.front");
        ASSERT_NE(nullptr, backPlacement);
        ASSERT_NE(nullptr, frontPlacement);
        EXPECT_GT(frontPlacement->floatingZOrder, backPlacement->floatingZOrder);

        ASSERT_TRUE(model.BringFloatingPanelToFront("native.float.back"));
        backPlacement = model.FindPlacement("native.float.back");
        frontPlacement = model.FindPlacement("native.float.front");
        ASSERT_NE(nullptr, backPlacement);
        ASSERT_NE(nullptr, frontPlacement);
        EXPECT_GT(backPlacement->floatingZOrder, frontPlacement->floatingZOrder);

        EditorDockPanelPlacement docked;
        docked.panelId = "native.docked.front";
        docked.area = EditorUIPanelDockArea::Left;
        ASSERT_TRUE(model.DockPanel(docked));
        EXPECT_FALSE(model.BringFloatingPanelToFront("native.docked.front"));
        EXPECT_FALSE(model.BringFloatingPanelToFront("missing.panel"));
    }

    TEST_F(EditorContextValidation, EditorDockingModelMovesFloatingPanelToDockArea)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement floating;
        floating.panelId = "native.float.dock";
        floating.area = EditorUIPanelDockArea::Floating;
        floating.hasFloatingBounds = true;
        floating.floatingBounds.x = 0.20f;
        floating.floatingBounds.y = 0.20f;
        floating.floatingBounds.width = 0.30f;
        floating.floatingBounds.height = 0.30f;
        floating.floatingZOrder = 3;
        ASSERT_TRUE(model.DockPanel(floating));

        ASSERT_TRUE(model.SetPanelDockArea("native.float.dock",
                                           EditorUIPanelDockArea::Left));
        const EditorDockPanelPlacement* docked =
            model.FindPlacement("native.float.dock");
        ASSERT_NE(nullptr, docked);
        EXPECT_EQ(EditorUIPanelDockArea::Left, docked->area);
        EXPECT_FALSE(docked->hasFloatingBounds);
        EXPECT_EQ(0u, docked->floatingZOrder);
        EXPECT_FALSE(model.BringFloatingPanelToFront("native.float.dock"));

        ASSERT_TRUE(model.SetPanelDockArea("native.float.dock",
                                           EditorUIPanelDockArea::Floating));
        docked = model.FindPlacement("native.float.dock");
        ASSERT_NE(nullptr, docked);
        EXPECT_EQ(EditorUIPanelDockArea::Floating, docked->area);
        EXPECT_GT(docked->floatingZOrder, 0u);
        EXPECT_FALSE(model.SetPanelDockArea("missing.panel",
                                            EditorUIPanelDockArea::Right));

        EditorDockPanelPlacement firstTab;
        firstTab.panelId = "native.tab.dock.area.first";
        firstTab.area = EditorUIPanelDockArea::Center;
        firstTab.tabStackId = "center.dock.area";
        firstTab.order = 1;
        ASSERT_TRUE(model.DockPanel(firstTab));

        EditorDockPanelPlacement secondTab;
        secondTab.panelId = "native.tab.dock.area.second";
        secondTab.area = EditorUIPanelDockArea::Center;
        secondTab.tabStackId = "center.dock.area";
        secondTab.order = 2;
        ASSERT_TRUE(model.DockPanel(secondTab));

        ASSERT_TRUE(model.SetPanelDockArea("native.tab.dock.area.second",
                                           EditorUIPanelDockArea::Center));
        const EditorDockPanelPlacement* independent =
            model.FindPlacement("native.tab.dock.area.second");
        ASSERT_NE(nullptr, independent);
        EXPECT_EQ(EditorUIPanelDockArea::Center, independent->area);
        EXPECT_TRUE(independent->tabStackId.empty());
        EXPECT_EQ(1u, model.GetTabStackPanelCount("center.dock.area"));
    }

    TEST_F(EditorContextValidation, EditorDockingModelTracksDockDropPreview)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement docked;
        docked.panelId = "native.docked.preview";
        docked.area = EditorUIPanelDockArea::Left;
        ASSERT_TRUE(model.DockPanel(docked));

        EXPECT_FALSE(model.SetDockDropPreview("missing.panel",
                                              EditorUIPanelDockArea::Left));
        EXPECT_FALSE(model.SetDockDropPreview("native.docked.preview",
                                              EditorUIPanelDockArea::Right));

        EditorDockPanelPlacement dockTab;
        dockTab.panelId = "native.docked.tab.preview";
        dockTab.area = EditorUIPanelDockArea::Center;
        dockTab.tabStackId = "center.preview";
        ASSERT_TRUE(model.DockPanel(dockTab));

        ASSERT_TRUE(model.SetDockDropPreview("native.docked.tab.preview",
                                             EditorUIPanelDockArea::Right));
        EXPECT_TRUE(model.GetDockDropPreview().active);
        EXPECT_EQ("native.docked.tab.preview", model.GetDockDropPreview().panelId);
        EXPECT_EQ(EditorUIPanelDockArea::Right, model.GetDockDropPreview().area);

        model.ClearDockDropPreview("native.docked.tab.preview");
        EXPECT_FALSE(model.GetDockDropPreview().active);

        EditorDockPanelPlacement floating;
        floating.panelId = "native.float.preview";
        floating.area = EditorUIPanelDockArea::Floating;
        ASSERT_TRUE(model.DockPanel(floating));

        ASSERT_TRUE(model.SetDockDropPreview("native.float.preview",
                                             EditorUIPanelDockArea::Left));
        EXPECT_TRUE(model.GetDockDropPreview().active);
        EXPECT_EQ("native.float.preview", model.GetDockDropPreview().panelId);
        EXPECT_EQ(EditorUIPanelDockArea::Left, model.GetDockDropPreview().area);

        model.ClearDockDropPreview("other.panel");
        EXPECT_TRUE(model.GetDockDropPreview().active);

        model.ClearDockDropPreview("native.float.preview");
        EXPECT_FALSE(model.GetDockDropPreview().active);

        ASSERT_TRUE(model.SetDockDropPreview("native.float.preview",
                                             EditorUIPanelDockArea::Bottom));
        ASSERT_TRUE(model.SetPanelDockArea("native.float.preview",
                                           EditorUIPanelDockArea::Center));
        EXPECT_FALSE(model.GetDockDropPreview().active);
        EXPECT_FALSE(model.SetDockDropPreview("native.float.preview",
                                              EditorUIPanelDockArea::Right));
    }

    TEST_F(EditorContextValidation, EditorDockingModelTracksDockTabStacks)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement first;
        first.panelId = "native.tab.first";
        first.area = EditorUIPanelDockArea::Center;
        first.order = 2;
        first.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(first));

        EditorDockPanelPlacement second;
        second.panelId = "native.tab.second";
        second.area = EditorUIPanelDockArea::Center;
        second.order = 1;
        second.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(second));

        EXPECT_EQ(2u, model.GetTabStackPanelCount("center.authoring"));
        EXPECT_EQ("native.tab.first",
                  model.GetActiveDockTab("center.authoring"));
        EXPECT_EQ("native.tab.first",
                  model.ResolveActiveDockTab("center.authoring"));

        ASSERT_TRUE(model.SetActiveDockTab("native.tab.second"));
        EXPECT_EQ("native.tab.second",
                  model.GetActiveDockTab("center.authoring"));
        EXPECT_EQ("native.tab.second",
                  model.ResolveActiveDockTab("center.authoring"));

        model.SetPanelVisible("native.tab.second", false);
        EXPECT_EQ(1u, model.GetTabStackPanelCount("center.authoring"));
        EXPECT_EQ("native.tab.first",
                  model.ResolveActiveDockTab("center.authoring"));

        ASSERT_TRUE(model.SetPanelTabStack("native.tab.first", ""));
        EXPECT_EQ(0u, model.GetTabStackPanelCount("center.authoring"));
        EXPECT_TRUE(model.ResolveActiveDockTab("center.authoring").empty());

        EditorDockPanelPlacement floating;
        floating.panelId = "native.tab.float";
        floating.area = EditorUIPanelDockArea::Floating;
        ASSERT_TRUE(model.DockPanel(floating));
        EXPECT_FALSE(model.SetPanelTabStack("native.tab.float", "float.stack"));
        EXPECT_FALSE(model.SetActiveDockTab("native.tab.float"));
    }

    TEST_F(EditorContextValidation, EditorDockingModelMovesDockTabsWithinStack)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement first;
        first.panelId = "native.tab.order.first";
        first.area = EditorUIPanelDockArea::Center;
        first.order = 10;
        first.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(first));

        EditorDockPanelPlacement second;
        second.panelId = "native.tab.order.second";
        second.area = EditorUIPanelDockArea::Center;
        second.order = 20;
        second.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(second));

        EditorDockPanelPlacement third;
        third.panelId = "native.tab.order.third";
        third.area = EditorUIPanelDockArea::Center;
        third.order = 30;
        third.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(third));

        ASSERT_TRUE(model.SetActiveDockTab("native.tab.order.second"));
        ASSERT_TRUE(model.MoveDockTab("native.tab.order.third",
                                      "native.tab.order.first",
                                      false));
        EXPECT_EQ(10u, model.FindPlacement("native.tab.order.third")->order);
        EXPECT_EQ(20u, model.FindPlacement("native.tab.order.first")->order);
        EXPECT_EQ(30u, model.FindPlacement("native.tab.order.second")->order);
        EXPECT_EQ("native.tab.order.second",
                  model.ResolveActiveDockTab("center.authoring"));

        ASSERT_TRUE(model.MoveDockTab("native.tab.order.third",
                                      "native.tab.order.second",
                                      true));
        EXPECT_EQ(10u, model.FindPlacement("native.tab.order.first")->order);
        EXPECT_EQ(20u, model.FindPlacement("native.tab.order.second")->order);
        EXPECT_EQ(30u, model.FindPlacement("native.tab.order.third")->order);

        EditorDockPanelPlacement otherStack;
        otherStack.panelId = "native.tab.order.other";
        otherStack.area = EditorUIPanelDockArea::Center;
        otherStack.order = 40;
        otherStack.tabStackId = "center.other";
        ASSERT_TRUE(model.DockPanel(otherStack));

        EXPECT_FALSE(model.MoveDockTab("native.tab.order.third",
                                       "native.tab.order.other",
                                       false));
        EXPECT_FALSE(model.MoveDockTab("native.tab.order.third",
                                       "native.tab.order.third",
                                       true));

        EditorDockPanelPlacement floating;
        floating.panelId = "native.tab.order.float";
        floating.area = EditorUIPanelDockArea::Floating;
        ASSERT_TRUE(model.DockPanel(floating));
        EXPECT_FALSE(model.MoveDockTab("native.tab.order.third",
                                       "native.tab.order.float",
                                       false));
    }

    TEST_F(EditorContextValidation, EditorDockingModelDetachesDockTabToFloating)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement first;
        first.panelId = "native.tab.detach.first";
        first.area = EditorUIPanelDockArea::Center;
        first.order = 10;
        first.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(first));

        EditorDockPanelPlacement second;
        second.panelId = "native.tab.detach.second";
        second.area = EditorUIPanelDockArea::Center;
        second.order = 20;
        second.tabStackId = "center.authoring";
        ASSERT_TRUE(model.DockPanel(second));
        ASSERT_TRUE(model.SetActiveDockTab("native.tab.detach.second"));

        EditorDockFloatingBounds floatingBounds;
        floatingBounds.x = 0.46f;
        floatingBounds.y = 0.22f;
        floatingBounds.width = 0.28f;
        floatingBounds.height = 0.34f;
        ASSERT_TRUE(model.DetachDockTabToFloating("native.tab.detach.first",
                                                  floatingBounds));

        const EditorDockPanelPlacement* detached =
            model.FindPlacement("native.tab.detach.first");
        ASSERT_NE(nullptr, detached);
        EXPECT_EQ(EditorUIPanelDockArea::Floating, detached->area);
        EXPECT_TRUE(detached->tabStackId.empty());
        EXPECT_TRUE(detached->hasFloatingBounds);
        EXPECT_FLOAT_EQ(0.46f, detached->floatingBounds.x);
        EXPECT_FLOAT_EQ(0.22f, detached->floatingBounds.y);
        EXPECT_FLOAT_EQ(0.28f, detached->floatingBounds.width);
        EXPECT_FLOAT_EQ(0.34f, detached->floatingBounds.height);
        EXPECT_GT(detached->floatingZOrder, 0u);
        EXPECT_EQ(1u, model.GetTabStackPanelCount("center.authoring"));
        EXPECT_EQ("native.tab.detach.second",
                  model.ResolveActiveDockTab("center.authoring"));

        ASSERT_TRUE(model.DetachDockTabToFloating("native.tab.detach.second",
                                                  floatingBounds));
        EXPECT_EQ(0u, model.GetTabStackPanelCount("center.authoring"));
        EXPECT_TRUE(model.ResolveActiveDockTab("center.authoring").empty());
        EXPECT_FALSE(model.DetachDockTabToFloating("native.tab.detach.second",
                                                   floatingBounds));
        EXPECT_FALSE(model.DetachDockTabToFloating("missing.panel", floatingBounds));

        EditorDockPanelPlacement plain;
        plain.panelId = "native.tab.detach.plain";
        plain.area = EditorUIPanelDockArea::Left;
        ASSERT_TRUE(model.DockPanel(plain));
        EXPECT_FALSE(model.DetachDockTabToFloating("native.tab.detach.plain",
                                                   floatingBounds));
    }

