    TEST_F(EditorContextValidation, EditorLayoutSerializerRoundTripsAndRejectsMalformedInput)
    {
        EditorDockingModel model;

        EditorDockPanelPlacement hierarchy;
        hierarchy.panelId = "native hierarchy";
        hierarchy.area = EditorUIPanelDockArea::Left;
        hierarchy.tabStackId = "left.authoring";
        hierarchy.normalizedSize = 0.25f;
        hierarchy.order = 2;
        hierarchy.visible = true;
        ASSERT_TRUE(model.DockPanel(hierarchy));

        EditorDockPanelPlacement inspector;
        inspector.panelId = "native.inspector";
        inspector.area = EditorUIPanelDockArea::Right;
        inspector.normalizedSize = 0.30f;
        inspector.order = 1;
        inspector.visible = false;
        ASSERT_TRUE(model.DockPanel(inspector));

        EditorDockPanelPlacement floating;
        floating.panelId = "native.floating";
        floating.area = EditorUIPanelDockArea::Floating;
        floating.normalizedSize = 0.40f;
        floating.order = 3;
        floating.visible = true;
        floating.hasFloatingBounds = true;
        floating.floatingBounds.x = 0.12f;
        floating.floatingBounds.y = 0.18f;
        floating.floatingBounds.width = 0.36f;
        floating.floatingBounds.height = 0.42f;
        floating.floatingZOrder = 7;
        ASSERT_TRUE(model.DockPanel(floating));

        EXPECT_TRUE(model.SetDockAreaSize(EditorUIPanelDockArea::Left, 0.31f));
        EXPECT_TRUE(model.SetDockAreaSize(EditorUIPanelDockArea::Right, 0.27f));
        EXPECT_TRUE(model.SetDockAreaSize(EditorUIPanelDockArea::Bottom, 0.33f));
        EXPECT_TRUE(model.SetDockAreaCollapsed(EditorUIPanelDockArea::Bottom,
                                               true));

        const std::string serialized = EditorLayoutSerializer::Serialize(model);
        EXPECT_NE(std::string::npos, serialized.find("RenderVerseXEditorLayout 6"));
        EXPECT_NE(std::string::npos, serialized.find("areas 0.310000 0.270000 0.330000"));
        EXPECT_NE(std::string::npos, serialized.find("drawer Bottom 1"));
        EXPECT_NE(std::string::npos, serialized.find("native%20hierarchy"));
        EXPECT_NE(std::string::npos, serialized.find("left.authoring"));
        EXPECT_NE(std::string::npos,
                  serialized.find("tabstack left.authoring native%20hierarchy"));
        EXPECT_NE(std::string::npos,
                  serialized.find("native.floating Floating 0.400000 3 1 1 "
                                  "0.120000 0.180000 0.360000 0.420000 7"));

        EditorDockingModel restored;
        std::string error = "not cleared";
        ASSERT_TRUE(EditorLayoutSerializer::Deserialize(serialized, restored, &error)) << error;
        EXPECT_TRUE(error.empty());
        EXPECT_FLOAT_EQ(0.31f,
                        restored.GetDockAreaSize(EditorUIPanelDockArea::Left));
        EXPECT_FLOAT_EQ(0.27f,
                        restored.GetDockAreaSize(EditorUIPanelDockArea::Right));
        EXPECT_FLOAT_EQ(0.33f,
                        restored.GetDockAreaSize(EditorUIPanelDockArea::Bottom));
        EXPECT_TRUE(restored.IsDockAreaCollapsed(EditorUIPanelDockArea::Bottom));
        ASSERT_NE(nullptr, restored.FindPlacement("native hierarchy"));
        EXPECT_EQ(EditorUIPanelDockArea::Left,
                  restored.FindPlacement("native hierarchy")->area);
        EXPECT_EQ("left.authoring",
                  restored.FindPlacement("native hierarchy")->tabStackId);
        EXPECT_EQ("native hierarchy",
                  restored.ResolveActiveDockTab("left.authoring"));
        EXPECT_FLOAT_EQ(0.25f, restored.FindPlacement("native hierarchy")->normalizedSize);
        ASSERT_NE(nullptr, restored.FindPlacement("native.inspector"));
        EXPECT_FALSE(restored.FindPlacement("native.inspector")->visible);
        ASSERT_NE(nullptr, restored.FindPlacement("native.floating"));
        EXPECT_TRUE(restored.FindPlacement("native.floating")->hasFloatingBounds);
        EXPECT_FLOAT_EQ(0.12f,
                        restored.FindPlacement("native.floating")->floatingBounds.x);
        EXPECT_FLOAT_EQ(0.18f,
                        restored.FindPlacement("native.floating")->floatingBounds.y);
        EXPECT_FLOAT_EQ(0.36f,
                        restored.FindPlacement("native.floating")->floatingBounds.width);
        EXPECT_FLOAT_EQ(0.42f,
                        restored.FindPlacement("native.floating")->floatingBounds.height);
        EXPECT_EQ(7u, restored.FindPlacement("native.floating")->floatingZOrder);

        const std::filesystem::path layoutPath =
            MakeTempScenePath("RVX_EditorLayoutSerializerRoundTrip.layout");
        RemoveFile(layoutPath);
        ASSERT_TRUE(EditorLayoutSerializer::SaveToFile(model, layoutPath, &error)) << error;

        EditorDockingModel fileRestored;
        ASSERT_TRUE(EditorLayoutSerializer::LoadFromFile(layoutPath, fileRestored, &error))
            << error;
        ASSERT_NE(nullptr, fileRestored.FindPlacement("native.inspector"));
        EXPECT_EQ(EditorUIPanelDockArea::Right,
                  fileRestored.FindPlacement("native.inspector")->area);
        EXPECT_FLOAT_EQ(0.31f,
                        fileRestored.GetDockAreaSize(EditorUIPanelDockArea::Left));
        EXPECT_TRUE(fileRestored.IsDockAreaCollapsed(EditorUIPanelDockArea::Bottom));
        EXPECT_EQ("native hierarchy",
                  fileRestored.ResolveActiveDockTab("left.authoring"));
        ASSERT_NE(nullptr, fileRestored.FindPlacement("native.floating"));
        EXPECT_TRUE(fileRestored.FindPlacement("native.floating")->hasFloatingBounds);
        EXPECT_EQ(7u, fileRestored.FindPlacement("native.floating")->floatingZOrder);
        RemoveFile(layoutPath);

        EditorDockingModel preserved;
        EditorDockPanelPlacement existing;
        existing.panelId = "existing";
        existing.area = EditorUIPanelDockArea::Bottom;
        ASSERT_TRUE(preserved.DockPanel(existing));
        EXPECT_FALSE(EditorLayoutSerializer::Deserialize(
            "RenderVerseXEditorLayout 1\npanel broken Unknown 0.500000 0 1\n",
            preserved,
            &error));
        EXPECT_FALSE(error.empty());
        ASSERT_NE(nullptr, preserved.FindPlacement("existing"));
        EXPECT_EQ(EditorUIPanelDockArea::Bottom,
                  preserved.FindPlacement("existing")->area);
    }

    TEST_F(EditorContextValidation,
           EditorLayoutPersistenceServiceLoadsMissingSavesAndRestoresNativeLayout)
    {
        const auto root = MakeTempScenePath("rvx_editor_layout_persistence");
        RemoveDirectory(root);

        const std::filesystem::path settingsPath =
            root / "Config" / "EditorSettings.json";
        EditorSettingsService settings(settingsPath);
        ASSERT_TRUE(settings.Load()) << settings.GetLastError();

        const std::filesystem::path layoutPath =
            root / "Config" / "EditorLayout.layout";
        EXPECT_EQ(layoutPath,
                  EditorLayoutPersistenceService::ResolveDefaultLayoutPath(
                      settings));

        NativeEditorUIBackend backend;
        NativeEditorUIBackendDesc backendDesc;
        backendDesc.host.surfaceWidth = 800;
        backendDesc.host.surfaceHeight = 480;
        backendDesc.host.scaleFactor = 1.0f;
        backendDesc.host.debugName =
            "EditorContextValidation.LayoutPersistence";
        ASSERT_TRUE(backend.Initialize(backendDesc));
        ASSERT_NE(nullptr, backend.GetHost());

        EditorLayoutPersistenceService service;
        EditorLayoutPersistenceDesc desc;
        desc.settingsService = &settings;
        desc.uiBackend = &backend;

        const EditorLayoutPersistenceResult missingLoad =
            service.LoadStartupLayout(desc);
        EXPECT_TRUE(missingLoad);
        EXPECT_TRUE(missingLoad.skipped);
        EXPECT_TRUE(missingLoad.missingLayout);
        EXPECT_FALSE(missingLoad.attempted);
        EXPECT_EQ(layoutPath, missingLoad.layoutPath);

        EditorDockPanelPlacement placement;
        placement.panelId = "native.persisted";
        placement.area = EditorUIPanelDockArea::Right;
        placement.normalizedSize = 0.42f;
        placement.order = 12;
        placement.visible = false;
        ASSERT_TRUE(backend.GetHost()->GetDockingModel().DockPanel(placement));
        backend.GetHost()->SetBottomDrawerCollapsed(true);

        const EditorLayoutPersistenceResult saved =
            service.SaveShutdownLayout(desc);
        EXPECT_TRUE(saved) << saved.error;
        EXPECT_TRUE(saved.attempted);
        EXPECT_TRUE(saved.succeeded);
        EXPECT_TRUE(std::filesystem::exists(layoutPath));
        const std::string savedLayout = ReadTextFile(layoutPath);
        EXPECT_NE(std::string::npos, savedLayout.find("drawer Bottom 1"));
        EXPECT_NE(std::string::npos, savedLayout.find("native.persisted"));
        backend.Shutdown();

        NativeEditorUIBackend restoredBackend;
        ASSERT_TRUE(restoredBackend.Initialize(backendDesc));
        EditorLayoutPersistenceDesc restoreDesc;
        restoreDesc.settingsService = &settings;
        restoreDesc.uiBackend = &restoredBackend;
        const EditorLayoutPersistenceResult restored =
            service.LoadStartupLayout(restoreDesc);
        EXPECT_TRUE(restored) << restored.error;
        EXPECT_TRUE(restored.attempted);
        EXPECT_TRUE(restored.succeeded);
        EXPECT_TRUE(restoredBackend.GetHost()->IsBottomDrawerCollapsed());
        const EditorDockPanelPlacement* restoredPlacement =
            restoredBackend.GetHost()
                ->GetDockingModel()
                .FindPlacement("native.persisted");
        ASSERT_NE(nullptr, restoredPlacement);
        EXPECT_EQ(EditorUIPanelDockArea::Right, restoredPlacement->area);
        EXPECT_FALSE(restoredPlacement->visible);
        restoredBackend.Shutdown();

        WriteTextFile(layoutPath, "broken editor layout");
        NativeEditorUIBackend badBackend;
        ASSERT_TRUE(badBackend.Initialize(backendDesc));
        const EditorLayoutPersistenceResult badLoad =
            service.LoadStartupLayout({&settings, &badBackend});
        EXPECT_FALSE(badLoad);
        EXPECT_TRUE(badLoad.attempted);
        EXPECT_FALSE(badLoad.error.empty());
        EXPECT_FALSE(badBackend.GetHost()->IsBottomDrawerCollapsed());
        badBackend.Shutdown();

        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation,
           EditorCommandBindingServiceSavesAndReloadsNativeLayout)
    {
        const auto root = MakeTempScenePath("rvx_editor_layout_command_binding");
        RemoveDirectory(root);

        const std::filesystem::path settingsPath =
            root / "Config" / "EditorSettings.json";
        EditorSettingsService settings(settingsPath);
        ASSERT_TRUE(settings.Load()) << settings.GetLastError();
        const std::filesystem::path layoutPath =
            EditorLayoutPersistenceService::ResolveDefaultLayoutPath(settings);

        NativeEditorUIBackend backend;
        NativeEditorUIBackendDesc backendDesc;
        backendDesc.host.surfaceWidth = 800;
        backendDesc.host.surfaceHeight = 480;
        backendDesc.host.scaleFactor = 1.0f;
        backendDesc.host.debugName =
            "EditorContextValidation.LayoutCommandBinding";
        ASSERT_TRUE(backend.Initialize(backendDesc));
        ASSERT_NE(nullptr, backend.GetHost());
        ASSERT_NE(nullptr, backend.GetCommandRegistry());

        EditorNotificationService notifications;
        EditorCommandExecutionService commands;
        commands.SetNotificationService(&notifications);
        EditorLayoutPersistenceService layoutPersistence;
        EditorCommandBindingService bindings;
        bindings.SetCommandExecutionService(&commands);
        bindings.SetUIBackend(&backend);
        bindings.SetSettingsService(&settings);
        bindings.SetLayoutPersistenceService(&layoutPersistence);
        ASSERT_TRUE(bindings.RegisterBuiltInCommands(
            *backend.GetCommandRegistry()));

        EditorCommandContext commandContext;
        backend.GetHost()->SetBottomDrawerCollapsed(true);
        EXPECT_TRUE(backend.GetCommandRegistry()->ExecuteCommand(
            EditorCommandIds::ViewSaveLayout,
            commandContext));
        EXPECT_EQ(EditorCommandActionStatus::Succeeded,
                  commands.GetLastResult().status);
        EXPECT_TRUE(layoutPersistence.GetStats().lastSave.succeeded);
        EXPECT_TRUE(std::filesystem::exists(layoutPath));
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Success,
                  notifications.GetLatest()->severity);

        backend.GetHost()->SetBottomDrawerCollapsed(false);
        EXPECT_FALSE(backend.GetHost()->IsBottomDrawerCollapsed());
        EXPECT_TRUE(backend.GetCommandRegistry()->ExecuteCommand(
            EditorCommandIds::ViewReloadLayout,
            commandContext));
        EXPECT_EQ(EditorCommandActionStatus::Succeeded,
                  commands.GetLastResult().status);
        EXPECT_TRUE(layoutPersistence.GetStats().lastLoad.succeeded);
        EXPECT_TRUE(backend.GetHost()->IsBottomDrawerCollapsed());
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Success,
                  notifications.GetLatest()->severity);

        RemoveFile(layoutPath);
        backend.GetHost()->SetBottomDrawerCollapsed(false);
        EXPECT_TRUE(backend.GetCommandRegistry()->ExecuteCommand(
            EditorCommandIds::ViewReloadLayout,
            commandContext));
        EXPECT_EQ(EditorCommandActionStatus::Deferred,
                  commands.GetLastResult().status);
        EXPECT_TRUE(layoutPersistence.GetStats().lastLoad.missingLayout);
        ASSERT_NE(nullptr, notifications.GetLatest());
        EXPECT_EQ(EditorNotificationSeverity::Info,
                  notifications.GetLatest()->severity);
        EXPECT_FALSE(backend.GetHost()->IsBottomDrawerCollapsed());

        backend.Shutdown();
        RemoveDirectory(root);
    }

    TEST_F(EditorContextValidation, EditorWorkspaceLayoutPolicyDefinesProductionDefaultStacks)
    {
        EditorWorkspaceLayoutPolicy policy;
        const EditorWorkspaceLayoutPreset preset = policy.GetDefaultPreset();

        EXPECT_FLOAT_EQ(0.20f, preset.areaSizing.leftWidthRatio);
        EXPECT_FLOAT_EQ(0.24f, preset.areaSizing.rightWidthRatio);
        EXPECT_FLOAT_EQ(0.28f, preset.areaSizing.bottomHeightRatio);
        EXPECT_EQ("workspace.left.scene", preset.leftStackId);
        EXPECT_EQ("workspace.right.details", preset.rightStackId);
        EXPECT_EQ("workspace.bottom.drawer", preset.bottomDrawerStackId);

        auto makeDesc = [](std::string id,
                           EditorUIPanelDockArea area) {
            EditorUIPanelDesc desc;
            desc.id = std::move(id);
            desc.title = desc.id;
            desc.defaultDockArea = area;
            desc.visibleByDefault = true;
            return desc;
        };

        const EditorDockPanelPlacement viewport =
            policy.BuildDefaultPlacement(makeDesc("native.viewport",
                                                  EditorUIPanelDockArea::Center),
                                         true,
                                         42u);
        EXPECT_EQ(EditorUIPanelDockArea::Center, viewport.area);
        EXPECT_TRUE(viewport.tabStackId.empty());
        EXPECT_EQ(10u, viewport.order);

        const EditorDockPanelPlacement hierarchy =
            policy.BuildDefaultPlacement(makeDesc("native.sceneHierarchy",
                                                  EditorUIPanelDockArea::Left),
                                         true,
                                         42u);
        EXPECT_EQ(preset.leftStackId, hierarchy.tabStackId);
        EXPECT_EQ(100u, hierarchy.order);

        const EditorDockPanelPlacement inspector =
            policy.BuildDefaultPlacement(makeDesc("native.inspector",
                                                  EditorUIPanelDockArea::Right),
                                         true,
                                         42u);
        EXPECT_EQ(preset.rightStackId, inspector.tabStackId);
        EXPECT_EQ(100u, inspector.order);

        const EditorDockPanelPlacement console =
            policy.BuildDefaultPlacement(makeDesc("native.console",
                                                  EditorUIPanelDockArea::Bottom),
                                         true,
                                         42u);
        EXPECT_EQ(preset.bottomDrawerStackId, console.tabStackId);
        EXPECT_EQ(120u, console.order);

        const EditorDockPanelPlacement unknownBottom =
            policy.BuildDefaultPlacement(makeDesc("native.customProfiler",
                                                  EditorUIPanelDockArea::Bottom),
                                         true,
                                         9u);
        EXPECT_TRUE(unknownBottom.tabStackId.empty());
        EXPECT_EQ(109u, unknownBottom.order);
    }

    TEST_F(EditorContextValidation, EditorUIHostUsesWorkspacePolicyForDefaultNativeLayout)
    {
        class WorkspacePanel final : public IEditorUIPanel
        {
        public:
            WorkspacePanel(std::string id,
                           EditorUIPanelDockArea area,
                           bool visibleByDefault = true)
            {
                desc.id = std::move(id);
                desc.title = desc.id;
                desc.defaultDockArea = area;
                desc.visibleByDefault = visibleByDefault;
                desc.closable = true;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }
            void BuildUI(EditorUIPanelFrameContext& context) override { (void)context; }

            EditorUIPanelDesc desc;
        };

        EditorUIHost host;
        EditorUIHostDesc hostDesc;
        hostDesc.surfaceWidth = 1280;
        hostDesc.surfaceHeight = 720;
        ASSERT_TRUE(host.Initialize(hostDesc));

        const EditorWorkspaceLayoutPolicy policy;
        const EditorWorkspaceLayoutPreset preset = policy.GetDefaultPreset();
        EXPECT_FLOAT_EQ(preset.areaSizing.leftWidthRatio,
                        host.GetDockingModel().GetDockAreaSize(EditorUIPanelDockArea::Left));
        EXPECT_FLOAT_EQ(preset.areaSizing.rightWidthRatio,
                        host.GetDockingModel().GetDockAreaSize(EditorUIPanelDockArea::Right));
        EXPECT_FLOAT_EQ(preset.areaSizing.bottomHeightRatio,
                        host.GetDockingModel().GetDockAreaSize(EditorUIPanelDockArea::Bottom));

        host.RegisterPanel(std::make_shared<WorkspacePanel>(
            "native.viewport",
            EditorUIPanelDockArea::Center));
        host.RegisterPanel(std::make_shared<WorkspacePanel>(
            "native.sceneHierarchy",
            EditorUIPanelDockArea::Left));
        host.RegisterPanel(std::make_shared<WorkspacePanel>(
            "native.inspector",
            EditorUIPanelDockArea::Right));
        host.RegisterPanel(std::make_shared<WorkspacePanel>(
            "native.assetBrowser",
            EditorUIPanelDockArea::Bottom));
        host.RegisterPanel(std::make_shared<WorkspacePanel>(
            "native.console",
            EditorUIPanelDockArea::Bottom));
        host.RegisterPanel(std::make_shared<WorkspacePanel>(
            "native.commandHistory",
            EditorUIPanelDockArea::Bottom,
            false));

        const EditorDockingModel& layout = host.GetDockingModel();
        ASSERT_NE(nullptr, layout.FindPlacement("native.viewport"));
        EXPECT_TRUE(layout.FindPlacement("native.viewport")->tabStackId.empty());
        ASSERT_NE(nullptr, layout.FindPlacement("native.sceneHierarchy"));
        EXPECT_EQ(preset.leftStackId,
                  layout.FindPlacement("native.sceneHierarchy")->tabStackId);
        ASSERT_NE(nullptr, layout.FindPlacement("native.inspector"));
        EXPECT_EQ(preset.rightStackId,
                  layout.FindPlacement("native.inspector")->tabStackId);
        ASSERT_NE(nullptr, layout.FindPlacement("native.assetBrowser"));
        ASSERT_NE(nullptr, layout.FindPlacement("native.console"));
        EXPECT_EQ(preset.bottomDrawerStackId,
                  layout.FindPlacement("native.assetBrowser")->tabStackId);
        EXPECT_EQ(preset.bottomDrawerStackId,
                  layout.FindPlacement("native.console")->tabStackId);
        EXPECT_EQ(2u, layout.GetTabStackPanelCount(preset.bottomDrawerStackId));
        EXPECT_EQ("native.assetBrowser",
                  layout.ResolveActiveDockTab(preset.bottomDrawerStackId));

        host.SetPanelVisible("native.commandHistory", true);
        EXPECT_EQ(3u, layout.GetTabStackPanelCount(preset.bottomDrawerStackId));
        EXPECT_EQ("native.assetBrowser",
                  layout.ResolveActiveDockTab(preset.bottomDrawerStackId));

        host.ResetLayout();
        EXPECT_EQ(preset.bottomDrawerStackId,
                  layout.FindPlacement("native.assetBrowser")->tabStackId);
        EXPECT_EQ(2u, layout.GetTabStackPanelCount(preset.bottomDrawerStackId));
        EXPECT_FALSE(host.IsPanelVisible("native.commandHistory"));

        host.Shutdown();
    }

    TEST_F(EditorContextValidation, EditorUIHostCollapsesBottomDrawerToTabStrip)
    {
        class WorkspacePanel final : public IEditorUIPanel
        {
        public:
            WorkspacePanel(std::string id,
                           EditorUIPanelDockArea area)
            {
                desc.id = std::move(id);
                desc.title = desc.id;
                desc.defaultDockArea = area;
                desc.visibleByDefault = true;
                desc.closable = true;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }
            void BuildUI(EditorUIPanelFrameContext& context) override
            {
                lastPanelBounds = context.panelBounds;
                lastContentBounds = context.contentBounds;
                ++buildCount;
            }

            EditorUIPanelDesc desc;
            UI::Rect lastPanelBounds;
            UI::Rect lastContentBounds;
            uint32 buildCount = 0;
        };

        EditorUIHost host;
        EditorUIHostDesc hostDesc;
        hostDesc.surfaceWidth = 1280;
        hostDesc.surfaceHeight = 720;
        ASSERT_TRUE(host.Initialize(hostDesc));
        EditorCommandCatalogCallbacks commandCallbacks;
        ASSERT_TRUE(RegisterEditorCommandCatalog(host.GetCommandRegistry(),
                                                 commandCallbacks));
        auto drawerCommand = [&host]() -> const EditorCommand* {
            return host.GetCommandRegistry().FindCommand(
                EditorCommandIds::ViewToggleBottomDrawer);
        };
        ASSERT_NE(nullptr, drawerCommand());
        EXPECT_TRUE(drawerCommand()->desc.checkable);
        EXPECT_FALSE(drawerCommand()->desc.checked);

        auto center = std::make_shared<WorkspacePanel>(
            "native.viewport",
            EditorUIPanelDockArea::Center);
        auto assets = std::make_shared<WorkspacePanel>(
            "native.assetBrowser",
            EditorUIPanelDockArea::Bottom);
        auto console = std::make_shared<WorkspacePanel>(
            "native.console",
            EditorUIPanelDockArea::Bottom);
        host.RegisterPanel(center);
        host.RegisterPanel(assets);
        host.RegisterPanel(console);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 1280;
        frameDesc.surfaceHeight = 720;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        const EditorPanelSurfaceRenderStats expandedStats =
            host.GetPanelSurfaceRenderer().GetLastBuildStats();
        EXPECT_FALSE(expandedStats.bottomAreaCollapsed);
        EXPECT_GT(expandedStats.bottomAreaHeight, expandedStats.titleBarHeight * 3.0f);
        EXPECT_GE(expandedStats.panelChromeIconButtonCount, 2u);
        UI::Widget::Ptr expandedToggleWidget =
            host.GetUIContext().GetCanvas().FindWidget(
                "Editor.PanelSurface.BottomDrawer.Toggle");
        ASSERT_NE(nullptr, expandedToggleWidget);
        std::shared_ptr<EditorIconButton> expandedToggle =
            std::dynamic_pointer_cast<EditorIconButton>(expandedToggleWidget);
        ASSERT_NE(nullptr, expandedToggle);
        EXPECT_EQ("chevron-down", expandedToggle->GetIconName());
        EXPECT_EQ("Collapse bottom drawer", expandedToggle->GetText());
        EXPECT_FALSE(expandedToggle->GetShowText());
        EXPECT_EQ("Collapse bottom drawer", expandedToggle->GetTooltipText());
        const float expandedCenterHeight = center->lastPanelBounds.height;
        const float expandedBottomHeight = assets->lastPanelBounds.height;
        ASSERT_GT(expandedBottomHeight, expandedStats.titleBarHeight * 3.0f);

        auto clickWidget = [&host](const UI::Widget::Ptr& widget) {
            ASSERT_NE(nullptr, widget);
            const UI::Rect rect = widget->GetGlobalRect();
            const float scale = host.GetUIContext().GetScaleFactor();
            UI::UIEvent mouseDown;
            mouseDown.type = UI::UIEventType::MouseDown;
            const Vec2 center = rect.Center();
            mouseDown.position = Vec2(center.x * scale, center.y * scale);
            mouseDown.button = static_cast<int>(UI::UIMouseButton::Left);
            EXPECT_TRUE(host.GetUIContext().GetCanvas().HandleEvent(mouseDown));
            UI::UIEvent mouseUp = mouseDown;
            mouseUp.type = UI::UIEventType::MouseUp;
            EXPECT_TRUE(host.GetUIContext().GetCanvas().HandleEvent(mouseUp));
        };
        clickWidget(expandedToggleWidget);
        EXPECT_TRUE(host.IsBottomDrawerCollapsed());
        ASSERT_NE(nullptr, drawerCommand());
        EXPECT_TRUE(drawerCommand()->desc.checked);
        host.BuildPanels();

        const EditorPanelSurfaceRenderStats collapsedStats =
            host.GetPanelSurfaceRenderer().GetLastBuildStats();
        EXPECT_TRUE(collapsedStats.bottomAreaCollapsed);
        EXPECT_LT(collapsedStats.bottomAreaHeight, expandedBottomHeight);
        EXPECT_NEAR(collapsedStats.titleBarHeight + 2.0f,
                    collapsedStats.bottomAreaHeight,
                    0.01f);
        EXPECT_GT(center->lastPanelBounds.height, expandedCenterHeight);
        EXPECT_LE(assets->lastContentBounds.height, 2.0f);
        EXPECT_EQ(1u, collapsedStats.bottomDrawerToggleCount);
        EXPECT_GE(collapsedStats.panelChromeIconButtonCount, 2u);
        UI::Widget::Ptr collapsedToggleWidget =
            host.GetUIContext().GetCanvas().FindWidget(
                "Editor.PanelSurface.BottomDrawer.Toggle");
        ASSERT_NE(nullptr, collapsedToggleWidget);
        std::shared_ptr<EditorIconButton> collapsedToggle =
            std::dynamic_pointer_cast<EditorIconButton>(collapsedToggleWidget);
        ASSERT_NE(nullptr, collapsedToggle);
        EXPECT_EQ("chevron-up", collapsedToggle->GetIconName());
        EXPECT_EQ("Expand bottom drawer", collapsedToggle->GetText());
        EXPECT_FALSE(collapsedToggle->GetShowText());
        EXPECT_EQ("Expand bottom drawer", collapsedToggle->GetTooltipText());

        clickWidget(collapsedToggleWidget);
        EXPECT_FALSE(host.IsBottomDrawerCollapsed());
        ASSERT_NE(nullptr, drawerCommand());
        EXPECT_FALSE(drawerCommand()->desc.checked);
        host.BuildPanels();
        EXPECT_FALSE(host.GetPanelSurfaceRenderer()
                         .GetLastBuildStats()
                         .bottomAreaCollapsed);

        host.EndFrame();
        host.Shutdown();
    }

    TEST_F(EditorContextValidation, EditorUIHostLoadsSavesAndResetsNativeDockLayout)
    {
        class LayoutPanel final : public IEditorUIPanel
        {
        public:
            LayoutPanel()
            {
                desc.id = "native.layout";
                desc.title = "Native Layout";
                desc.defaultDockArea = EditorUIPanelDockArea::Bottom;
                desc.visibleByDefault = true;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }
            void BuildUI(EditorUIPanelFrameContext& context) override { (void)context; }

            EditorUIPanelDesc desc;
        };

        EditorDockingModel storedLayout;
        EditorDockPanelPlacement storedPlacement;
        storedPlacement.panelId = "native.layout";
        storedPlacement.area = EditorUIPanelDockArea::Right;
        storedPlacement.normalizedSize = 0.42f;
        storedPlacement.order = 7;
        storedPlacement.visible = false;
        ASSERT_TRUE(storedLayout.DockPanel(storedPlacement));
        ASSERT_TRUE(storedLayout.SetDockAreaCollapsed(EditorUIPanelDockArea::Bottom,
                                                      true));

        const std::filesystem::path layoutPath =
            MakeTempScenePath("RVX_EditorUIHostNativeDockLayout.layout");
        RemoveFile(layoutPath);
        std::string error;
        ASSERT_TRUE(EditorLayoutSerializer::SaveToFile(storedLayout, layoutPath, &error))
            << error;

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 640;
        desc.surfaceHeight = 360;
        ASSERT_TRUE(host.Initialize(desc));
        EditorCommandCatalogCallbacks commandCallbacks;
        ASSERT_TRUE(RegisterEditorCommandCatalog(host.GetCommandRegistry(),
                                                 commandCallbacks));
        auto drawerCommand = [&host]() -> const EditorCommand* {
            return host.GetCommandRegistry().FindCommand(
                EditorCommandIds::ViewToggleBottomDrawer);
        };
        ASSERT_NE(nullptr, drawerCommand());
        EXPECT_FALSE(drawerCommand()->desc.checked);
        ASSERT_TRUE(host.LoadLayout(layoutPath, &error)) << error;
        EXPECT_TRUE(host.IsBottomDrawerCollapsed());
        ASSERT_NE(nullptr, drawerCommand());
        EXPECT_TRUE(drawerCommand()->desc.checked);

        auto panel = std::make_shared<LayoutPanel>();
        host.RegisterPanel(panel);

        ASSERT_NE(nullptr, host.GetDockingModel().FindPlacement("native.layout"));
        EXPECT_EQ(EditorUIPanelDockArea::Right,
                  host.GetDockingModel().FindPlacement("native.layout")->area);
        EXPECT_FLOAT_EQ(0.42f,
                        host.GetDockingModel().FindPlacement("native.layout")->normalizedSize);
        EXPECT_FALSE(host.IsPanelVisible("native.layout"));

        const std::filesystem::path savedPath =
            MakeTempScenePath("RVX_EditorUIHostNativeDockLayoutSaved.layout");
        RemoveFile(savedPath);
        ASSERT_TRUE(host.SaveLayout(savedPath, &error)) << error;

        EditorDockingModel savedLayout;
        ASSERT_TRUE(EditorLayoutSerializer::LoadFromFile(savedPath, savedLayout, &error))
            << error;
        ASSERT_NE(nullptr, savedLayout.FindPlacement("native.layout"));
        EXPECT_FALSE(savedLayout.FindPlacement("native.layout")->visible);
        EXPECT_TRUE(savedLayout.IsDockAreaCollapsed(EditorUIPanelDockArea::Bottom));

        host.ResetLayout();
        ASSERT_NE(nullptr, host.GetDockingModel().FindPlacement("native.layout"));
        EXPECT_EQ(EditorUIPanelDockArea::Bottom,
                  host.GetDockingModel().FindPlacement("native.layout")->area);
        EXPECT_TRUE(host.IsPanelVisible("native.layout"));
        EXPECT_FALSE(host.IsBottomDrawerCollapsed());
        ASSERT_NE(nullptr, drawerCommand());
        EXPECT_FALSE(drawerCommand()->desc.checked);

        host.Shutdown();

        NativeEditorUIBackend backend;
        NativeEditorUIBackendDesc backendDesc;
        backendDesc.host.surfaceWidth = 640;
        backendDesc.host.surfaceHeight = 360;
        backendDesc.host.scaleFactor = 1.0f;
        backendDesc.host.debugName =
            "EditorContextValidation.LayoutCommandState";
        ASSERT_TRUE(backend.Initialize(backendDesc));
        ASSERT_NE(nullptr, backend.GetHost());
        ASSERT_TRUE(backend.GetHost()->LoadLayout(layoutPath, &error)) << error;
        EXPECT_TRUE(backend.GetHost()->IsBottomDrawerCollapsed());

        EditorCommandBindingService bindings;
        bindings.SetUIBackend(&backend);
        ASSERT_NE(nullptr, backend.GetCommandRegistry());
        ASSERT_TRUE(
            bindings.RegisterBuiltInCommands(*backend.GetCommandRegistry()));
        const EditorCommand* lateDrawerCommand =
            backend.GetCommandRegistry()->FindCommand(
                EditorCommandIds::ViewToggleBottomDrawer);
        ASSERT_NE(nullptr, lateDrawerCommand);
        EXPECT_TRUE(lateDrawerCommand->desc.checked);
        backend.Shutdown();

        RemoveFile(layoutPath);
        RemoveFile(savedPath);
    }

    TEST_F(EditorContextValidation, EditorPanelSurfaceRendererUsesDockOrderAndNormalizedSizes)
    {
        class LayoutProbePanel final : public IEditorUIPanel
        {
        public:
            LayoutProbePanel(std::string id, std::string title)
            {
                desc.id = std::move(id);
                desc.title = std::move(title);
                desc.defaultDockArea = EditorUIPanelDockArea::Left;
                desc.visibleByDefault = true;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }
            void BuildUI(EditorUIPanelFrameContext& context) override
            {
                lastPanelBounds = context.panelBounds;
                lastContentBounds = context.contentBounds;
                ++buildCount;
            }

            EditorUIPanelDesc desc;
            UI::Rect lastPanelBounds;
            UI::Rect lastContentBounds;
            uint32 buildCount = 0;
        };

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 1000;
        desc.surfaceHeight = 600;
        ASSERT_TRUE(host.Initialize(desc));

        EditorDockPanelPlacement smallPlacement;
        smallPlacement.panelId = "native.layout.small";
        smallPlacement.area = EditorUIPanelDockArea::Left;
        smallPlacement.normalizedSize = 0.25f;
        smallPlacement.order = 10;
        smallPlacement.visible = true;
        ASSERT_TRUE(host.GetDockingModel().DockPanel(smallPlacement));

        EditorDockPanelPlacement largePlacement;
        largePlacement.panelId = "native.layout.large";
        largePlacement.area = EditorUIPanelDockArea::Left;
        largePlacement.normalizedSize = 0.75f;
        largePlacement.order = 20;
        largePlacement.visible = true;
        ASSERT_TRUE(host.GetDockingModel().DockPanel(largePlacement));

        auto largePanel =
            std::make_shared<LayoutProbePanel>("native.layout.large", "Large");
        auto smallPanel =
            std::make_shared<LayoutProbePanel>("native.layout.small", "Small");
        host.RegisterPanel(largePanel);
        host.RegisterPanel(smallPanel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 1000;
        frameDesc.surfaceHeight = 600;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        EXPECT_EQ(1u, smallPanel->buildCount);
        EXPECT_EQ(1u, largePanel->buildCount);
        const EditorPanelSurfaceRenderStats& surfaceStats =
            host.GetPanelSurfaceRenderer().GetLastBuildStats();
        EXPECT_EQ(2u, surfaceStats.panelFrameCount);
        EXPECT_EQ(2u, surfaceStats.leftPanelCount);

        EXPECT_NEAR(surfaceStats.workArea.y, smallPanel->lastPanelBounds.y, 0.01f);
        EXPECT_NEAR(smallPanel->lastPanelBounds.Bottom(),
                    largePanel->lastPanelBounds.y,
                    0.01f);
        EXPECT_NEAR(surfaceStats.workArea.height * 0.25f,
                    smallPanel->lastPanelBounds.height,
                    0.01f);
        EXPECT_NEAR(surfaceStats.workArea.height * 0.75f,
                    largePanel->lastPanelBounds.height,
                    0.01f);
        EXPECT_NEAR(smallPanel->lastPanelBounds.width,
                    largePanel->lastPanelBounds.width,
                    0.01f);
        EXPECT_GT(smallPanel->lastContentBounds.height, 0.0f);
        EXPECT_GT(largePanel->lastContentBounds.height,
                  smallPanel->lastContentBounds.height);
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "Editor.PanelSurface.Panel.native.layout.small.Frame"));
        EXPECT_NE(nullptr,
                  host.GetUIContext().GetCanvas().FindWidget(
                      "Editor.PanelSurface.Panel.native.layout.large.Frame"));

        host.EndFrame();
        host.Shutdown();
    }

