    TEST_F(EditorContextValidation, EditorPanelSurfaceRendererBuildsFloatingPanelsByZOrder)
    {
        class FloatingProbePanel final : public IEditorUIPanel
        {
        public:
            FloatingProbePanel(std::string id, std::string title)
            {
                desc.id = std::move(id);
                desc.title = std::move(title);
                desc.defaultDockArea = EditorUIPanelDockArea::Floating;
                desc.visibleByDefault = true;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override { return desc; }
            void BuildUI(EditorUIPanelFrameContext& context) override
            {
                lastPanelBounds = context.panelBounds;
                ++buildCount;
            }

            EditorUIPanelDesc desc;
            UI::Rect lastPanelBounds;
            uint32 buildCount = 0;
        };

        EditorUIHost host;
        EditorUIHostDesc desc;
        desc.surfaceWidth = 1000;
        desc.surfaceHeight = 600;
        ASSERT_TRUE(host.Initialize(desc));

        EditorDockPanelPlacement backPlacement;
        backPlacement.panelId = "native.float.z.back";
        backPlacement.area = EditorUIPanelDockArea::Floating;
        backPlacement.visible = true;
        backPlacement.order = 1;
        backPlacement.hasFloatingBounds = true;
        backPlacement.floatingBounds.x = 0.08f;
        backPlacement.floatingBounds.y = 0.08f;
        backPlacement.floatingBounds.width = 0.36f;
        backPlacement.floatingBounds.height = 0.36f;
        backPlacement.floatingZOrder = 1;
        ASSERT_TRUE(host.GetDockingModel().DockPanel(backPlacement));

        EditorDockPanelPlacement frontPlacement;
        frontPlacement.panelId = "native.float.z.front";
        frontPlacement.area = EditorUIPanelDockArea::Floating;
        frontPlacement.visible = true;
        frontPlacement.order = 2;
        frontPlacement.hasFloatingBounds = true;
        frontPlacement.floatingBounds.x = 0.20f;
        frontPlacement.floatingBounds.y = 0.18f;
        frontPlacement.floatingBounds.width = 0.36f;
        frontPlacement.floatingBounds.height = 0.36f;
        frontPlacement.floatingZOrder = 2;
        ASSERT_TRUE(host.GetDockingModel().DockPanel(frontPlacement));

        auto frontPanel = std::make_shared<FloatingProbePanel>(
            "native.float.z.front", "Front");
        auto backPanel = std::make_shared<FloatingProbePanel>(
            "native.float.z.back", "Back");
        FloatingProbePanel* frontPanelPtr = frontPanel.get();
        FloatingProbePanel* backPanelPtr = backPanel.get();
        host.RegisterPanel(frontPanel);
        host.RegisterPanel(backPanel);

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 1000;
        frameDesc.surfaceHeight = 600;
        frameDesc.deltaTime = 0.016f;
        ASSERT_TRUE(host.BeginFrame(frameDesc));
        host.BuildPanels();

        UI::UICanvas& canvas = host.GetUIContext().GetCanvas();
        ASSERT_EQ(1u, frontPanelPtr->buildCount);
        ASSERT_EQ(1u, backPanelPtr->buildCount);
        const float overlapX =
            std::max(frontPanelPtr->lastPanelBounds.x,
                     backPanelPtr->lastPanelBounds.x) + 36.0f;
        const float overlapY =
            std::max(frontPanelPtr->lastPanelBounds.y,
                     backPanelPtr->lastPanelBounds.y) +
            host.GetPanelSurfaceRenderer().GetLastBuildStats().titleBarHeight + 36.0f;
        UI::Widget* hit = canvas.HitTest(Vec2(overlapX, overlapY));
        ASSERT_NE(nullptr, hit);
        EXPECT_NE(std::string::npos,
                  hit->GetName().find("native.float.z.front"));

        UI::Widget::Ptr backTitleBar =
            canvas.FindWidget("Editor.PanelSurface.Panel.native.float.z.back.TitleBar");
        ASSERT_NE(nullptr, backTitleBar);
        const UI::Rect backTitleRect = backTitleBar->GetGlobalRect();
        UI::UIEvent mouseDown;
        mouseDown.type = UI::UIEventType::MouseDown;
        mouseDown.position = backTitleRect.Center();
        mouseDown.button = static_cast<int>(UI::UIMouseButton::Left);
        EXPECT_TRUE(canvas.HandleEvent(mouseDown));

        UI::UIEvent mouseUp = mouseDown;
        mouseUp.type = UI::UIEventType::MouseUp;
        EXPECT_TRUE(canvas.HandleEvent(mouseUp));

        const EditorDockPanelPlacement* activatedBack =
            host.GetDockingModel().FindPlacement("native.float.z.back");
        const EditorDockPanelPlacement* activatedFront =
            host.GetDockingModel().FindPlacement("native.float.z.front");
        ASSERT_NE(nullptr, activatedBack);
        ASSERT_NE(nullptr, activatedFront);
        EXPECT_GT(activatedBack->floatingZOrder, activatedFront->floatingZOrder);

        host.BuildPanels();
        ASSERT_EQ(2u, frontPanelPtr->buildCount);
        ASSERT_EQ(2u, backPanelPtr->buildCount);
        hit = canvas.HitTest(Vec2(overlapX, overlapY));
        ASSERT_NE(nullptr, hit);
        EXPECT_NE(std::string::npos,
                  hit->GetName().find("native.float.z.back"));

        host.EndFrame();
        host.Shutdown();
    }

