        EXPECT_GE(metrics.menuBarHeight, editorTheme.metrics.controlHeight);
        EXPECT_GE(metrics.commandToolbarHeight,
                  editorTheme.metrics.toolbarHeight);
        EXPECT_GE(metrics.statusBarHeight, editorTheme.metrics.statusBarHeight);
        EXPECT_FLOAT_EQ(metrics.menuBarHeight + metrics.commandToolbarHeight,
                        metrics.topReservedHeight);
        EXPECT_FLOAT_EQ(metrics.statusBarHeight, metrics.bottomReservedHeight);

        EXPECT_GE(metrics.contentPadding, 6.0f);
        EXPECT_GE(metrics.compactGap, 5.0f);
        EXPECT_GE(metrics.statusItemGap, metrics.itemGap);
        EXPECT_GE(metrics.panelControlHeight, 28.0f);
        EXPECT_FLOAT_EQ(metrics.contentPadding + metrics.panelControlHeight +
                            metrics.contentPadding,
                        metrics.singleRowPanelToolbarHeight);
        EXPECT_GT(metrics.twoRowPanelToolbarHeight,
                  metrics.singleRowPanelToolbarHeight);
        EXPECT_GE(metrics.panelListRowHeight,
                  metrics.compactPanelListRowHeight);
        EXPECT_GE(metrics.formRowHeight, metrics.panelControlHeight);
        EXPECT_GE(metrics.formLineHeight, 26.0f);
        EXPECT_GE(metrics.pickerRowHeight, metrics.formRowHeight);
        EXPECT_GE(metrics.pickerCategoryHeight, metrics.formLineHeight);
        EXPECT_GE(metrics.dialogPadding, metrics.contentPadding);
        EXPECT_GE(metrics.dialogSpacing, metrics.itemGap);
        EXPECT_GE(metrics.dialogTitleHeight, metrics.dialogBodyLineHeight);
        EXPECT_GE(metrics.dialogControlHeight, metrics.formRowHeight);
        EXPECT_GE(metrics.panelTitleBarHeight, metrics.panelTabHeight);
        EXPECT_GE(metrics.panelChromeButtonSize, 24.0f);

        UI::UIContext context;
