    TEST_F(EditorContextValidation,
           EditorAutomationInteractionDriverValidatesCommandSurfaces)
    {
        NativeEditorUIBackend backend;
        NativeEditorUIBackendDesc desc;
        desc.host.surfaceWidth = 720;
        desc.host.surfaceHeight = 460;
        ASSERT_TRUE(backend.Initialize(desc));

        EditorCommandRegistry* registry = backend.GetCommandRegistry();
        EditorCommandSurfaceModel* surfaceModel =
            backend.GetCommandSurfaceModel();
        ASSERT_NE(nullptr, registry);
        ASSERT_NE(nullptr, surfaceModel);

        EditorCommandCatalogCallbacks callbacks;
        callbacks.openScene = []() {};
        callbacks.saveScene = []() {};
        callbacks.saveSceneAs = []() {};
        callbacks.commandPalette = []() {};
        ASSERT_TRUE(RegisterEditorCommandCatalog(*registry, callbacks));
        surfaceModel->BuildDefaultEditorSurfaces();

        EditorAutomationInteractionDriver interaction(backend);
        EXPECT_TRUE(interaction.RequireCommandRegistered(
            EditorCommandIds::FileOpenScene,
            "Open Scene command probe"));
        EXPECT_TRUE(interaction.RequireCommandEnabled(
            EditorCommandIds::FileOpenScene,
            "Open Scene enabled probe"));
        EXPECT_TRUE(interaction.RequireMenuCommandVisible(
            "file",
            EditorCommandIds::FileOpenScene,
            "Open Scene file menu probe"));
        EXPECT_TRUE(interaction.RequireToolbarCommandVisible(
            "main",
            EditorCommandIds::FileSaveScene,
            "Save Scene toolbar probe"));

        EditorUIAutomationResult missingCommand =
            interaction.RequireCommandRegistered("file.missing",
                                                 "Missing command probe");
        EXPECT_FALSE(missingCommand);
        EXPECT_NE(std::string::npos,
                  missingCommand.error.find(
                      "command 'file.missing' is not registered"));

        registry->SetCommandEnabled(EditorCommandIds::FileOpenScene, false);
        EditorUIAutomationResult disabledCommand =
            interaction.RequireCommandEnabled(EditorCommandIds::FileOpenScene,
                                              "Disabled command probe");
        EXPECT_FALSE(disabledCommand);
        EXPECT_NE(std::string::npos,
                  disabledCommand.error.find(
                      "command 'file.openScene' is disabled"));

        EditorUIAutomationResult missingMenu =
            interaction.RequireMenuCommandVisible(
                "missing",
                EditorCommandIds::FileOpenScene,
                "Missing menu probe");
        EXPECT_FALSE(missingMenu);
        EXPECT_NE(std::string::npos,
                  missingMenu.error.find(
                      "menu 'missing' is not registered"));

        EditorUIAutomationResult wrongMenu =
            interaction.RequireMenuCommandVisible(
                "view",
                EditorCommandIds::FileOpenScene,
                "Wrong menu probe");
        EXPECT_FALSE(wrongMenu);
        EXPECT_NE(std::string::npos,
                  wrongMenu.error.find(
                      "command 'file.openScene' is not visible in menu "
                      "'view'"));

        EditorUIAutomationResult missingToolbar =
            interaction.RequireToolbarCommandVisible(
                "missing",
                EditorCommandIds::FileSaveScene,
                "Missing toolbar probe");
        EXPECT_FALSE(missingToolbar);
        EXPECT_NE(std::string::npos,
                  missingToolbar.error.find(
                      "toolbar 'missing' is not registered"));

        backend.Shutdown();
    }

    TEST_F(EditorContextValidation,
           EditorAutomationScenarioRunnerClicksCommandSurfaceMenuItem)
    {
        class CommandSurfaceClickProbePanel final : public IEditorUIPanel
        {
        public:
            CommandSurfaceClickProbePanel()
            {
                m_desc.id = "automation.commandSurfaceProbe";
                m_desc.title = "Command Surface Probe";
                m_desc.defaultDockArea = EditorUIPanelDockArea::Center;
                m_desc.visibleByDefault = true;
                m_desc.closable = false;
            }

            const EditorUIPanelDesc& GetPanelDesc() const override
            {
                return m_desc;
            }

            void BuildUI(EditorUIPanelFrameContext& context) override
            {
                (void)context;
            }

        private:
            EditorUIPanelDesc m_desc;
        };

        NativeEditorUIBackend backend;
        NativeEditorUIBackendDesc desc;
        desc.host.surfaceWidth = 720;
        desc.host.surfaceHeight = 460;
        ASSERT_TRUE(backend.Initialize(desc));
        ASSERT_NE(nullptr, backend.GetHost());

        EditorCommandRegistry* registry = backend.GetCommandRegistry();
        EditorCommandSurfaceModel* surfaceModel =
            backend.GetCommandSurfaceModel();
        ASSERT_NE(nullptr, registry);
        ASSERT_NE(nullptr, surfaceModel);

        uint32 newSceneCount = 0;
        EditorCommandCatalogCallbacks callbacks;
        callbacks.newScene = [&newSceneCount]() {
            ++newSceneCount;
        };
        ASSERT_TRUE(RegisterEditorCommandCatalog(*registry, callbacks));
        surfaceModel->BuildDefaultEditorSurfaces();
        backend.GetHost()->RegisterPanel(
            std::make_shared<CommandSurfaceClickProbePanel>());

        EditorAutomationScenarioRunner runner;
        runner.Reset(EditorAutomationScenarioType::CommandSurfaceClick,
                     "file:file.newScene");
        EXPECT_TRUE(runner.HasScenario());
        EXPECT_FALSE(runner.IsComplete());

        EditorAutomationScenarioContext context;
        context.uiBackend = &backend;

        EditorUIFrameDesc frameDesc;
        frameDesc.surfaceWidth = 720;
        frameDesc.surfaceHeight = 460;
        frameDesc.deltaTime = 0.016f;

        ASSERT_TRUE(backend.BeginFrame(frameDesc));
        backend.BuildPanels();
        runner.Advance(context);
        EXPECT_FALSE(runner.HasFailed()) << runner.GetError();
        EXPECT_FALSE(runner.IsComplete());
        EXPECT_TRUE(backend.GetHost()->GetCommandSurfaceRenderer().IsMenuOpen(
            "file"));
        EXPECT_EQ(0u, newSceneCount);
        backend.EndFrame();

        ASSERT_TRUE(backend.BeginFrame(frameDesc));
        backend.BuildPanels();
        EXPECT_NE(nullptr,
                  backend.GetHost()->GetUIContext().GetCanvas().FindWidget(
                      "Editor.CommandSurface.Menu.file.Item.file.newScene"));
        runner.Advance(context);
        EXPECT_FALSE(runner.HasFailed()) << runner.GetError();
        EXPECT_TRUE(runner.IsComplete());
        EXPECT_EQ(1u, newSceneCount);
        EXPECT_FALSE(backend.GetHost()->GetCommandSurfaceRenderer().IsMenuOpen(
            "file"));

        const std::vector<EditorUICommandHistoryEntry>& history =
            backend.GetHost()->GetCommandHistory();
        ASSERT_GE(history.size(), static_cast<size_t>(2));
        EXPECT_FALSE(history[history.size() - 2u].diagnostic);
        EXPECT_EQ(EditorUICommandExecutionSource::Direct,
                  history[history.size() - 2u].source);
        EXPECT_EQ(EditorCommandIds::FileNewScene,
                  history[history.size() - 2u].result.commandId);
        EXPECT_TRUE(history[history.size() - 2u].Succeeded());
        EXPECT_TRUE(history.back().diagnostic);
        EXPECT_TRUE(history.back().diagnosticSucceeded);
        EXPECT_NE(std::string::npos,
                  history.back().diagnosticMessage.find(
                      "Clicked command surface menu item"));

        backend.EndFrame();
        backend.Shutdown();
    }

