        mouseUp.position = recentSubdir->GetGlobalRect().Center();
        EXPECT_TRUE(canvas.HandleEvent(mouseUp));
        host.BuildPanels();

        const EditorFilePickerDialogStats& recentStats =
            host.GetFilePickerDialog().GetLastBuildStats();
