        EXPECT_EQ((root / "Subdir").string(), recentStats.pathText);
        EXPECT_GE(recentStats.breadcrumbCount, 2u);
        EXPECT_EQ(2u, recentStats.recentDirectoryCount);

        const std::vector<EditorFilePickerBreadcrumb>& breadcrumbs =
            host.GetFilePickerDialog().GetModel().GetBreadcrumbs();
