        EXPECT_EQ(0u, stats.toolbarOverflowIndicatorCount);
        EXPECT_EQ(0u, stats.toolbarOverflowIndicatorClippedCount);
        EXPECT_GE(stats.statusItemCount, 2u);
        EXPECT_EQ(1u, stats.statusLeftItemCount);
        EXPECT_EQ(2u, stats.statusCenterItemCount);
        EXPECT_EQ(1u, stats.statusRightItemCount);
        const UI::UITheme& theme = host.GetUIContext().GetTheme();
